globalThis.ANDE_CHUNKS["5b3f9182feacfcfdb8dc89396ba968fa9e6a23c4de508fd29134b314da03bc14"] = [{"id":"shlab_social:7688999843491334427","sourceKey":"shlab_social","company":"上海AI实验室","title":"【高阶岗位】Agent 任务与环境青年科学家","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7688999843491334427?mode=social","duty":"1. 面向大模型 Agent 的训练与评测，负责任务、环境及交互数据的关键技术研究，推动研究原型向可规模化交付的能力转化。 \n2.  研究任务生成、环境自动构建与验证方法，建设可执行、可复现、可验证的任务环境，提升生产效率、质量与复用性。 \n3.  建设任务与环境评测体系，研究难度分级、结果校验、奖励设计及评测可靠性，形成高质量基准与自动化验证流程。 \n4.  与模型团队协作开展轨迹采集、数据合成及后训练实验，验证任务、环境和数据对 Agent 能力的实际贡献。 \n5.  独立牵引方向内的研发项目，承担需求评估、技术路线设计与交付推进，指导工程师及合作学生，参与骨干培养与团队建设。","requirements":"1.  计算机、人工智能、软件工程等相关专业，博士及以上学历。 \n2.  在 Agent、代码智能、任务环境构建、自动化评测或大模型后训练等至少一个方向具有深入研究或实践经验，并有可展示的成果。 \n3.  具备扎实的 Python 编程能力，熟悉 Linux、Docker 及常用深度学习工具，能够独立完成研究原型、实验验证及关键模块开发。 \n4.  具备较强的问题定义、实验设计与指标分析能力，能够区分模型、数据、环境及评测机制带来的问题，并通过实验验证改进效果。 \n5.  具备独立负责科研或研发项目的能力，能够拆解目标、判断优先级、协调资源并推动交付，愿意承担技术指导与团队协作职责。 \n加分项\n1.  有代码、办公、科学计算或安全等场景的 Agent 任务集、环境、Benchmark 或 Harness 建设经验。 \n2.  有大规模环境构建、沙盒运行、轨迹生产或 RLVR 实践经验，了解可复现性、评测泄漏及奖励漏洞等问题。 \n3.  有高质量论文、开源项目或实际应用成果；有带领小团队、指导学生或组织跨团队合作的经验","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7688997288136509739","sourceKey":"shlab_social","company":"上海AI实验室","title":"【高阶岗位】多模态与智能文档理解青年科学家","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7688997288136509739?mode=social","duty":"1.  负责多模态与智能文档理解关键技术研究，面向科学文献、技术报告等复杂文档，提升文本、图像、表格、公式等内容的识别、结构化与语义理解能力。 \n2.  研究文档结构建模、图文语义对齐与跨页信息关联等方法，实现从元素解析到内容理解的能力提升，支撑高质量训练语料构建与科学信息检索。 \n3.  建设训练数据与评测体系，研究数据合成、质量筛选及自动化评估方法，系统评估解析准确性、结构完整性、语义一致性与下游应用效果。 \n4.  开展多模态模型训练、适配与推理优化，与工程团队协作推动研究成果在大规模文档处理中的落地，兼顾效果、效率与稳定性。 \n5.  独立牵引方向内的研发项目，承担技术路线设计、关键问题攻关与交付推进，指导工程师及合作学生，参与骨干培养与团队建设。","requirements":"1. 计算机、人工智能、模式识别等相关专业，博士及以上学历。 \n2.  在文档智能、多模态大模型、计算机视觉或自然语言处理等至少一个方向具有深入研究或实践经验，并有可展示的成果。 \n3.  具备扎实的 Python 编程能力，熟悉 PyTorch 等深度学习框架，能够独立完成数据构建、模型训练、实验验证及关键模块开发。 \n4.  具备较强的问题定义、实验设计与误差分析能力，能够定位数据、模型及处理流程中的瓶颈，通过系统实验验证改进效果。 \n5.  具备独立负责科研或研发项目的能力，能够结合实际需求判断技术优先级，组织协作并推动成果落地，愿意承担技术指导与团队协作职责。\n加分项\n1.  有复杂版面、表格、公式、科学图表或长文档理解经验，熟悉科学文献等专业文档的处理难点。 \n2.  有多模态模型微调、强化学习、合成数据或跨模态对齐经验，或参与过大规模文档解析与数据生产系统建设。 \n3.  有高质量论文、开源项目或实际应用成果；有带领小团队、指导学生或组织跨团队合作的经验","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7688673894496880906","sourceKey":"shlab_social","company":"上海AI实验室","title":"Agent算法工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7688673894496880906?mode=social","duty":"1. 探索 AI 驱动的自主物质科学发现闭环，构建大模型驱动的材料发现与优化决策自进化智能体，推动通用材料研发 AI 新范式；\n2. 负责科学场景下 Agent 系统的设计与落地，包括任务规划、工具调用、多轮交互、记忆机制与执行轨迹管理，打通从假设生成到实验验证的完整链路；\n3. 主导大模型后训练工作，围绕材料科学垂域开展数据构建、SFT、偏好优化与强化学习训练，持续提升模型在专业任务上的表现；\n4. 构建 Agent Harness 与评测体系，搭建实验环境、轨迹采集与自动化评测框架，支撑 Agent 能力的持续迭代与自进化；\n5. 跟踪 Agent 与 AI4S 前沿进展，参与论文、开源项目与技术成果产出。","requirements":"1. 计算机科学、人工智能、自动化或相关专业硕士及以上学历，2 年以上大模型或 Agent 方向工程与研发经验；\n2. 满足如下项目中的任意一项\n2.1 具备 LLM Agent 系统的完整开发经验，独立或主导实现过 Agent 的规划、工具调用、多轮执行等核心模块，熟悉主流 Agent 框架（LangChain、AutoGen、Dify 等）；\n2.2 具备大模型后训练实操经验，独立完成过 SFT / DPO / RLHF 等训练流程，熟悉训练数据构建、清洗与质量控制，有实际调优并产生效果提升的案例；\n2.3 具备 Harness 或评测系统建设经验，做过实验平台、轨迹采集、自动化评测或 Benchmark 建设，能够将模糊的能力需求转化为可量化的评估指标；\n3. 优秀的工程能力，熟练使用 Python、PyTorch 与 Linux，具备扎实的数据结构与算法基础，能够独立完成从原型到落地的全流程实现；\n4. 熟悉 Transformer 架构，了解 Diffusion Model、强化学习、贝叶斯优化等方法中的一种或多种；\n5. 具备较强的独立问题分析与解决能力，能将开放性科研问题拆解为可实现、可验证的工程方案；\n6. 良好的沟通表达能力，能够与材料、化学等跨学科团队高效协作。\n\n加分项：\n1. 有 Self-Evolving Agent、Self-Reflection、自动化科学发现（AI Scientist）等方向的研究或工程经验；\n2. 有 AI4S 相关项目经历，或在材料、化学、生物等科学场景下的模型落地经验；\n3. 有大规模分布式训练、大模型推理优化或 Agent Infrastructure 实践经验；\n4. 在 NeurIPS、ICML、ICLR、ACL 等会议发表过相关论文，或参与过有影响力的开源项目。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7688662553580685594","sourceKey":"shlab_social","company":"上海AI实验室","title":"具身智能算法与评测工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7688662553580685594?mode=social","duty":"1. 参与WAM/VLA的后训练与评测工作；\n2. 参与RL在WAM/VLA/具身智能体等方向的研究，协助团队完成模型强化学习微调的工具链建设与评测工具开发；\n3. 或参与 Real2Sim2Real 方向研究，液体、柔体等物理仿真建模以及触觉仿真，协助推进结合传统仿真和生成式仿真的数据合成，推动合成数据价值探索与应用落地。 \n","requirements":"1、计算机、人工智能、机器人相关专业硕士及以上学历，有相关学术/项目成果者优先；\n2、擅长强化学习核心算法(如 PPO、GRPO等), 或擅长液体、柔体与触觉等仿真建模并在real2sim2real 方向有相关成果；\n3   熟悉具身VLA、WAM等模型，有如机械臂操作等真机相关经验； \n4.  熟悉至少一种主流仿真环境或框架，如Isaac Sim、 MuJoCo，熟练 Issac Lab者优先。 \n5.  在NeurIPS、ICLR、ICML、RSS、CoRL、ICRA、RAL等机器学习、机器人会议或期刊上有出色成果发表者可加分。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7688285389001689387","sourceKey":"shlab_social","company":"上海AI实验室","title":"推理服务研发工程师（后端/开源引擎方向）","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7688285389001689387?mode=social","duty":"1. 开源推理引擎二次开发与优化：深入研究主流开源推理引擎（vLLM、SGLang、TensorRT-LLM、Dynamo等），根据业务需求进行源码级二次开发、功能拓展、性能优化，修复引擎内核问题，适配公司自研模型与业务场景。\n2. 推理服务后端架构研发：负责AI推理服务的后端架构设计与开发，实现模型加载、请求调度、批处理推理、动态路由、流量管控、超时重试等核心能力，搭建标准化、可复用的推理服务底座。\n3. 推理性能专项优化：针对大模型推理的吞吐、延时、显存占用、推理速度等核心指标分析推理链路瓶颈（Gateway/Scheduler/Runtime/GPU）进行专项优化，结合业务场景优化KV缓存、动态批处理、模型量化、推理并行策略，提升单机及集群推理并发能力，降低推理部署成本。\n4. 云原生推理服务化落地：将优化后的推理引擎封装为标准化云原生服务，对接K8s集群，实现推理服务的容器化部署、弹性扩缩容、灰度发布、资源管控，保障线上服务高可用。\n5. 推理服务监控与问题迭代：基于可观测体系（Metrics/Profiling/Tracing）搭建推理服务全链路监控体系，跟踪线上推理异常、性能瓶颈、报错问题，持续迭代优化引擎与服务架构，提升推理服务稳定性与用户体验。\n6. 技术调研与方案落地：持续跟进业界开源推理技术、大模型部署新技术、新方案，开展技术调研与POC验证，输出适配业务的推理部署最优方案，推动团队技术架构升级。","requirements":"核心能力\n1. 本科及以上学历，计算机、软件工程、人工智能等相关专业，1-3年及以上AI推理后端、引擎开发、模型部署相关工作经验。\n2. 扎实的后端开发功底，熟练掌握Go/C++/Python任意一种主力开发语言，熟悉网络编程、高并发服务开发、微服务架构，具备扎实的数据结构与算法基础。\n3. 熟悉至少 1–2 种主流大模型推理引擎或框架，如 vLLM、SGLang、TensorRT-LLM、Dynamo 等，具备源码阅读、二次开发或性能调优经验；\n4. 熟悉大模型推理、量化、批处理、KV缓存、调度策略优化、PD分离、张量并行、流水线并行等核心技术，了解LLM线上部署的业务痛点与优化方向。\n5. 熟悉Docker、Kubernetes等云原生技术原理和使用，了解推理服务容器化部署、资源调度、弹性扩容基本流程，能够独立完成服务上线与运维适配。\n6. 具备独立技术调研、方案设计和问题攻坚能力，逻辑清晰，善于拆解复杂问题，有良好的团队协作和沟通能力。\n加分项\n1. 有大模型推理引擎深度优化、开源项目贡献经验；\n2. 熟悉 Prometheus/Grafana/eBPF 等可观测体系；\n3. 深入理解 KV Cache、PagedAttention、Speculative Decoding 机制，具备大规模KVCache集群管理和维护经验，熟悉缓存压缩、调度等优化策略；\n4. 有InfiniBand、RDMA等高速网络技术在推理场景中的应用经验。\n5. 有百卡级以上GPU集群的大规模分布式推理服务开发或运维经验。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7687962713473648932","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型安全强化学习青年研究员","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7687962713473648932?mode=social","duty":"1.    以强化学习为核心手段，研究和落地大模型在漏洞挖掘、代码安全分析等安全场景的应用，支撑团队“模型漏洞挖掘”等核心任务；\n2.    设计面向安全任务的 RL 训练方案，包括任务建模、环境与沙盒构建、奖励函数设计（可执行验证、PoV 等）、训练数据构造与课程学习；\n3.    将 RL 训练能力与安全工程结合，搭建漏洞挖掘 Agent / 工具链的工程化方案，持续提升漏洞挖掘的覆盖率、准确率与自动化水平；\n4.    跟进 LLM4Security 与 Agentic RL 前沿进展，探索安全场景与强化学习结合的新方向。","requirements":"1.    人工智能、计算机、软件工程、网络空间安全等相关专业硕士及以上学历，博士优先；\n2.    具备扎实的强化学习基础，熟悉 PPO、GRPO、DPO 等主流 RL 算法，有大模型训练或 RL 训练调优实践经验；\n3.    有安全背景者优先（漏洞挖掘、Fuzzing、程序分析、二进制分析、CTF 竞赛等）；\n4.    对 AI×Security 交叉方向有浓厚兴趣，学习能力强，能快速补齐安全领域知识并与安全团队高效协作；\n5.    在模型/训练技术报告中有署名成果者优先；在相关方向顶级会议（NeurIPS / ICML / ICLR，或 S&P / USENIX Security / CCS / NDSS）有成果发表者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7687962435164522793","sourceKey":"shlab_social","company":"上海AI实验室","title":"智能体强化学习青年科学家","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7687962435164522793?mode=social","duty":"1.    面向智能体场景开展强化学习前沿研究，探索长程规划、多轮交互、工具调用等 Agentic RL 的核心算法与训练范式；\n2.    构建智能体强化学习训练系统，解决复杂环境/沙盒构建、任务与奖励设计、轨迹数据管理、异步训练等关键问题，实现智能体的自主学习与持续进化；\n3.    突破复杂环境下的感知–决策闭环，提升模型的长程规划与多轮交互学习能力，将研究成果应用于模型漏洞挖掘等团队核心任务交付；\n4.    跟踪并洞察 RL / Agent 领域最新进展，产出有影响力的研究成果（论文、开源、技术报告），主导定义团队 Agentic RL 技术路线。\n","requirements":"1.    人工智能、计算机、数学等相关专业博士学历，具备扎实的深度学习与强化学习理论基础；特别优秀的应届博士/博后亦可；\n2.    深入掌握 PPO、GRPO、DPO、DAPO、GSPO 、SAO等主流大模型强化学习算法，有训练智能体的一手经验，包括但不限于Mid-train、多轮交互 RL、工具调用 RL、长程任务奖励设计等；\n3.    熟悉至少一种主流 RL 训练框架（如 veRL、OpenRLHF、TRL、slime 等），具备框架深度定制与二次开发能力者优先；\n4.    具备 1–2 年以上一线大厂后训练团队相关经验者优先；特别优秀的应届博士/博后亦可；\n5.    在模型/训练技术报告中有署名成果者优先；在 NeurIPS、ICML、ICLR、ACL 等顶级会议发表过相关方向论文者优先（论文非硬性要求）；\n6.    具备极强的科研创新能力与独立攻关能力，能作为关键角色主导团队 Agentic RL 方向的技术交付。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7687960297156315435","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型后训练青年研究员","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7687960297156315435?mode=social","duty":"1.    研究和优化大模型后训练核心算法，包括 SFT、RFT、PPO、GRPO、DAPO 、OPD、SAO等主流强化学习对齐方法；\n2.    设计与搭建大规模强化学习训练框架，支持大模型（含 MoE 架构）的高效训练与调优，沉淀团队可复用的后训练基础设施与最佳实践；\n3.    结合团队“模型漏洞挖掘”等任务场景，将后训练与 RL 技术落地为可交付的模型能力，持续提升模型的安全性、推理与泛化能力；\n4.    跟进 RL 与后训练领域前沿进展（如 RLVR、过程奖励模型、Agentic RL 等），推动新算法在业务场景中的验证与落地。","requirements":"1.    人工智能、计算机、数学等相关专业硕士及以上学历（博士优先），具备扎实的强化学习与大模型智能体基础；\n2.    熟练掌握 PPO、GRPO、DPO 等主流 RL 算法，有大模型后训练 / RL 训练调优的实操经验；熟悉至少一种主流 RL 训练框架（如 veRL、OpenRLHF、TRL、slime 等），具备框架深度定制与二次开发能力者优先；\n3.    具备扎实的工程实现能力，熟练掌握 Python，熟悉 PyTorch 分布式训练；有 Megatron-LM、vLLM、SGLang 等训练/推理 Infra 经验者优先；\n4.    具备 1–2 年以上一线大厂后训练团队相关经验者优先；特别优秀的应届博士/博后亦可；\n5.    在模型/训练技术报告中有署名成果者优先；在 NeurIPS、ICML、ICLR、ACL 等顶级会议发表过相关方向论文者优先（论文非硬性要求）；\n6.    具备良好的前沿趋势洞察力、创新能力与独立解决问题的能力，科研与工程能力兼备。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7687957433378310441","sourceKey":"shlab_social","company":"上海AI实验室","title":"项目交付经理-物理智能中心","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7687957433378310441?mode=social","duty":"1、前期磋商阶段介入，和解决方案同事一起确认交付边界、验收标准、时间节点与责任划分\n2、统筹项目全周期：合同、排期、设备采购与到场、场地改造、软硬件部署、联调测试验收，对进度和成本负责\n3、驻场阶段带队完成安装调试和用户培训，确保能正确使用\n4、运维期建立响应机制，跟踪故障、收集使用数据、推动续约与能力扩展\n5、沉淀交付方法论。第一个实验室靠人扛，第十个实验室要靠流程","requirements":"1、本科及以上，理工科背景，一年以上项目管理或交付经验，做过涉及硬件安装与现场调试的项目\n2、独立负责过从签约到验收的项目，有分析和解决项目过程中出现的问题的经验能力\n3、有同时推动内部研发、外部供应商和客户三方的经验\n4、接受阶段性驻场，单次驻场可能持续数周。\n加分项\n1、有高校、科研院所或国家实验室的项目交付经验，熟悉科研体系的采购流程和决策链条\n2、有 PMP 或同类认证\n3、了解一点机器人或自动化设备","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7687497092064233779","sourceKey":"shlab_social","company":"上海AI实验室","title":"科研助理","city":"上海","category":"业务通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7687497092064233779?mode=social","duty":"1. 综合运营与支持\n1.1 综合运营：作为中心负责人的核心支持，高效管理其工作日程、差旅行程及重要会议的组织安排；作为内外部沟通的关键枢纽，协助进行团队管理、核心成员关系维护及跨部门协同。\n1.2 活动支持：与多部门协同，策划、组织、协同支持相关活动，包括但不限于技术大会、学术分享等。\n2. 科研项目与文案支持\n协助项目经理及科研人员进行科研项目书、结题材料的撰写支持；负责人员信息收集、文案初审及系统申报上传等事务。\n3. 技术成果宣发与社区运营\n负责技术成果在各渠道的宣发，负责内容策划与制作及社交账号的日常运维；\n4. 生态合作对接\n配合项目负责人进行外部生态合作对接，协助与高校、其他实验室及合作伙伴建立并维护良好的互动关系。","requirements":"1. 全日制本科及以上学历，1年及以上运营、综合行政管理相关工作经验；\n2. 极强的沟通协调与组织能力：具备出色的多任务处理、活动组织能力及能动性；\n3. 具备优秀的责任心、耐心与抗压能力，能妥善处理繁杂的部门行政工作；\n4. 具备良好的英文书面沟通能力，能独立处理英文邮件及日常英文材料；\n5. 有独立撰写文案、视频图片制作能力者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7687427339903289641","sourceKey":"shlab_social","company":"上海AI实验室","title":"物理智能仿真与生成工程师","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7687427339903289641?mode=social","duty":"面向具身智能与 Physical AI，负责 Real2Sim2Real、生成式仿真、可交互 3D 场景、合成数据生产及机器人仿真相关工具链与基础设施建设，推动算法研究成果形成稳定、高效、可规模化运行的仿真与数据系统。\n\n岗位职责\n1、负责物理智能仿真与生成工具链的设计、开发与维护，建设从真实数据输入、场景重建与生成、仿真环境构建、合成数据生产到机器人策略评测的完整工程链路。\n2、负责 Real2Sim 自动化场景构建 Pipeline，实现真实图像、视频、点云等数据向可交互仿真场景的转换，包括三维重建、资产生成与导入、Mesh / Collision 构建、物理属性配置及场景编辑等。\n3、负责基于 Isaac Sim / Isaac Lab、MuJoCo、SAPIEN、ManiSkill 等平台的机器人仿真系统开发，建设标准化、模块化的场景、资产、机器人、传感器及任务管理能力。\n4、参与基于 VLM、多模态大模型及生成模型的自动化场景生成系统开发，将场景理解、3D 重建、3D 生成及机器人仿真等算法集成至统一工具链，实现从真实数据或自然语言输入到可运行仿真环境的自动化构建。\n5、建设规模化合成数据与机器人轨迹数据生成 Pipeline，实现仿真任务自动执行、轨迹采集、数据清洗、质量检测、筛选及管理，支持大规模 Synthetic Data 生产。\n6、负责视觉、深度、点云、触觉等多模态传感器的仿真与数据采集，并支持刚体、液体、柔体、可变形物体等复杂物理场景的工程实现。\n7、支持 VLA、机器人 Policy、World Model / World Action Model 等模型在仿真环境中的训练与评测，建设批量实验、Benchmark、自动化评测及数据闭环能力。\n8、参与机器人真机实验及 Sim2Real 闭环验证，定位并解决仿真环境、数据管线、机器人控制与系统部署中的工程问题，持续提升系统运行效率、稳定性与可扩展性。","requirements":"任职要求\n1、计算机科学、人工智能、机器人、自动化、电子信息等相关专业，本科及以上学历。\n2、具备扎实的 Python / C++ 编程能力和良好的软件工程基础，熟悉 Linux、Git、Docker 等常用开发环境与工具。\n3、熟悉至少一种机器人仿真平台，如 Isaac Sim / Isaac Lab、MuJoCo、SAPIEN、ManiSkill 等，具有实际项目开发经验。\n4、熟悉机器人及三维场景相关数据，了解 RGB / RGB-D、Point Cloud、Mesh、USD / URDF / MJCF 等数据及资产格式。\n5、熟悉三维场景资产处理流程，能够完成场景与资产导入、坐标系转换、碰撞体构建、物理属性配置及仿真调试。\n6、熟悉 PyTorch 等深度学习框架，能够完成视觉、生成模型或多模态模型的推理部署、算法集成及数据 Pipeline 开发。\n7、具备较强的系统开发和工程问题定位能力，能够独立完成模块设计、开发、测试、性能优化与部署。\n8、具备良好的团队协作与沟通能力，能够与算法研究人员共同完成算法工程化、系统集成及实验验证。\n\n加分项\n1、具有 Real2Sim / Sim2Real、生成式仿真、数字孪生或自动化场景构建相关工程经验；\n2、具有 Isaac Sim / Isaac Lab 大规模仿真、Synthetic Data Generation 或机器人数据 Pipeline 开发经验；\n3、熟悉 USD、URDF、MJCF、Mesh、Point Cloud、3D Gaussian Splatting 等三维场景与资产表示；\n4、熟悉 ROS / ROS2、MoveIt、机器人控制及真机部署流程；\n5、具有多 GPU / 多机并行仿真、大规模数据生成或分布式任务调度经验；\n6、具有 VLA、机器人 Policy、Imitation Learning / Reinforcement Learning 等模型训练与评测系统开发经验；\n7、具有液体、柔体、触觉等复杂物理仿真系统开发经验；\n8、具有真实机械臂、移动机器人或其他具身智能平台的开发及调试经验。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7687426093590055178","sourceKey":"shlab_social","company":"上海AI实验室","title":"物理智能仿真与生成青年研究员","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7687426093590055178?mode=social","duty":"面向具身智能与 Physical AI，开展 Real2Sim2Real、生成式仿真、可交互 3D 场景生成、合成数据及多模态物理仿真 等方向研究，探索从真实世界建模、仿真世界生成到机器人策略训练与真实环境验证的完整技术闭环。\n\n岗位职责\n1、参与物理智能仿真与生成方向的前沿研究，围绕 Real2Sim2Real、Generative Simulation、Synthetic Data 等方向开展算法研发，探索面向具身智能的新一代仿真与数据生成范式。\n2、研究面向具身智能的可交互场景生成与重建技术，探索基于图像、视频及多模态数据的三维场景理解、几何重建、资产生成、物理属性恢复与场景编辑，实现高保真、可交互、物理一致的仿真环境构建。\n3、探索基于 VLM、多模态大模型及生成模型的自动化仿真场景生成，研究从自然语言、图像及视频等输入自动生成场景、任务、资产与交互环境的方法，提升仿真世界构建的自动化程度与多样性。\n4、研究生成式仿真数据与机器人轨迹数据合成，探索场景生成、任务生成、轨迹生成及数据质量评估等关键技术，构建规模化、多样化的机器人训练与评测数据。\n5、探索复杂物理世界建模与多模态仿真，包括刚体、液体、柔体、可变形物体等物理过程，以及视觉、触觉等多模态传感器仿真，提升生成环境的物理真实性与交互能力。\n6、探索仿真与生成技术在 VLA（Vision-Language-Action）、World Model / World Action Model、机器人策略学习等方向中的应用，开展模型训练、策略评测、仿真泛化及 Sim2Real 研究。\n7、构建 Real → Sim → Learning → Real 闭环验证体系，通过真实机器人实验分析仿真环境、合成数据及模型策略之间的 Domain Gap，持续提升仿真数据对真实机器人任务的有效性。\n8、跟踪 Physical AI、具身智能、生成模型、三维视觉及机器人学习领域前沿技术，负责关键问题定义、技术路线设计与实验验证，推动研究成果形成高水平论文、专利、开源项目或实际应用。\n","requirements":"任职要求\n1、计算机科学、人工智能、机器人、自动化、电子信息等相关专业，博士优先。\n2、在以下至少一个方向具有较深入的研究经验：具身智能、Real2Sim / Sim2Real、机器人学习、3D Vision、3D Generation、生成模型、World Model、物理仿真等。\n3、具备扎实的机器学习、深度学习及计算机视觉基础，熟悉 Python、PyTorch 等常用开发与深度学习框架。\n4、具备良好的科研能力，能够独立完成问题定义、文献调研、算法设计、实验验证及结果分析。\n5、了解机器人仿真及学习相关技术，熟悉 Isaac Sim / Isaac Lab、MuJoCo、SAPIEN、ManiSkill 等一种或多种仿真平台者优先。\n6、具备良好的英文文献阅读、技术沟通与团队协作能力，对 Physical AI 与具身智能方向具有持续研究兴趣。\n\n加分项\n1、具有 Real2Sim2Real、生成式仿真、自动化场景生成或机器人合成数据相关研究经验；\n2、熟悉 NeRF、3D Gaussian Splatting、Mesh、3D Generation、Video Generation 等三维重建与生成技术；\n3、具有 VLA、World Model / World Action Model、Imitation Learning、Reinforcement Learning 等相关研究经验；\n4、具有液体、柔体、可变形物体、触觉等复杂物理与多模态仿真经验；\n5、具有机器人真机实验及 Sim2Real 闭环验证经验；\n6、在 CVPR、ICCV、ECCV、NeurIPS、ICLR、ICML、RSS、CoRL、ICRA、IROS 等相关会议或期刊发表过高质量研究成果，或具有高质量开源项目及系统落地经验。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7686757468328937738","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型评测研究员/算法工程师（AI for Science方向）","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7686757468328937738?mode=social","duty":"\n面向大模型及AI在科学研究中的应用，研究如何科学、可靠地评价模型解决专业学科问题的能力，建设高质量评测基准，并通过实验分析识别模型的优势、局限和改进方向。\n\n1. 跟踪相关学科中AI应用与评测研究进展，识别具有科学价值和实际应用意义的评测问题；\n2. 围绕科学知识理解、推理、计算及具体科研任务，设计评测方案，建设和完善评测数据集、评价指标与基线方法；\n3. 开展模型评测与基线复现，检查数据和实验质量，提升评测的可靠性与可复现性；\n4. 结合学科知识分析模型表现，开展典型错误分析与能力边界研究，形成评测报告和研究成果；\n5. 与学科专家、算法及工程团队合作，推动评测方法和工具落地，探索自动评测与专家评价相结合的方法。","requirements":"\n任职要求\n1. 硕士及以上学历，化学、生物、材料、医疗、数学、计算机等相关专业，具备具体科学学科的研究经历或跨学科研究经验。\n2. 熟悉机器学习或大模型基本原理，对AI在科学研究中的应用具有研究兴趣，能够理解专业科学问题及其评价标准。\n3. 具备扎实的实验设计与分析能力，能够独立开展文献调研、评测方案设计、对照实验和结果分析。\n4. 熟练使用Python，熟悉Linux及常用机器学习、数据分析工具，能够阅读研究代码并完成实验复现。\n5. 具备良好的沟通协作能力，能够与不同学科背景的研究人员共同推进项目。\n\n加分项：\n\n1. 有AI for Science、大模型评测或科学领域Benchmark建设经验；\n2. 有高质量科研数据集建设、开源项目贡献或相关研究成果；\n3. 有科学计算工具、专业数据库或科研软件的使用与开发经验。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7686415471956756774","sourceKey":"shlab_social","company":"上海AI实验室","title":"数学科学发现与智能体方向青年研究员","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7686415471956756774?mode=social","duty":"我们正在构建面向原创数学发现的 数学科学发现智能体（Mathematical Discovery Agent）。团队希望将顶尖纯数学研究能力与人工智能深度结合，探索 AI 如何从“数学解题”进一步走向数学研究与数学发现：理解前沿数学文献、提出研究问题、形成证明策略、调用计算与形式化工具、验证关键命题，并在长期研究过程中产生新的数学知识。\n我们希望寻找具有扎实纯数学研究背景、对 AI 具有强烈兴趣的优秀数学家，与 AI 研究人员共同构建下一代数学科学发现智能体，并以国际知名数学猜想和重要开放问题作为真实研究环境，牵引智能体在长程推理、开放问题探索、自我反思与原创发现等核心能力上的持续突破。\n\n【主要工作】\n1、共同研发数学科学发现智能体\n与大模型、Agent 和强化学习研究人员深度合作，构建面向真实数学研究的科学发现智能体，使其具备数学文献理解、问题建模、猜想生成、证明规划、引理发现、反例搜索、证明验证及知识积累等能力，推动 AI 从数学 Problem Solving 迈向 Mathematical Research & Discovery。\n2、挑战重要数学猜想与开放问题\n面向代数、几何、拓扑、数论、分析、组合数学、概率等纯数学领域，选择具有重要学术价值的知名数学猜想、开放问题和关键子问题，开展“数学家 + AI Agent”协同研究。\n将真实开放问题作为智能体能力发展的核心牵引，通过长期研究任务不断暴露现有模型在抽象推理、证明规划、知识迁移、长程探索及原创性方面的能力边界，并推动智能体持续突破。\n3、研究 AI 驱动的数学发现新范式\n探索人工智能如何参与数学研究的完整过程，包括：\n文献理解 → 问题提出 → 猜想生成 → 路径探索 → 引理构造 → 证明搜索 → 反例发现 → 形式化验证 → 新知识形成。\n研究数学家的研究方法、直觉、启发式策略和问题分解方式如何与大模型及 Agent 结合，探索“Human-AI Collaborative Mathematics”以及更高自主程度的数学发现范式。\n4、以数学发现牵引智能体核心能力发展\n将纯数学作为研究高级智能的重要试验场，围绕真实数学研究需求，与 AI 团队共同定义和提升智能体的核心能力，包括复杂抽象推理、长程任务规划、深度搜索、记忆与知识组织、自我反思、错误修正、工具使用以及长期自主研究等。\n通过重大数学问题反向牵引基础模型、推理模型和 Agent 能力演进，使数学科学发现成为推动下一代智能体发展的核心场景之一。\n5、推动重要原创数学成果产出\n以产生真正具有数学价值的新知识为目标，与团队共同推动 AI 辅助或 AI 驱动的原创数学研究，在重要猜想、开放问题、新定理、新证明方法及数学理论等方向形成具有国际影响力的原创成果，并探索建立 AI 时代数学科学发现的新研究范式。","requirements":"【岗位要求】\n1、纯数学方向博士毕业，具有系统、深入的纯数学训练和独立科研能力；主要研究方向包括但不限于代数、代数几何、微分几何、拓扑、数论、分析、组合数学、概率论及相关领域；\n2、在纯数学领域具有优秀科研成果，以第一作者或核心作者在国际顶级数学期刊发表过高水平研究论文，具有解决重要数学问题的研究经历；\n3、具备扎实的数学基础、抽象思维能力和原创研究能力，能够独立判断重要数学问题的研究价值、技术难点和潜在突破路径；\n4、对人工智能、大语言模型、推理模型及智能体具有浓厚兴趣，愿意与 AI 研究人员长期深度合作，探索 AI 驱动数学发现的新范式；\n5、不要求候选人已经具备大模型训练或 Agent 工程背景，但希望具备一定编程基础，并愿意快速学习和使用现代 AI、计算数学及形式化数学工具；\n6、具有开放的研究视野，愿意挑战高风险、高难度、长周期的重要数学问题，并对“AI 能否进行真正的原创数学发现”这一长期问题具有强烈探索欲。\n\n【加分项】\n具备以下一项或多项经历者优先：\n1、在 Annals of Mathematics、Inventiones Mathematicae、Journal of the American Mathematical Society、Acta Mathematica 等国际顶级数学期刊或同等级别期刊发表过代表性成果；\n2、在某一纯数学方向具有系统深入的研究积累，并对该领域的重要猜想、开放问题和前沿研究方向具有深入理解；\n3、有解决知名数学猜想、长期开放问题或重要关键子问题的研究经历；\n4、具有跨数学领域研究能力，善于寻找不同理论、方法和数学结构之间的深层联系；\n5、熟悉 Lean、Isabelle、Coq 等形式化证明系统，或有自动定理证明、计算数学、符号计算相关经验；\n6、对 LLM、Reasoning Model、Agent、强化学习、自动定理证明等 AI 方向已有研究或实践；\n7、对 AI for Mathematics、Automated Mathematical Discovery、Human-AI Collaborative Mathematics 等方向有系统思考。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7686414353352984858","sourceKey":"shlab_social","company":"上海AI实验室","title":"智能体Harness与大模型强化学习算法工程师/青年研究员","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7686414353352984858?mode=social","duty":"我们正在构建面向下一代智能系统的 Agent Harness 与自主进化体系。团队聚焦 Agent、Harness、大模型强化学习、Recursive Self-Improvement（RSI）与能力内化，研究如何通过 Harness 为智能体提供规划、工具、环境、记忆与反馈机制，使模型在真实复杂任务中持续学习和进化，并进一步将 Harness 中形成的有效策略、技能与经验内化为模型自身能力，推动智能体从“依赖外部系统完成任务”走向“自主学习、自我改进与持续进化”。\n【主要工作】\n1、研发下一代 Agent Harness\n设计和构建面向复杂真实任务的 Agent Harness，研究任务规划与分解、工具调用、代码执行、状态与上下文管理、记忆、反思纠错、环境交互及长程任务执行等核心机制；探索 Harness 从“模型外部脚手架”向智能体学习环境、能力放大器与进化基础设施演进。\n2、研究 Agent 后训练与强化学习\n开展面向智能体的 SFT、Preference Learning、Reward Modeling、PPO / GRPO、RLVR、Online RL、Agentic RL 等后训练与强化学习研究，结合代码执行、工具调用、任务结果及环境反馈构建可验证奖励，重点提升模型的规划、推理、工具使用、长程执行、信用分配、自我纠错及复杂任务泛化能力。\n3、探索 Recursive Self-Improvement 与自主进化\n研究智能体递归自我改进（RSI）、Self-Play、持续学习、自动课程生成、经验积累、技能发现与策略进化等机制，构建“任务执行 → 环境反馈 → 错误分析 → 策略改进 → 数据生成 → 模型更新 → 能力验证”的持续学习闭环，探索智能体从人工设计向自主学习、自我改进和持续进化演进。\n4、研究 Harness 能力内化\n探索如何将 Harness 中通过人工设计、搜索或智能体自主发现形成的任务规划、工具选择、工作流、Reflection、错误恢复及 Skill 等有效能力，转化为高质量训练轨迹与学习信号，通过 SFT、蒸馏、强化学习及持续学习等方式逐步内化到模型参数中，形成“Harness 能力构建 → Agent Trajectory → 模型训练 → 能力内化 → 模型增强 → Harness 再进化”的 Model-Harness 协同进化闭环。\n5、推动 Auto-Research 与复杂真实任务落地\n将 Harness、Agent Learning 与 RSI 能力应用于 Coding Agent、Research Agent、Scientific Agent 等复杂任务，打通问题理解、任务规划、工具调用、代码执行、环境交互、结果验证、经验积累和持续优化等环节，并推动模型训练、Harness 迭代、能力评测及跨团队集成交付。\n","requirements":"【岗位要求】\n1、本科及以上学历，计算机、人工智能、软件工程、数学、自动化、认知科学等相关专业；\n2、编程基础扎实，熟练使用 Python，掌握 PyTorch、Transformers 等深度学习与大模型开发框架；\n3、具备大模型、强化学习或智能体相关研究与工程经验，对 SFT、PPO / GRPO、RLVR、Agent RL、工具调用、长程 Agent、Harness 系统中的一项或多项有深入理解；\n4、具备扎实的软件工程和实验能力，能够独立完成问题定义、系统设计、算法实现、模型训练、实验调参、结果分析和问题定位；\n5、对 Agent、Harness、大模型强化学习、自我改进和自主进化具有浓厚兴趣，愿意探索模型能力与系统能力如何相互促进、持续演化等开放性问题。\n6、具备较强系统工程能力的候选人同样欢迎申请，尤其欢迎同时理解模型训练与 Agent 系统、能够将前沿算法转化为可靠复杂系统的人才。\n\n【加分项项】\n具备以下一项或多项经验者优先：\n1、在 Agent、大模型、强化学习、机器学习等方向有优秀论文、开源项目或代表性成果。\n2、熟悉 LLaMA-Factory、verl、ms-swift、Megatron-LM、DeepSpeed 等训练框架；\n3、熟悉 vLLM、SGLang 等大模型推理与服务框架；\n4、有 SFT、PPO / GRPO、RLVR、Agent RL、Online RL、偏好学习等后训练实践；\n5、有 Agent Harness、Agent Framework、LLM Infra 或复杂任务执行环境开发经验；\n6、有 Recursive Self-Improvement、Self-Play、Continual Learning、Agent Evolution 等相关研究或实践；\n7、有长程 Agent、Coding Agent、Research Agent、Deep Research、多智能体、Memory 或 Tool Use 相关经验；\n8、有 SWE-Bench、ALE-Bench、Auto-Research 等 Agent Benchmark 或真实复杂任务评测经验；\n9、有分布式训练、大规模强化学习、推理优化或训练基础设施经验；","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7686387234296105235","sourceKey":"shlab_social","company":"上海AI实验室","title":"科学智能体算法工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7686387234296105235?mode=social","duty":"面向真实地球科学问题，建设能调用科学数据、领域模型与物理模拟工具的科学智能体系统，推动气象、遥感、能源等场景中的自动化分析、预测验证与科学发现。\n\n1. 研发科学智能体系统架构，实现科学问题理解、任务分解、规划调度、模型/工具选择与结果分析；\n2. 建设地球科学 Agent 工具链，接入气象、遥感、地面站、新能源等数据和模型，并沉淀标准化接口；\n3. 参与科学可信评测建设，覆盖结果正确性、物理一致性、证据充分性和工具执行状态。\n\n\n1. 设计地球科学数据治理体系，制定数据接入、时空基准、质量控制、版本与生命周期管理规范；建设数据基础设施与多源数据管线；\n2. 构建数据资产目录；建设 AI-Ready 数据集与 Benchmark，提供自动化数据构建能力，支撑建模与科学发现任务。","requirements":"1. 硕士及以上，理工科相关专业；\n2. 具有机器学习 / 人工智能相关经验，或地球科学研究背景；\n3. 熟悉 NetCDF、GRIB、GeoTIFF、Zarr 等地球科学数据格式，以及 xarray、GDAL、rasterio 等工具者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7686383797260863807","sourceKey":"shlab_social","company":"上海AI实验室","title":"AI后端开发工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7686383797260863807?mode=social","duty":"1. 负责 AI/Data Agent 平台任务环境和后端服务的设计、开发与持续演进，推动现有基础设施能力平台化、服务化和规模化落地。\n2. 负责 CPU/GPU 资源管理、任务调度、队列管理、优先级控制、资源隔离、配额管理等核心能力建设。\n3. 负责任务编排与异步执行系统建设，支持数据接入、文档解析、结构化抽取、清洗去重、格式转换、质量评估、标准化入库和结果交付等流程。\n4. 建设可注册、可检索、可组合、可评测的数据处理工具库，完善工具输入输出契约、参数模板、版本管理、资源消耗和质量评分等机制。\n5. 设计并实现面向 Agent的服务接口，支撑工具调用、任务状态管理、权限控制、执行追踪和结果回传。\n6. 完善任务失败重试、异常恢复、幂等控制、日志追溯、监控告警和审计能力，保障平台的稳定性、可观测性和可维护性。\n7. 与 Agent、算法、产品和测试团队协作，参与评测环境、轨迹收集环境和数据处理工作流的建设，推动平台能力持续迭代。\n8. 参与工程规范、接口标准、数据规范和研发工具链建设，持续提升系统质量和团队研发效率。","requirements":"1. 本科及以上学历，计算机、软件工程、人工智能等相关专业，3 年及以上 Python 或 Golang 后端研发经验。\n2. 深入理解 Python 或 Golang 的语言特性和工程实践，注重代码规范、测试质量和系统可维护性。\n3. 熟悉微服务、分布式系统、异步架构、高并发和大规模数据处理等技术。\n4. 熟悉数据库、缓存、消息队列、负载均衡、容器化和 Kubernetes 等常用基础设施。\n5. 具备任务调度、工作流引擎、资源管理、数据处理平台或云原生平台开发经验。\n6. 熟悉 RESTful、RPC 等服务接口设计方式，具备完善的服务治理、监控和故障排查能力。\n7. 具备基本的大模型、Agent、工具调用或 AI 服务工程化知识，能够理解 Agent 对任务调度和工具平台的调用需求。\n8. 具备较强的问题分析、技术攻坚和跨团队协作能力，能够独立推进复杂模块落地。\n加分项\n1. 有 AI 平台、Agent 基础设施、模型服务或数据构建平台研发经验。\n2. 熟悉 Ray、Argo、Airflow 等任务编排或分布式计算框架。\n3. 有 CPU/GPU 集群调度、资源隔离、科学数据处理或多模态数据处理经验。\n4. 活跃于开源社区，参与过有实际用户或影响力的开源项目。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7686160240714287387","sourceKey":"shlab_social","company":"上海AI实验室","title":"AI Data 平台高级开发工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7686160240714287387?mode=social","duty":"负责 AI-Ready 数据基座的平台框架和核心服务研发，统一承载不同来源和类型的数据处理能力，通过标准化算子和 Agent 动态编排，为模型训练、评测、RAG 及其他 AI 应用提供数据服务。\n岗位职责\n- 开发数据接入、算子注册、任务编排、执行调度、版本管理和结果发布等平台核心模块。\n- 将解析、清洗、去重、筛选、增强和质量评估等能力封装为标准化、可组合算子。\n- 建设 Agent 驱动的算子选择、自由组合、任务执行、异常处理和效果反馈机制。\n- 开发算法算子接入 SDK、API 和运行规范。\n- 与架构、算法及外部合作团队协作，完成算法能力的平台化集成。\n- 持续优化平台的执行效率、稳定性、扩展性和可观测性。","requirements":"- 计算机、人工智能、软件工程、数学等相关专业硕士及以上学历。\n- 3年以上软件工程、AI 数据处理或 AI 基础设施经验；优秀项目成果可不受年限限制。\n- 具备扎实的软件工程能力，能够独立完成模块设计、开发、测试和问题排查。\n- 有大模型、多模态、文档智能或其他 AI 数据处理工程经验。\n- 熟悉 Spark、Flink、Ray 等分布式数据处理框架中的至少一种，了解数据湖、任务调度等大数据平台技术。\n- 精通 Python，熟悉 Go、Java、Rust、C++ 中至少一种。\n- 在实际工程项目中落地过 Agent，包括工具调用、工作流编排、自动执行或异常恢复。\n- 熟练使用 Codex、Claude Code、Cursor 等 AI 开发工具，并能审查和验证生成代码。\n- 具备良好的沟通、团队协作和技术文档能力。\n优先考虑\n- 参与过生命科学、材料科学等领域的科学数据库、专题知识库或专题数据集建设。\n- 有 MinerU 等 AI 文档解析工具使用经验。\n- 有算子平台、工作流引擎、分布式任务系统或 Agent Runtime 开发经验。\n- 有优秀论文、竞赛、开源项目或从零到一工程成果。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7686158026001058074","sourceKey":"shlab_social","company":"上海AI实验室","title":"科学数据解决方案专员","city":"上海","category":"业务通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7686158026001058074?mode=social","duty":"1. 负责自然科学、工程技术及社会科学领域的数据需求分析与拆解，推进数据线索挖掘、需求调研、采购、采集、质量验收及入库，及时识别项目风险并推动问题闭环；\n2. 建立并持续完善元数据、分类标签、数据去重、完整性、可用性及质量抽检规则，维护数据运营看板，保障数据质量与项目交付效率；\n3. 负责与科研机构、供应商及其他合作伙伴开展需求沟通和方案协同，制定项目计划，跟进关键节点、问题清单及交付成果，推动合作项目按期落地；\n4. 运用大模型及自动化工具提升数据检索、整理、清洗、打标、核验及项目材料整理效率，并负责实习生的任务安排、过程指导与交付复核。","requirements":"1. 双一流高校本科及以上学历，信息管理、图书情报、数据科学、统计学等相关专业优先；\n2. 具有3年以上数据运营、数据治理、数据采购或项目管理相关工作经验，具备科研数据、专业语料库或对外合作项目经验者优先；\n3. 认真负责、耐心细致，具有较强的数据质量意识和结果导向，能够持续跟进问题直至闭环；\n4. 具备较强的信息检索、桌面研究、需求分析和结构化归纳能力，能够将合作伙伴的业务需求转化为清晰、可执行的数据方案；\n5. 具备AI思维，能够熟练运用大模型提升数据检索、整理、清洗、打标、核验及项目材料整理效率；\n6. 熟悉数据采集、元数据、分类标签、数据清洗、质量验收或采购交付等环节，掌握SQL、Python或自动化工具者优先；\n7. 具备良好的沟通协调和多项目管理能力，能够独立组织项目沟通、维护计划与问题清单，协调产品、技术、科研机构、供应商及合作伙伴推进项目。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7686151297975748891","sourceKey":"shlab_social","company":"上海AI实验室","title":"后端开发工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7686151297975748891?mode=social","duty":"1. 负责多模态多语言数据处理管线与集成平台的后端架构设计、开发和交付，构建覆盖数据接入、文档解析、文本清洗、质量过滤、格式标准化和入库交付全流程的数据处理系统，持续提升数据处理效率与质量。\n2. 建设支持多模态语料清洗与过滤能力，设计可组合、可版本化、可回滚的规则引擎与语言配置体系，保障数据处理的正确性、可观测与不丢数。\n3. 负责大规模分布式数据处理的工程落地，基于 Spark 等分布式计算框架完成清洗、转换、质量评估管线的性能优化与容量规划，支撑 PB 级语料的高吞吐处理。\n4. 建设多模态多语言数据集成平台，统一管理数据源接入、处理任务编排、数据血缘追踪和质量度量，沉淀可复用的数据处理工具库与组件。\n5. 设计并实现数据处理的配置化、版本化管理能力，支持规则集灰度发布、shadow 对比验证、异常归因和快速回滚，保障数据质量持续可控。\n6. 完善数据处理任务的失败重试、幂等控制、计数守恒校验、日志追溯、监控告警等稳定性能力，建立覆盖吞吐、保留率、错误率的完整指标体系。\n7. 与大模型训练、算法、评测团队协作，理解下游语料需求并将数据模型&质量标准工程化、规模化，参与语料构建、质量评估和迭代优化闭环。\n8. 参与工程规范、接口标准、测试体系（golden corpus、回归测试、性能基线）和研发工具链建设，持续提升系统质量和团队研发效率。","requirements":"1. 本科及以上学历，计算机、软件工程、人工智能等相关专业，3 年及以上 Python 或 Golang 后端研发经验。\n2. 深入理解 Python 或 Golang 的语言特性和工程实践，注重代码规范、测试质量和系统可维护性，具备大型代码库的重构与演进经验。\n3. 熟悉 Spark、Ray 等分布式计算框架，理解大规模数据处理的分区策略、容错机制、内存管理与性能调优方法。\n4. 熟悉数据库、缓存、消息队列、对象存储和容器化等常用基础设施，具备数据密集型系统的设计经验。\n5. 具备文本处理、数据清洗、ETL 管线或数据平台开发经验，理解数据质量治理的常见问题与工程解法。\n6. 熟悉 RESTful、RPC 等服务接口设计方式，具备完善的服务治理、监控和故障排查能力。\n7. 具备较强的问题分析、技术攻坚和跨团队协作能力，能够独立推进复杂模块落地，并从数据指标出发持续迭代系统。\n8. 具备基本的大模型或 NLP 工程化知识，了解语料构建、数据预处理对模型训练的影响，能够理解算法团队对数据管线的要求。\n加分项\n1. 有大模型训练语料构建、多语言数据处理、多模态数据（图像、音频、OCR、文档解析）管线研发经验。\n2. 熟悉 Ray、Argo、Airflow 等任务编排或分布式计算框架，有 YARN 或 Kubernetes 集群上的大规模作业调优经验。\n3. 有数据处理平台的版本管理、灰度发布、shadow 验证或 A/B 对比体系建设经验。\n4. 活跃于开源社区，参与过有实际用户或影响力的开源项目。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7686150868265224454","sourceKey":"shlab_social","company":"上海AI实验室","title":"AI Data平台架构师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7686150868265224454?mode=social","duty":"负责 AI-Ready 数据基座的平台架构和核心框架设计，建设支持多源数据接入、算子管理、Agent 动态编排、数据评估及下游服务的统一平台。\n岗位职责\n- 负责 AI Data 平台总体架构、技术选型和演进路线。\n- 设计数据接入、算子注册、执行调度、版本管理、质量评估和数据发布等平台框架。\n- 建设 Agent 驱动的算子选择、动态组合、任务执行和效果反馈能力。\n- 推动内外部算法算子的标准化接入和平台适配。\n- 与工程、算法及外部高校合作团队协同，推进关键技术方案落地。\n- 保障平台的扩展性、稳定性、可观测性和规模化运行效率。","requirements":"- 计算机、人工智能、软件工程、数学等相关专业硕士及以上学历。\n- 3年以上 AI 基础设施、AI 数据平台或模型工程经验；优秀项目成果可不受年限限制。\n- 具备扎实的平台架构和软件工程能力，有复杂系统从零到一建设经验。\n- 熟悉 AI 数据处理、质量评估、版本管理及下游供给流程。\n- 熟悉 Spark、Flink、Ray 等分布式数据处理框架中的至少一种，了解数据湖、任务调度等大数据平台技术。\n- 精通 Python，并熟悉 Go、Java、Rust、C++ 中至少一种。\n- 在实际工程项目中落地过 Agent，理解工具调用、任务编排、状态管理、评测和可观测性。\n- 熟练使用 Codex、Claude Code、Cursor 等 AI 开发工具，能够将其应用于设计、开发、测试和代码审查。\n- 具备良好的沟通和团队协作能力，能够推动内部团队及外部合作方达成一致。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7686149783077882138","sourceKey":"shlab_social","company":"上海AI实验室","title":"网络安全数据解决方案架构师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7686149783077882138?mode=social","duty":"1. 懂网络安全，能做 \"安全 + 数据\" 翻译器\n  - 熟悉漏洞挖掘、渗透测试、安全测评、密码模块、可信计算、物联网安全等核心概念与技术\n  - 主导设计网络安全数据数据需求地图与建设方案\n  - 研究前沿攻防技术，跟踪国内外安全动态与漏洞披露信息，复现漏洞，研究攻击手法和防御技术，持续提升团队的安全研究能力\n2. AI/Agent 驱动的漏洞挖掘与修复\n  - 有实操经验：利用大模型（Claude/GPT/DeepSeek/Qwen 等）或 Agent 框架（LangChain/AutoGen/SWE-Agent/Hermes 等）完成漏洞自动化发现、PoC 生成、补丁分析与修复建议\n  - 与技术部门联合建设 Agent 轨迹数据采集管线（含 environment 快照、reward/verify 信号、thinking fidelity 分级），形成可复用的 \"AI 安全攻防\" 数据基座\n  - 探索大模型辅助二进制漏洞挖掘、Fuzzing + LLM 变异、自动修复（AutoPatch） 等前沿方向并工程化落地\n3. 生态合作与外部资源整合\n  - 了解奇安信、360、绿盟、启明星辰、长亭、斗象、微步在线等网络安全公司的产品能力与数据能力，能识别可合作 / 可采购 / 可置换的外部数据源\n  - 主导与安全厂商、高校院所、行业用户的数据共建、共测、共享合作，签订合作协议并推动交付\n4. 国家项目管理与交付\n  - 具备国家重大专项、重点研发计划、部委专项课题的申报、执行、验收全流程经验，能独立牵头课题任务书编写、预算编制与节点交付\n  - 协调跨单位联合攻关，处理多方协作中的合作进度、成果集成、成果归属、联合表达等事项","requirements":"- 网络安全：10年以上网络安全行业经验，主导过漏洞挖掘或安全测评项目\n- AI/Agent 实操：至少 1 个利用大模型 / Agent 完成漏洞挖掘或修复的可验证项目（GitHub / 专利 / 内部报告均可）\n- 生态合作：有安全厂商 BD / 生态合作经验，或已建立厂商 / 高校 / 行业数据合作网络；具备商务谈判与数据合规审查能力\n- 国家项目：牵头或核心参与过国家重大专项、重点研发计划、部委课题；熟悉课题任务书、预算、验收管理规范；有涉密项目管理经验者优先","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7686149338261145865","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型预训练数据研发工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7686149338261145865?mode=social","duty":"负责大模型预训练数据的处理、评估、筛选和实验验证，推动数据从原始来源转化为可用于模型训练的数据集，并持续提升数据的有效性和稳定性。\n岗位职责\n- 负责文本、代码及领域数据的清洗、去重、采样和数据集构建；\n- 设计数据特征、分类模型、排序模型和筛选策略；\n- 综合规则、统计特征、embedding、代码模型和大模型评分信号进行数据评估；\n- 参与代码可解析性、结构、可执行性、重复性和安全风险分析；\n- 参与多语种、代码、数学及其他领域数据的处理和评估；\n- 参与合成数据的生成、验证和筛选；\n- 设计数据标注、抽检、难例分析和误差分析流程；\n- 通过小模型训练、消融实验和下游评测验证数据价值；\n- 负责相关模型和流程的部署、监控及持续迭代。","requirements":"- 计算机、机器学习、自然语言处理、数据挖掘或相关专业硕士及以上学历；\n- 具备机器学习、数据挖掘或大模型数据研发经验；\n- 熟练掌握 Python，熟悉 PyTorch、Transformers 或类似工具；\n- 熟悉分类、排序、回归、特征工程、样本采样和模型评估；\n- 熟悉 XGBoost、LightGBM 或其他结构化数据建模工具；\n- 具备大规模文本、代码或多语种数据处理经验；\n- 能够独立完成从数据分析、特征设计、模型训练到效果验证的完整工作；\n- 具备良好的实验设计、问题分析和工程落地能力；\n- 能够阅读英文论文和开源项目，并将方法实现为可靠工具或流程。\n优先考虑\n- 有大模型预训练数据、数据筛选或数据配比经验；\n- 有代码模型、代码解析、静态分析、编译测试或代码安全分析经验；\n- 有多语种 NLP、低资源语言或跨语言评估经验；\n- 有合成数据、LLM-as-a-Judge、reward model 或数据排序经验；\n- 有数据去重、污染检测、隐私保护或许可证风险识别经验；\n- 有相关论文、开源项目或实际落地成果。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7686149332273973558","sourceKey":"shlab_social","company":"上海AI实验室","title":"数据分析挖掘工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7686149332273973558?mode=social","duty":"1、负责人工智能方向多语种、多模态海量数据的清洗治理、挖掘分析与质量迭代，搭建稳定高效的数据处理管道，沉淀高质量 AI 训练数据资产。\n2、深入理解大模型语料建设、数据基座搭建、AI 产品出海等核心业务逻辑，结合业务场景拆解分析需求，输出数据洞察、复盘结论与优化方案，支撑项目落地与业务决策。\n3、参与区域国别数据体系、知识图谱、分层语料库建设，联动算法、产品与智库团队，持续提升模型训练、智能检索、多语种生成的数据底座能力。\n4、结合海外区域、国别行业特征开展专项数据调研与分析，沉淀标准化数据方法论，赋能跨境 AI 合作与海外业务布局。","requirements":"1、硕士及以上学历，计算机、大数据、统计、人工智能、国际关系等相关专业，有 AI 数据挖掘、数据分析相关经验优先。\n2、熟练 SQL、Python，具备扎实的数据清洗、统计分析、数据治理能力，了解 NLP、多模态数据处理基本逻辑。\n3、具备业务思维，不局限纯技术执行，能够结合业务目标开展数据分析与问题优化。\n4、优先条件：具备区域国别研究、海外市场分析、小语种数据、一带一路 / 跨境数据项目经验者大幅优先。\n5、数据敏感度高，逻辑清晰，善于沉淀方法论，具备良好跨部门协同与文档复盘能力。\n岗位亮点：\n参与国家级 AI 数据基建与区域国别数据核心项目，对接智库与头部企业出海业务，技术 + 业务 + 行业研究多维成长，赛道稀缺、成长空间大。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7686149294239467814","sourceKey":"shlab_social","company":"上海AI实验室","title":"Agent 开发工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7686149294239467814?mode=social","duty":"1. 负责面向复杂数据处理任务的 Data Agent 核心能力研发，构建稳定、可部署、可持续迭代的 Agent 系统。\n2. 研发复杂任务的意图理解、任务分解、动态规划、工具语义检索、流程自动编排、自动执行、异常修复和结果校验能力。\n3. 负责 Agent 的设计与开发，包括上下文构建、状态管理、记忆管理、权限控制、环境交互、工具调用和执行记录等能力。\n4. 建设 Agent 任务环境、轨迹收集和数据构建流程，沉淀任务轨迹、工具调用链、环境交互数据、多轮推理数据和代码执行数据。\n5. 建设 Agent 评测体系和自动化评测流水线，设计任务指标、工具链成功率、流程质量、稳定性和任务完成度等评估方法。\n6. 基于评测结果和迭代数据，持续优化 Agent 的提示策略、任务规划、工具使用、长上下文理解、函数调用、自我反思和错误恢复能力。\n7. 参与 SFT、RLVR、数据合成、能力回归和模型适配等工作，重点开展面向实际场景的二次开发和工程优化。\n8. 与后端工程师协作完成资源调度、工具库、任务编排平台的接口适配，推动 Agent 能力在科学数据处理和复杂任务场景中的落地。\n9. 跟踪 Agent、LLM Infra、代码智能体和科学智能等方向的前沿进展，完成技术调研、方案验证和工程沉淀。","requirements":"1. 本科及以上学历，计算机、人工智能、软件工程、自然语言处理、机器学习、数据科学等相关专业，硕士及以上优先。\n2. 具备扎实的 Python 编程能力，熟悉 Linux、Docker 及常用软件工程实践。\n3. 熟悉大语言模型、推理模型、RAG、Tool Use、函数调用、任务规划、上下文管理或多智能体系统中的一个或多个方向。\n4. 理解 ReAct、CoT、工作流编排、Agent 记忆、状态管理和结果校验等基本方法。\n5. 具备 Agent 系统或 AI 应用的工程落地经验，能够使用 RESTful API、WebSocket 等方式完成前后端和算法模块协同。\n6. 熟悉 PyTorch、Transformers、vLLM、Ray、LangChain、LlamaIndex 或同类工具者优先。\n7. 具备较强的实验设计、指标分析、问题拆解和快速迭代能力，能够将研究思路转化为稳定可用的系统能力。\n8. 具备良好的沟通协作能力，能够与后端、算法、产品和测试团队共同推进复杂任务。\n加分项\n1. 参与过 Agent、LLM Infra、自动化办公助手、搜索问答系统或复杂工作流系统建设。\n2. 有 SFT、DPO、RLHF/RLAIF、RLVR、数据合成、轨迹构建或自动化评测经验。\n3. 熟悉 SWE-Bench、代码生成、代码修复、科学文献理解、AI4Science 或安全智能体等场景。\n4. 有 Agent Framework、Harness、工具调用系统或相关开源项目经验。\n5. 有前沿论文、专利、开源项目，或 ACM、Kaggle、CTF 等竞赛经历优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7686063101133555994","sourceKey":"shlab_social","company":"上海AI实验室","title":"司南平台设计师","city":"上海","category":"业务通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7686063101133555994?mode=social","duty":"1. 负责司南 OpenCompass 大模型评测产品的 UI 视觉和交互体验设计，覆盖 Web 端及必要的移动端适配；\n2. 负责模型榜单、评测集社区、大模型竞技场、评测任务、模型详情、能力画像及评测报告等核心产品的体验设计；\n3. 深入理解大模型评测业务，将模型、数据集、评测指标和实验结果等专业概念转化为清晰、易懂的产品界面；\n4. 参与需求分析和产品方案讨论，通过用户流程、信息架构、线框图及交互原型推动需求落地；\n5. 负责复杂操作流程的交互设计，包括模型接入、评测配置、任务创建、运行监控、异常处理和结果分析等；\n6. 使用 Cursor、Codex、Claude Code 等 AI 编程工具，通过 Vibe Coding 将设计方案快速实现为可交互的前端页面；\n7. 建立并持续维护产品设计系统，包括色彩、字体、图标、栅格、组件、图表和交互规范；\n8. 输出高质量设计稿、交互原型、设计规范及切图资源，并与前端工程师协作完成设计验收。通过用户访谈、可用性测试、用户反馈及产品数据发现体验问题，持续推动产品优化；\n9. 跟踪 AI 产品、开发者工具、数据分析产品和模型评测领域的设计趋势，探索适合大模型评测场景的交互方式；\n10. 跟踪 AI 产品、开发者工具、数据分析产品和模型评测领域的设计趋势，探索适合大模型评测场景的交互方式。","requirements":"1. 视觉传达、交互设计、工业设计、数字媒体或相关专业本科及以上学历。具备 UI 和交互设计经验，能够独立完成从需求理解、流程梳理、原型设计到视觉交付的完整设计工作；\n2. 熟练使用 Figma 等主流设计工具，具备高保真原型和设计规范输出能力；\n3. 具备扎实的视觉设计基础，对布局、色彩、字体、图标、层级和品牌一致性有良好的把控能力；\n4. 具备良好的交互设计能力，熟悉信息架构、用户流程、交互原型和可用性设计方法；\n5. 有复杂平台型或数据型产品设计经验，能够处理多层级导航、复杂表单、任务流程、数据筛选和多状态页面；\n6. 具备较强的信息整理和抽象能力，能够把复杂、专业的评测概念转化为用户容易理解的信息结构；\n7. 了解 Web 前端的基本实现原理和约束，能够与前端工程师进行有效沟通，并兼顾设计效果与实现成本；\n8. 具备良好的产品思维和用户意识，能够从用户目标出发分析问题，而不只是完成视觉美化；\n9. 具备良好的沟通表达和跨团队协作能力，能够与产品、前端、后端及算法团队共同推进方案落地；\n10. 应聘时需提供能够体现 UI、交互流程和复杂产品设计能力的作品集。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7685977732224960822","sourceKey":"shlab_social","company":"上海AI实验室","title":"AI红队算法工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7685977732224960822?mode=social","duty":"1.研究在真实场景中造成安全影响的大模型与智能体攻击技术，包括但不限于越狱攻击、提示注入攻击等，重点关注code agent、terminal agent等复杂应用场景。\n2.研究大模型安全护栏的对抗与绕过技术，分析模型拒答机制、内容过滤器、输入输出审核、安全策略模型及系统级防护机制，研究针对模型安全护栏的自适应对抗方法，包括自动化越狱生成、攻击提示优化、多轮攻击、长上下文攻击、跨模态攻击及基于反馈的迭代攻击等。\n3.构建自动化大模型与智能体红队系统，利用搜索、规划、强化学习、自进化、多智能体协作等方法自动生成、筛选和优化攻击样本，提升攻击方法在不同模型、任务、工具和应用环境中的迁移性、稳定性与成功率。\n4.研究智能体全链路安全风险，分析大模型智能体在感知、规划、推理、记忆、工具调用、代码执行和结果汇报等环节中的安全薄弱点，研究长程任务执行中的策略规避、欺骗行为、权限滥用、敏感信息泄露和非预期工具调用等风险。","requirements":"1.本科及以上学历，博士学历优先；计算机科学、人工智能、数据科学、软件工程、信息安全或相关专业背景优先，有大模型安全、可信人工智能或网络安全相关研究和项目经验者优先。\n2.具备扎实的机器学习和深度学习基础，理解大语言模型的预训练、监督微调、偏好优化和强化学习等基本流程，熟悉推理模型和智能体系统的基本原理。\n3.对大模型安全攻防具有较强兴趣，了解越狱攻击、提示注入、安全对齐等至少一个方向，包括系统提示词、安全微调、拒答机制、内容审核、输入输出过滤、Guard Model、工具权限控制和运行时防护等。\n4.具备良好的编程和实验能力，熟练使用Python；熟悉PyTorch、Transformers、vLLM等常用深度学习框架或推理工具。\n5.在CVPR、NeurIPS、ICML、ICLR、ACL、EMNLP等人工智能会议，或CCS、IEEE S&P、USENIX Security等安全会议发表过相关研究成果者优先。\n\n加分项\n有在AI公司进行安全研究的经验，具有code agent、terminal agent等的开发、测试和安全分析经验。\n有大模型越狱、提示注入、智能体红队、安全评测或安全对齐相关研究和项目经验，能够独立复现或改进代表性攻击方法。熟悉自动化攻击优化方法，例如多智能体协作、自进化攻击框架等。\n参与过大模型安全评测平台、红队工具、开源Benchmark或攻防框架的开发与维护，或在GitHub等平台有高质量开源项目。\n","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7685719238644451594","sourceKey":"shlab_social","company":"上海AI实验室","title":"解决方案工程师（集成电路）-产业融合方案中心","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7685719238644451594?mode=social","duty":"该岗位为面向集成电路产业的核心探索者与方案架构师。任职者将深入理解集成电路核心环节的业务逻辑与技术痛点，基于实验室现有的AI架构资源，识别高价值切入场景，将复杂产业需求转化为可验证的技术路线，并协同团队完成原型验证与产业落地。实验室重视候选人的产业根基与成长潜力，期待其在扎实专业背景基础上，展现跨领域融合的能力与携手共建新方向的意愿。\n【岗位职责】\n一、产业扫描与场景识别\n- 系统跟踪集成电路全产业链动态，覆盖芯片设计（前端/后端）、晶圆制造（工艺、良率、设备）、封装测试、半导体设备与材料等核心环节；\n- 深入调研各环节的业务流程与技术瓶颈，识别算法技术可赋能的高价值场景，完成优先级评估、可行性论证及技术路径初判；\n- 建立并维护产业知识图谱，沉淀细分领域的方法论与最佳实践。\n二、技术方案架构与路径探索\n- 基于实验室现有的AI架构资源与算力基础设施，参与或主导产业解决方案的技术架构设计，明确数据链路、技术接口、评估体系及交付标准；\n- 针对关键场景开展技术概念验证与原型开发，使用Python等工具完成可行性验证，探索算法能力与产业问题的有效结合方式；\n- 在算法能力持续建设过程中，承担技术路径定义与需求输入的核心角色，将产业洞察转化为清晰的技术命题与资源投入建议。\n三、产业对接与方案落地\n- 独立对接集成电路产业链各环节头部企业（设计公司、晶圆厂、封测厂、设备商等），深入挖掘真实业务痛点，完成需求分析与技术方案设计；\n- 撰写行业深度报告、技术方案白皮书及项目立项材料，为实验室战略决策与资源投入提供依据；\n- 主导或参与对外技术宣讲、方案演示及项目交付，建立并维护产业合作关系，推动实验室技术能力在产业端的验证与应用。\n四、方向建设与知识沉淀\n- 参与团队技术体系建设，沉淀跨领域知识库、标准化工作流程及探索阶段的方法论；\n- 指导初级研究人员开展产业调研与技术验证，提升团队整体产业认知与解决方案能力。","requirements":"1. 微电子、集成电路、电子信息、材料、计算机等相关专业，硕士及以上学历；\n2. 五年左右集成电路或相关领域从业经验，对芯片设计、晶圆制造、封装测试、半导体设备或材料中至少一个环节有深入理解，对其他环节具备基本认知或强烈学习意愿；\n3. 对算法技术（如机器学习、深度学习、大语言模型等）具备认知与兴趣，能够基于实验室资源开展学习与技术验证，熟练使用Python开展基础实验；\n4. 具备出色的业务抽象与逻辑分析能力，能够将复杂产业问题拆解为清晰的技术命题，并参与从方案设计到原型验证的闭环；\n5. 具备优秀的跨领域沟通与资源整合能力，能够独立对接产业客户，并基于现有架构资源推动技术探索；\n6. 具备开创精神与共创意愿，适应方向持续演进的创新环境，愿意与实验室共同定义并建设这一新兴方向。\n【优先条件】\n- 具有EDA、AI芯片、晶圆制造、封装测试、半导体设备或产业咨询等跨领域复合背景；\n- 具有将新兴技术引入传统半导体产业并推动落地的实际经验；\n- 具有产业解决方案设计、技术咨询或头部半导体企业核心研发/产品经历；\n- 了解大语言模型、生成式技术在半导体产业各环节的前沿应用；\n- 具备团队搭建经验或技术方向带头经历。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7685663259203111204","sourceKey":"shlab_social","company":"上海AI实验室","title":"重点研发项目经理TPM（数据中心）","city":"上海","category":"业务通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7685663259203111204?mode=social","duty":"1. 负责科研团队研发项目数据方向工作推进，制定数据全生命周期管理方案（采集、清洗、标注、评测、版本管理），统筹训练数据建设进度、质量与成本，确保模型训练数据供给按期交付；\n2. 搭建并持续优化数据治理与质量评估体系，建立数据质量指标（覆盖率、多样性、准确性、时效性等），支撑数据集评测与迭代，推动数据飞轮闭环；\n3. 管理大模型训练数据构建项目（文本、图像、视频、音频、代码等），统筹标注需求定义、标注规范制定、标注团队管理与质检流程，保障标注质量与一致性；\n4. 协调内外部数据资源，对接产品/科研团队、数据供应商、标注合作方及政府相关部门，推进数据采购、授权合规与跨机构数据协作；\n5. 推动数据基础设施与工具链建设，包括数据平台、标注平台、数据版本管理、自动化清洗流水线等，提升数据生产效率与可复用性；\n6. 支撑科研项目标准化立项与交付全流程，组织数据相关项目书撰写、阶段性检查、结题验收等工作；\n7. 支持组织管理与运营，包括数据团队资源配置（算力、人力、存储等）、知识库建设、效能优化及数据资产盘点；\n8. 管理并跟进与重点企业、机构的数据合作项目，支持研究团队与外部沟通交流。","requirements":"1. 硕士及以上学历，6年及以上相关工作经验，计算机、数据科学、人工智能、统计学等理工科相关专业优先；\n2. 具备大规模数据集构建或数据治理实践经验，熟悉数据采集、清洗、标注、评测全流程，有AI训练数据管理经验者优先；\n3. 了解大模型训练数据需求（预训练语料、指令微调数据、RLHF偏好数据、安全对齐数据等），熟悉多模态数据构建者优先；\n4. 拥有出色的沟通协调能力与跨部门合作能力，能够统筹标注团队、算法团队、外部供应商等多方资源，解决数据生产过程中的质量问题、进度瓶颈与协作冲突；\n5. 熟悉数据合规相关法律法规（个人信息保护法、数据安全法等）及AI数据治理框架，有数据合规审查经验者优先；\n6. 有政府机关、高校、科研院所、大型企业等或头部AI公司数据团队相关工作经验者优先；\n7. 有国家级、省部级科技项目的申报立项和组织管理相关工作经验者优先；\n8. 拥有PMP证书或Scrum Master认证优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7685624585177467174","sourceKey":"shlab_social","company":"上海AI实验室","title":"智能体能力对齐工程师/青年研究员","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7685624585177467174?mode=social","duty":"1. 参与智能体模型的真实场景生产能力与科学能力的训练与能力提升，包括代码生成、任务规划和长时程优化等能力。\n2. 参与智能体模型的后训练方法研究与实现，包括 SFT、强化学习、自我改进（Recursive Self-Improvement）等方向。\n3. 构建和优化面向 Agent 的训练数据与评测体系，包括高质量轨迹数据、错误修复数据、任务规划数据和多轮交互数据。\n4. 参与面向 Auto-Research 的能力提升，负责智能体模型的跨团队协作与交付，并推动在智能体模型上的能力集成。","requirements":"1. 硕士及以上学历，计算机、人工智能、软件工程、数学、自动化等相关专业优先。\n2. 编程基础扎实，熟练使用 Python，熟悉 PyTorch / Transformers 等大模型训练框架。\n3. 熟悉大模型基本原理，对 SFT、RLHF、DPO、PPO、GRPO等后训练方法有理解或实践经验。\n4. 具备较强的实验能力，能够独立完成实验设计、训练调参、结果分析和问题定位。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7685621983657462054","sourceKey":"shlab_social","company":"上海AI实验室","title":"科学通用智能体算法工程师/青年研究员","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7685621983657462054?mode=social","duty":"我们正在构建面向未来科学研究与科学发现的科学通用智能体（General Scientific Agent）。团队聚焦科学推理、科学研究与科学发现，研究大模型如何理解复杂科学问题、执行长程科研任务，并进一步形成可验证的新假设与新知识，推动智能体从“解决已知问题”走向“自主研究与原创发现”。\n\n工作职责：\n1. 提升科学通用智能体能力：面向数学、物理、生命科学等领域，提升模型的复杂科学推理、长程任务规划、代码与工具调用、记忆反思、多智能体协作及未知问题泛化能力；\n2. 研究智能体后训练方法：开展面向 Agent 的 SFT、强化学习、GRPO、偏好优化、轨迹学习、长程信用分配和自我改进等算法研究，提升模型在复杂科研任务中的规划、执行、纠错与持续优化能力；\n3. 构建科学数据与评测体系：研发大规模、自动化、高质量的科学数据生产系统，构建推理轨迹、研究轨迹、任务规划、工具调用、错误修复、多轮交互及科学发现数据；建立覆盖科学推理、科学研究和科学发现的一体化评测体系；\n4. 研发全流程 Auto-Research 智能体：打通文献检索与理解、科学问题提出、假设生成、研究方案设计、代码与实验执行、证据分析、结果验证和知识积累等环节，推进模型训练、推理优化、能力评测及跨团队集成交付。","requirements":"岗位要求\n1. 本科及以上学历，计算机、人工智能、软件工程、数学、物理、生命科学、电子信息、自动化等相关专业；\n2. 编程基础扎实，熟练使用 Python，掌握 PyTorch、Transformers 等深度学习与大模型开发框架；\n3. 具备大模型、推理模型或智能体相关研究与工程经验，对 SFT、强化学习、GRPO、偏好优化、工具调用、长上下文或 Agent 系统中的一项或多项有深入理解；\n4. 具备较强的数理基础和实验能力，能够独立完成问题定义、实验设计、算法实现、训练调参、结果分析与问题定位；\n5. 对大模型、智能体、AI for Science 和自主科学研究有浓厚兴趣，愿意持续探索开放性、高难度问题。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7685327528730560822","sourceKey":"shlab_social","company":"上海AI实验室","title":"生态合作运营","city":"上海","category":"业务通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7685327528730560822?mode=social","duty":"1. 负责司南大模型评测体系的生态运营和对外合作，制定模型厂商、科研机构、央国企、行业协会及开源社区的合作策略；\n2. 建立并维护与国内外大模型厂商的合作关系，推动厂商主动参与司南评测，形成稳定、长期的模型送测和结果发布机制；\n3. 跟踪主流模型厂商的产品与模型发布计划，推动在新模型正式发布时第一时间拿到模型评测资源；\n4. 设计模型厂商合作方案，协调模型接入、测试资源、评测周期、结果确认和联合发布等环节；\n5. 向模型厂商推广司南自研评测基准、评测数据集和自动化评测，推动相关成果被采用、集成或共同建设；\n6. 与央企、国企、科研院所、高校及产业单位建立联系，深入了解其大模型应用和评测需求，识别行业评测基准共建、标准共建等合作机会；\n7. 拓展开源平台、开发者社区、技术媒体及内容社区合作，推动司南产品、评测榜单、研究成果和技术内容的传播；\n8. 策划并组织专业活动，包括学术研讨会、技术沙龙、模型评测专题会、闭门交流会及成果发布会；\n9. 负责合作伙伴及生态项目管理，建立合作线索、伙伴分层、跟进记录、项目进度和成果复盘机制；\n10. 收集模型厂商、机构用户及社区开发者的反馈，为评测基准建设、产品迭代和生态策略提供输入。","requirements":"1. 本科及以上学历，人工智能、计算机、市场营销、新闻传播、公共关系或相关专业优先；\n2. 具备科技行业生态运营、商务拓展、机构合作、开发者关系或行业运营经验；\n3. 具备模型厂商、高校科研院所、央国企、行业协会、开源社区等至少一类主体的合作经验；\n4. 具备较强的合作拓展能力，能够独立完成合作对象识别、关系建立、需求挖掘、方案设计、商务沟通和项目推进；\n5. 具备良好的技术理解能力，能够理解大模型、模型评测、评测基准、评测榜单及评测平台等基本概念；\n6. 能够将专业技术成果转化为合作伙伴容易理解的价值主张、合作方案和对外材料；\n7. 具备复杂项目推进能力，能够协调模型厂商、科研机构、技术团队及传播渠道等多方资源，推动合作按期落地；\n8. 具备较强的行业敏感度，能够持续跟踪模型发布、技术趋势及产业动态，及时识别潜在合作机会；\n9. 具备专业活动策划和执行能力，能够主导议题设计、嘉宾邀请、流程组织、现场执行及会后传播；\n10. 具备目标导向和结果意识，能够同时管理多个合作项目，并建立清晰的过程与结果指标。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7685310923753900324","sourceKey":"shlab_social","company":"上海AI实验室","title":"科学数据评测青年研究员","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7685310923753900324?mode=social","duty":"1. AI4S 科学数据评测与治理体系建设：设计跨学科、跨场景科学数据评测框架、评测基准与指标体系；科学数据检索能力建设、科学数据治理工作，持续优化评测、检索流程的效率与可靠性；\n2.  科学数据评测平台能力集成：支撑科学数据评测平台建设，研发科学数据前沿评测系统，输出评测报告与技术文献，落地对外项目汇交数据评测；\n3. 跨学科科研协同：联动多学科团队完成科学数据与科研任务适配，探索面向交叉科研场景的数据应用能力。","requirements":"1. 计算机科学、自动化、人工智能、数据科学或理化、地学、生命科学等AI4S 交叉学科的硕士/博士；\n2. 熟悉多模态大模型、智能体的评测方法和工具，或熟悉数据质量评价相关理论方法，具有多模态数据处理和分析经验；\n3. 以第一作者发表过高水平论文，包括但不限于AI领域顶会顶刊（NeurIPS/ICML/ICLR/CVPR/TPAMI/TIP）或Nature，Science 主刊或子刊；\n4. 具有多模态数据集开发、垂类大模型开发、智能体系统开发工作经验优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7685296302590511402","sourceKey":"shlab_social","company":"上海AI实验室","title":"服务端开发工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7685296302590511402?mode=social","duty":"1. 负责司南 OpenCompass 评测产品的后端架构设计、功能开发和持续迭代，建设稳定、易用、可扩展的大模型评测平台；\n2. 与评测算法及研究团队紧密协作，理解评测算法的原理、输入输出和运行流程，将算法原型转化为可配置、可复用的产品功能和后端服务；\n3. 负责评测平台评测任务全生命周期管理，包括任务创建、参数校验、资源申请、调度执行、进度跟踪、异常处理、结果回收及任务重试；\n4. 建立数据与模型服务的规范化访问接口，保障产品前端和算法服务的稳定调用。支持开源模型、内部模型及外部模型 API 的统一评测；\n5. 负责评测结果的存储、查询、聚合和对比分析，支持排行榜、实验对比、能力画像和评测报告等产品功能；\n6. 优化大规模评测场景下的系统性能和稳定性，解决高并发、长耗时任务、分布式调度、服务容错及海量实验数据管理等问题；\n7. 建设平台的日志、监控、告警、权限控制、操作审计和故障排查能力，保障系统稳定、安全运行；\n8. 参与需求分析、技术方案设计、代码评审、测试发布和技术文档建设，持续提升研发效率和代码质量；\n4. 负责各类大语言模型及多模态模型的评测任务，完成评测方案设计、任务配置、资源调度、结果校验和分析报告输出；\n5. 优化大规模评测任务的执行效率与稳定性，解决分布式推理、并发调用、显存管理、任务容错和结果复现等工程问题；\n6. 建设评测数据、配置、实验结果和模型版本的管理机制，保证评测过程可追踪、可复现、可对比；\n7. 参与评测基准和数据集建设，包括数据清洗、质量检查、污染检测、样本分析及评测指标设计；\n8. 与算法研究、模型训练及产品团队紧密协作，根据模型迭代需求设计评测方案，为模型能力分析提供依据；\n9. 跟踪国内外大模型评测技术的发展，推动优秀评测方法和工程实践在司南OpenCompass评测平台中落地。","requirements":"1. 计算机、软件工程、人工智能或相关专业本科及以上学历；\n2. 具备扎实的计算机基础，熟悉数据结构、网络编程、操作系统、数据库和常用软件设计模式；\n3. 熟练掌握 Python、Go 或 Java 中至少一种后端开发语言，具备良好的代码设计和工程实现能力；熟悉 Python 者优先；\n4. 熟悉 FastAPI、Django、Flask、Gin、Spring Boot 等至少一种主流后端开发框架；\n5. 熟悉 MySQL、PostgreSQL 等关系型数据库，具备数据库表设计、事务处理、索引设计和 SQL 性能优化能力；\n6. 熟悉 Redis、消息队列及异步任务框架中的一种或多种，能够设计长耗时任务的异步执行、状态管理、重试和容错机制；\n7. 具备 Kubernetes 基本概念与使用经验，理解 Pod、Deployment、Service、容器化部署等基础机制；\n8. 熟悉任务调度、分布式系统或数据处理系统相关经验者优先；\n9. 具备良好的系统设计能力，能够设计高并发、高可靠的服务架构；\n10. 具备评测算法技术的理解与工程转化能力，能够阅读算法方案、原型代码，梳理算法流程和工程边界，并将其封装为稳定、可配置、可维护的产品功能；\n11. 有AI平台、机器学习平台、评测系统、实验管理平台（Experiment / Benchmark） 相关经验者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7685295808103565587","sourceKey":"shlab_social","company":"上海AI实验室","title":"评测算法工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7685295808103565587?mode=social","duty":"1. 负责模型评测平台的评测任务执行设计、开发与持续优化，包括模型接入、数据集接入、推理执行、指标计算、结果分析和报告生成等模块；\n2. 建设稳定、高效、可扩展的评测基础设施，支持开源模型、内部模型及主流模型 API 的统一评测；\n3. 将大模型评测相关的算法研究成果工程化落地，包括新评测方法、新指标、自动化评测、主观评测及模型裁判等能力；\n4. 负责各类大语言模型及多模态模型的评测任务，完成评测方案设计、任务配置、资源调度、结果校验和分析报告输出；\n5. 优化大规模评测任务的执行效率与稳定性，解决分布式推理、并发调用、显存管理、任务容错和结果复现等工程问题；\n6. 建设评测数据、配置、实验结果和模型版本的管理机制，保证评测过程可追踪、可复现、可对比；\n7. 参与评测基准和数据集建设，包括数据清洗、质量检查、污染检测、样本分析及评测指标设计；\n8. 与算法研究、模型训练及产品团队紧密协作，根据模型迭代需求设计评测方案，为模型能力分析提供依据；\n9. 跟踪国内外大模型评测技术的发展，推动优秀评测方法和工程实践在司南OpenCompass评测平台中落地。","requirements":"1. 计算机、人工智能、软件工程或相关专业本科及以上学历；\n2. 熟练掌握 Python，具备良好的代码设计、调试和工程实现能力，熟悉常用的软件工程实践；\n3. 并对大模型的基本原理、推理流程及常见模型架构有一定理解；\n4. 熟悉vLLM、LMDeploy、SGLang 等至少一种模型推理或部署框架；\n5. 了解大模型常见评测任务和指标，例如知识问答、推理、代码生成、数学、长文本、指令遵循、安全性以及主观评价等；\n6. 具备较强的问题定位能力，能够独立处理模型加载、推理异常、显存不足、数据格式、并发调用和结果不一致等问题；\n7. 具备大模型评测算法和前沿技术的复现能力，能够阅读相关论文及技术报告，准确理解算法原理，独立完成代码实现、实验验证、结果对齐，并将研究原型转化为可维护、可复用的工程模块。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7685287275907402034","sourceKey":"shlab_social","company":"上海AI实验室","title":"推理系统工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7685287275907402034?mode=social","duty":"· 负责下一代大模型推理系统中具体功能模块（如计算调度、显存管理、模型加载、算子优化等方向）的研发、性能优化与日常维护，确保该模块在高并发、低延迟场景下的稳定与高效。\n· 深入理解并应用推理优化技术（如Continuous Batching、PagedAttention、KV Cache管理等），在资深工程师的指导下将技术方案落地为高质量代码。\n· 承担所负责模块的性能分析与问题定位工作，针对显存、计算、通信等瓶颈进行系统性调优。\n· 参与模块的技术方案设计、代码评审与文档撰写，保证代码的可维护性与可扩展性。\n· 理解并遵循系统的整体架构设计，参与架构相关的技术讨论与评审。\n· 与模型团队、系统团队紧密协作，理解上层业务需求，完成推理系统与周边组件的对接与集成。\n· 关注Agent应用场景对推理系统的需求（如多轮对话状态保持、工具调用、长上下文推理等），确保推理框架能够高效支撑Agent类业务。\n· 持续跟踪vLLM、SGLang等主流框架的最新进展，保持对技术演进的敏感度。","requirements":"· 计算机科学或相关领域本科及以上学历。\n· 2年以上系统软件研发经验，有深度学习推理或训练系统相关经验者优先。\n· 熟练掌握C++（现代C++17/20标准）与Python，具备良好的工程编码习惯与调试能力，熟悉CMake构建体系。\n· 熟悉CUDA编程模型（包括内存层次、Warp调度、Kernel优化等），有实际GPU性能分析和调优经验者优先；了解Cutlass模板库或Tensor Core编程者加分；熟悉NVIDIA Nsight Systems等性能分析工具者优先。\n· 对至少一种主流推理框架（如vLLM、SGLang、TensorRT-LLM）有使用或阅读源码的经验，理解其核心数据结构和调度流程。\n· 了解Agent应用的基本形态（如ReAct循环、工具调用、多轮对话状态管理等），对推理系统如何支撑Agent工作负载有基本的认知和兴趣。\n· 对大型分布式系统或推理系统的整体架构有基本了解者优先。\n· 具备扎实的计算机基础知识（操作系统、计算机网络、数据结构与算法）。\n· 具备良好的问题分析和解决能力，能够在指导下独立完成模块级别的研发任务。\n· 有良好的团队沟通与协作意识，乐于分享与学习。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7685281803453122854","sourceKey":"shlab_social","company":"上海AI实验室","title":"数据算法工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7685281803453122854?mode=social","duty":"面向地球科学智能体与基础模型研发需求，建设可信、可检索、可复用的 AI-Ready 地球科学数据资产。岗位将围绕多源观测数据的采集、质量控制、版本治理和 Benchmark 建设展开，为智能体工具调用、模型训练与科学评测提供统一数据底座。\n\n\n1. 设计地球科学数据治理体系，制定数据接入、时空基准、质量控制、版本与生命周期管理规范；建设数据基础设施与多源数据管线；\n2. 构建数据资产目录；建设 AI-Ready 数据集与 Benchmark，提供自动化数据构建能力，支撑建模与科学发现任务。","requirements":"1. 硕士及以上，理工科相关专业；\n2. 具有机器学习 / 人工智能相关经验，或地球科学研究背景；\n3. 熟悉地球科学领域科学数据，有 ERA5、GFS、FY 卫星、Himawari、MODIS、Sentinel 等再分析、气象、遥感或站点数据处理经验者优先；\n4. 具备扎实的工程化能力，能使用 Python / SQL 完成数据接入、自动化处理、统一存储、数据目录、数据 API、测试与文档等数据基础建设。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7685281407384930623","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型算法研究员/工程师（能源电力方向）","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7685281407384930623?mode=social","duty":"面向新型电力系统的真实问题，研究大模型与智能体驱动的新能源预测、电网暂稳态计算与感知、运行风险推理及调度运行决策，融合电力系统机理、科学数据与仿真工具，构建“预测—感知—推理—决策—验证”的闭环，探索模型与智能体在环境反馈中的持续学习与自进化。\n\n1. 开展新能源功率预测与电网暂稳态计算、状态感知研究，探索融合多源数据、电网拓扑与物理机理的模型方法；\n2. 研发电网风险推理与调度决策大模型及智能体，实现运行状态理解、风险分析、优化建模与决策方案生成。","requirements":"1. 硕士及以上学历，计算机、人工智能、电气工程、自动化、应用数学等相关专业；\n2. 具有机器学习、大模型或智能体研究经验，或具备电力系统分析、预测、优化与控制研究基础，有志于开展 AI 与能源电力交叉研究；\n3. 具有新能源预测、潮流计算、状态估计、暂态稳定分析或调度优化经验者优先；\n4. 具有大模型训练、强化学习、智能体工具调用、物理约束学习或电力仿真与优化工具使用经验者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7685280474328238363","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型算法工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7685280474328238363?mode=social","duty":"1. 多模态基座大模型与世界模型训练：开展大语言模型 SFT / RL / OPT，以及多模态模型、世界模型训练研究；\n2. 科研智能体：围绕 Agent Harness、Agentic Training 等技术，搭建智能体驱动的科学发现系统；\n3. 科学数据处理：对天文领域图像/序列以及其他结构化信号进行大规模处理，以满足人工智能训练规范。","requirements":"1. 硕士及以上，计算机等相关专业；\n2. 具有机器学习、人工智能相关经验，或自然科学研究背景；\n3. 有大模型开发、训练、智能体开发经验者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7685260524792170795","sourceKey":"shlab_social","company":"上海AI实验室","title":"资深推理系统架构师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7685260524792170795?mode=social","duty":"· 负责面向下一代大模型推理系统的核心架构设计与研发，探索并实现更高效率、更低成本的推理服务方案。\n· 深入研究并应用前沿推理优化技术（如模型量化、剪枝、稀疏化、Continuous Batching、PagedAttention 等），并将其落地于实际生产环境。\n· 负责推理框架在复杂负载下的性能调优与稳定性建设，系统性解决高并发、长序列场景中的计算、显存与延迟瓶颈。\n· 带领技术团队攻克推理系统研发中的关键技术难题，输出高质量的代码实现与系统设计文档。\n· 参与制定推理系统的技术演进路线图（Roadmap），推动关键节点的规划与落地。\n· 积极参与开源社区建设，与业界技术专家保持交流，持续跟踪前沿技术动态。\n· 指导团队成员进行技术方案选型、系统设计与代码评审，提升团队整体技术能力。\n· 与模型训练团队、算法团队及基础设施团队紧密协同，推动大模型在复杂业务场景中的高效部署与规模化落地。","requirements":"· 计算机科学或相关领域硕士及以上学历，博士优先。\n· 5年以上系统软件研发经验，其中至少3年以上大模型推理或深度学习系统相关经验。\n· 精通C++与Python编程，深入理解CUDA编程模型及GPU硬件体系架构。\n· 对主流推理框架（如vLLM、SGLang、TensorRT-LLM）有深入理解和丰富的二次开发或优化经验。\n· 熟悉常见的推理优化技术体系，对显存管理、计算调度、模型压缩等方向有实践经验。\n· 具备优秀的系统问题分析与复杂问题排查能力，能够独立主导大型模块的研发与交付。\n· 有带领技术团队完成复杂项目的实际管理经验，具备良好的跨团队沟通与协作能力。\n· 有AI系统或高性能计算领域开源项目核心贡献者经验者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7684140915950881062","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型及智能体后训练工程师/青年研究员","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7684140915950881062?mode=social","duty":"1、参与大模型及智能体模型的后训练研究与能力提升，围绕 SFT、强化学习、偏好优化、自我改进（Recursive Self-Improvement）等方向开展算法研究与工程实现。\n2、参与 Agent RL 训练与优化，重点提升模型在代码生成、复杂任务规划、长时程推理、多轮交互、错误恢复等真实任务中的能力等。\n3、参与构建面向后训练的高质量数据与训练 pipeline，包括高质量轨迹数据、偏好数据、错误修复数据、任务规划数据、多轮交互数据等，并研究数据筛选、难度控制与自动化生成方法。\n4、参与大模型强化学习算法研究与实验，包括 reward 设计、rollout、credit assignment、on-policy / off-policy learning、训练稳定性与效率优化等。\n5、参与模型自我改进与 Agent Self-Evolution 方向研究，探索数据生成—训练—评测—再生成的闭环训练机制，提升模型持续学习和复杂任务解决能力。\n6、构建和优化面向 Coding Agent、Auto-Research 等任务的评测体系，并参与模型能力分析、实验设计、训练调参和问题定位。","requirements":"1、硕士及以上学历，计算机、人工智能、软件工程、数学、自动化等相关专业优先。\n2、编程基础扎实，熟练使用 Python，熟悉 PyTorch / Transformers 等大模型训练框架。\n3、熟悉大模型基本原理，对 SFT、GRPO和OPD等后训练方法有理解或实践经验。\n4、对大模型后训练、Agent RL、Reasoning、Coding Agent、Self-Improvement 等方向有较强兴趣。\n5、 具备较强的实验能力，能够独立完成实验设计、训练调参、结果分析和问题定位。\n\n【加分项】\n1、熟悉 LLaMA-Factory、verl、msswift、Megatron-LM、vLLM、sglang 等训练或推理框架者优先。\n2、有大模型 SFT / RL、Reward Model、Preference Learning 或 Agent RL 实践经验者优先。\n3、有高质量训练数据构造、Agent trajectory 生成、偏好数据构建、自动数据生成等经验者优先。\n4、有 SWE-Bench、ALE-Bench 和 Auto-Research等相关评测经验者优先。\n5、有相关论文、开源项目、大模型训练项目或较强工程实践经验者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7684101652311935283","sourceKey":"shlab_social","company":"上海AI实验室","title":"数学研究级推理青年研究员/工程师","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7684101652311935283?mode=social","duty":"参与实验室书生大模型数学研究级推理智能体的强化学习与自进化研究，提升模型在复杂数学问题分析、证明推导和研究探索等场景中的自主推理能力。具体工作内容包括：\n1. 参与数学研究级推理智能体的强化学习算法研发，面向定理证明、猜想探索、数学问题分析、证明验证和研究思路生成等任务，提升模型的复杂推理能力；\n2. 研究适用于数学研究场景的奖励建模、过程监督、结果校验和环境反馈机制，探索对数学推理过程进行细粒度评价和有效优化的方法；\n3. 参与数学研究级推理智能体的自进化训练流程建设，围绕问题生成、解题规划、证明执行、结果验证、反思修正和经验积累等环节，构建闭环迭代机制；\n4. 参与构建高质量数学研究推理数据集、任务集和评测体系，覆盖数学知识理解、长链条推理、形式化证明、开放性问题探索等能力维度；\n5. 基于数学专业知识分析模型在复杂推理过程中的错误模式、能力瓶颈和泛化问题，并从算法、数据和训练流程等角度提出优化方案；\n6. 参与文本和智能体强化学习相关技术研发，推动数学研究级推理方案在不同模型规模和任务场景中的实验验证与工程落地；\n7. 跟踪 AI for Math、大模型推理、智能体强化学习及自进化等方向的前沿研究，推进相关方法的复现、改进和应用。","requirements":"1. 硕士及以上学历，数学、计算机科学、人工智能、统计、电子工程等相关专业优先，数学或计算机方向博士优先；\n2. 具备扎实的数学基础和较强的数学推理能力，对纯数学、应用数学或数学计算研究有深入了解；\n3. 熟悉大模型后训练、强化学习和智能体相关技术，了解文本强化学习、环境反馈强化学习、奖励建模或过程监督等方法；\n4. 熟练使用 Python、PyTorch 等工具，具备较强的科研编程和实验分析能力；\n5. 具备较强的论文阅读、问题抽象、算法设计和结果分析能力，能够将数学问题转化为可评测、可训练和可迭代的任务；\n6. 对 AI for Math、数学研究级推理智能体和人机协同数学研究具有浓厚兴趣；\n7. 目标导向、自驱力强，具备良好的沟通协作和项目推进能力；\n8. 有数学科研、定理证明、形式化数学、数学竞赛、顶会论文或大模型推理相关经验者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7684100325015324954","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型智能体强化学习青年研究员/算法工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7684100325015324954?mode=social","duty":"参与实验室书生大模型智能体强化学习长稳训练相关的算法研发、工程建设与优化迭代，提升模型在复杂、多轮、长时程任务中的持续交互、任务执行和自主决策能力。具体工作内容包括：\n1. 参与智能体强化学习长稳训练方案的设计与研发，面向网页浏览、工具调用、代码执行、复杂任务规划及多轮交互等场景，提升智能体的任务完成能力和交互稳定性；\n2. 研究和优化适用于长时程智能体任务的强化学习算法，重点关注长链路信用分配、稀疏反馈、过程奖励、轨迹筛选、失败恢复和策略稳定性等问题；\n3. 参与智能体训练环境、任务编排、工具调用、状态管理、轨迹采集和反馈评价等基础设施建设，提升训练系统的可扩展性和实验效率；\n4. 参与奖励模型、环境评价器、过程监督模型和结果校验模型的研发，构建覆盖任务过程与最终结果的多粒度反馈机制；\n5. 负责智能体强化学习实验的设计、执行和分析，定位训练过程中的不稳定、退化、奖励投机和泛化不足等问题，并推动算法与工程方案迭代；\n6. 参与长稳训练相关数据集、任务集和评测体系建设，建立面向多轮交互、复杂任务执行和长期自主运行的能力评估方法；\n7. 跟踪智能体强化学习、环境交互学习和大模型后训练领域的前沿进展，推进相关论文复现和技术成果落地。","requirements":"1. 本科及以上学历，计算机科学、人工智能、数学、统计、电子工程等相关专业优先；\n2. 熟悉大模型、强化学习和智能体相关技术，对文本、多模态或智能体强化学习有研究或工程实践经验；\n3. 理解 PPO、GRPO、RLHF、RLAIF、奖励建模、过程监督、环境反馈和多轮强化学习等相关方法；\n4. 熟练使用 Python、PyTorch 等语言和代码库，有 Ray、分布式训练、智能体框架、环境构建或大模型训练系统经验者优先；\n5. 对智能体长时程训练中的任务规划、工具使用、轨迹建模、奖励设计和训练稳定性有较强兴趣或实践经验；\n6. 具备较强的工程实现、实验分析和问题定位能力，能够将算法方案转化为稳定可复现的训练流程；\n7. 目标导向，自驱力强，具备良好的团队协作和沟通能力；\n8. 拥有高水平论文、知名竞赛获奖、顶级研究机构或大模型智能体相关经验者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7684098206242638123","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型强化学习青年研究员/算法工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7684098206242638123?mode=social","duty":"参与实验室书生大模型后训练阶段文本、多模态及智能体强化学习算法的研发与迭代，推动强化学习技术在复杂推理和真实应用任务中的效果提升。具体工作内容包括：\n1. 参与文本、多模态和智能体场景下强化学习算法的研发与优化，覆盖复杂推理、代码、指令遵循、工具调用、网页浏览和多轮交互等任务；\n2. 参与基于模型反馈、环境反馈和用户反馈的强化学习方案设计，探索适用于不同任务和不同模型阶段的奖励构建、策略优化和训练方法；\n3. 参与奖励模型、过程评价模型、结果校验模型及相关训练数据集的构建与迭代，提升反馈信号的准确性、稳定性和泛化能力；\n4. 负责强化学习实验的设计、执行和分析，系统评估不同算法、数据和训练配置对模型能力的影响，并推动有效方案持续迭代；\n5. 参与大模型强化学习训练系统的工程实现与性能优化，提升训练效率、资源利用率和实验稳定性；\n6. 跟踪大模型后训练和强化学习领域的最新研究进展，结合业务和模型需求推进论文复现、技术验证和方案落地。","requirements":"1. 本科及以上学历，计算机科学、人工智能、数学、统计、电子工程等相关专业优先，硕士及以上学历优先；\n2. 熟悉大模型后训练和强化学习相关研究工作，对文本、多模态强化学习有一定研究或实践经验；\n3. 了解 PPO、GRPO、RLHF、RLAIF、奖励建模、过程监督、环境反馈强化学习等方法，有大模型强化学习算法研发经验者优先；\n4. 熟练使用 Python、PyTorch 等编程语言和深度学习框架，熟悉 Ray、分布式训练或大模型训练系统者优先；\n5. 具备较强的论文阅读、实验设计、问题分析和结果判断能力，能够系统性对比相关研究成果并制定改进方案；\n6. 目标导向，具备良好的团队协作和沟通能力，能够承担从问题分析、方案设计到实验验证和落地迭代的完整工作；\n7. 拥有高水平论文、知名竞赛获奖、顶级研究机构或大模型相关工作经验者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7683112927079123250","sourceKey":"shlab_social","company":"上海AI实验室","title":"产品运营中心高级主管 - 科研产品平台部","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7683112927079123250?mode=social","duty":"1、负责产品运营中心的整体规划与团队管理，制定阶段目标、资源配置、工作机制和评价体系，对核心运营结果负责。\n2、围绕产品战略，搭建用户增长、用户成功、科研生态、内容社区、活动赛事、数据运营及成果案例等运营体系。\n3、统筹重大活动、赛事、产品发布和社区运营，重点推动活动后的用户转化、能力沉淀和案例产出，而非停留在曝光层面。\n4、建立全链路运营指标体系，统一用户、活跃、留存、科研任务、数据贡献、机构合作及成果案例等关键口径，推动数据驱动的运营决策。\n5、负责核心用户与合作机构的分层经营，建立从机构触达、产品使用、联合共创到标杆示范的转化机制。\n6、建立科研成果发现、培育与案例化机制，推动优秀科研实践形成可验证、可传播、可复制的标杆成果。\n7、推动高校、科研院所、实验室、企业及专家团队开展科研场景共创，促进真实科研任务进入平台并形成持续使用。\n8、建立科研用户成功机制，推动用户上手、任务激活、深度使用、需求反馈和问题闭环。\n9、持续沉淀用户、机构、内容、数据、案例、媒体及运营方法等长期资产，形成可复用、可规模化的运营模式。\n10、与产品、研发、科研、市场及外部合作团队紧密协作，推动运营洞察进入产品规划和迭代闭环。","requirements":"1、本科及以上学历，5年以上互联网、人工智能、科技平台或专业产品运营经验，具备团队管理经验。\n2、具备从0到1搭建运营体系的经验；有带领业务实现规模化增长经历者优先。\n3、能够兼顾战略规划、组织管理与一线业务推进，对业务结果负责。\n4、对用户增长、用户成功、社区生态、机构合作和数据运营有系统理解，不局限于活动或内容运营。\n5、具备较强的目标拆解、指标设计和经营分析能力，能够通过数据识别问题并推动解决。\n6、具备复杂项目管理和多方协同经验，能够与科研、产品、研发团队及外部机构高效合作。\n7、具备较强的用户洞察和产品意识，能够将用户需求与运营反馈转化为明确的产品改进建议。\n8、责任心强，具有主动判断、资源组织和推动结果落地的能力。\n9、对AI、大模型或AI for Science保持持续兴趣，能够快速理解技术能力及其应用边界。\n优先条件\n1、有AI产品、大模型平台、开发者平台或科研平台运营经验；\n2、有高校、科研院所、实验室或科技企业生态建设经验；\n3、有从用户使用、数据沉淀到产品迭代和成果案例形成的完整实践；\n4、有重大产品发布、行业赛事或大型生态项目统筹经验。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7683111551720704299","sourceKey":"shlab_social","company":"上海AI实验室","title":"产品运营主管（科研生态运营）- 科研产品平台部","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7683111551720704299?mode=social","duty":"1、负责高校、科研院所、重点实验室、企业及专家团队等科研生态的拓展与持续运营。\n2、建立合作机构及科研用户的分层管理体系，维护专家、PI、课题组和核心用户关系。\n3、深入理解不同学科的科研流程与真实需求，识别适合AI产品介入的高价值场景。\n4、通过用户访谈、场景调研和需求分析，将科研需求转化为产品建议、共创课题或运营方案。\n5、推动科研机构和课题组使用产品，组织产品培训、工作坊、种子用户计划及重点课题陪跑。\n6、协同产品、研发及科研团队推进联合共创，持续跟踪从方案设计、产品使用到反馈优化和成果形成的全过程。\n7、挖掘代表性科研实践，沉淀学科解决方案、科研工作流模板、用户案例和标杆成果。\n7、参与学术会议、科研赛事及学科社区合作，关注活动后的用户激活、持续使用和成果转化。\n8、建设科研生态资源库，沉淀机构画像、专家网络、合作记录、科研场景及案例资产。\n","requirements":"1、本科及以上学历，3年以上科研平台、科技产品、学术合作、产业生态或专业用户运营经验。\n2、了解高校、科研院所和课题组的组织方式、科研流程及合作特点。\n3、具备较强的沟通访谈、需求分析和关系维护能力，能够与科研人员及产品研发团队有效协作。\n4、具备复杂项目推进能力，能够持续跟踪合作并推动真实使用和成果落地。\n5、具备良好的文字表达能力，能够独立完成合作方案、调研报告、案例材料和运营复盘。\n6、主动性和责任心强，能够在信息不完整、协作方较多的情况下推动工作落地。\n7、对人工智能、大模型及AI for Science保持兴趣，具备快速理解新技术和新学科的能力。\n优先条件\n1、理工科、生命科学、材料、化学、地球科学或计算机等专业背景；\n2、有高校、科研院所、国家实验室或科技企业合作经验；\n3、有科研项目管理、技术转移、学术会议或科学传播经验；\n4、有AI科研产品、科研数据库、开发者平台或专业软件运营经验；有推动机构合作走向产品使用、联合共创和成果案例的完整实践。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7683051876145793306","sourceKey":"shlab_social","company":"上海AI实验室","title":"具身智能强化学习算法工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7683051876145793306?mode=social","duty":"团队介绍\n团队面向真实机器人操作任务，研究基于视觉—语言—动作模型（VLA）、世界模型（World Model）和强化学习的机器人自主学习方法，重点探索机器人在真实环境中的持续数据采集、策略优化、失败恢复、多任务学习及跨本体能力迁移。\n\n我们希望招聘一名具有较强算法基础和工程实践能力的硕士毕业生，共同推进相关算法从研究原型到真实机械臂系统的落地。\n\n\n岗位职责\n1. 参与VLA与World Model驱动的真机强化学习系统研发，打通数据采集、策略训练、真机执行、反馈评估和持续更新闭环；\n2. 研究goal-conditioned VLA、结构化视觉子目标、价值/进度评估、失败恢复及安全探索等关键技术；\n3. 负责机械臂操作任务的真机部署与实验，包括标定、感知、策略推理、动作执行、数据记录和问题定位；\n4. 建设真机RL训练与评测基础设施，包括异步采样、Replay管理、自动化评测、模型版本管理和实验可视化；\n5. 参与多机械臂并行数据采集、多任务学习以及同构/异构机械臂之间的知识共享与能力迁移；\n6. 跟踪机器人学习、VLA、World Model和强化学习领域的前沿工作，完成算法复现、改进及实验验证；\n7. 参与论文、专利、技术报告及开源项目等科研成果产出。\n\n","requirements":"岗位要求\n1. 计算机、人工智能、自动化、机器人、控制、电子信息等相关专业硕士学历；\n2. 熟练使用Python，具备良好的PyTorch编程能力，熟悉Linux、Git及基本软件工程流程；\n3. 对强化学习、模仿学习、机器人学习、VLA或World Model中的至少一个方向有较深入理解；\n4. 能够阅读英文论文，并将论文方法转化为可运行、可验证的代码和实验；\n5. 具备较强的实验分析和问题定位能力，能够根据日志、数据和可视化结果分析模型失败原因；\n6. 具有良好的沟通协作能力、责任心和持续学习能力，愿意参与真实机器人系统的部署与调试。\n\n加分项\n1. 有机械臂操作、ROS/ROS2、仿真环境或真实机器人部署经验；\n2. 有强化学习或模仿学习项目经验，实际完成过数据采集、训练、评测和部署闭环；\n3. 熟悉Diffusion Policy、Flow Matching、Action Chunking、Goal-conditioned RL、Offline RL等方法；\n4. 熟悉VLA模型、视觉语言模型、视频生成/预测模型或机器人世界模型；\n5. 有目标检测、分割、跟踪、位姿估计、多视角视觉或力觉处理经验；\n6. 有多机并行采样、分布式训练、异步数据管线或跨机器人迁移经验；\n7. 在机器人、计算机视觉、机器学习相关会议发表过论文，或有高质量开源项目和竞赛成果。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7682997093649172762","sourceKey":"shlab_social","company":"上海AI实验室","title":"AI编译器与异构计算青年研究员/青年科学家","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7682997093649172762?mode=social","duty":"我们正在寻找一位在 AI 编译器、计算框架和异构芯片优化领域具有丰富经验的资深人才。该职位负责推动 AI 模型在 NVIDIA GPU及国产 AI 芯片上的适配与性能优化，建设软硬件协同技术能力。\n主要职责：\n1、负责 AI 模型在 NVIDIA及国产 AI 芯片上的迁移、适配和性能优化。\n2、设计软硬件协同技术架构，打通模型、框架、编译器、算子、运行时和硬件后端。\n3、开展计算图、动态 Shape、算子融合、内存管理、自动调优和代码生成等编译优化工作。\n4、针对大模型训练与推理，优化计算、显存、通信、吞吐和延迟。\n5、跟踪 AI 编译器、异构计算及国产芯片技术发展，推动关键技术攻关和项目落地。","requirements":"1、计算机、电子工程、人工智能等相关专业本科及以上学历。\n2、5 年以上 AI 框架、编译器、高性能计算或芯片软件栈研发经验。\n3、熟悉 PyTorch、TensorFlow、JAX或MindSpore等框架的内部机制。\n4、熟悉 LLVM、MLIR、XLA、TorchInductor、Triton或TVM中的一种或多种。\n5、深入理解 NVIDIA GPU、CUDA及相关加速库；具备国产 AI 芯片适配经验。\n6、熟悉计算图优化、Kernel优化、动态 Shape、混合精度、量化及内存优化。\n7、具备复杂技术问题分析、跨团队协作和技术方案落地能力。\n优先考虑：\n1、参与过 AI 编译器、框架、算子库或大模型推理系统核心研发。\n2、具备国产芯片完整适配或 CUDA/Triton Kernel优化经验。\n3、在相关开源社区有贡献，或拥有论文、专利及大型项目落地经验。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7681189806655981862","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型安全智能体青年研究员/工程师","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7681189806655981862?mode=social","duty":"参与安全场景下的大模型训练和智能体研发，围绕模型后训练、Agent 能力构建、任务环境及自动化评测开展研究与工程实践，将算法方案转化为可训练、可运行和可验证的智能体系统。\n\n1.参与大模型训练与后训练，包括数据及轨迹构建、SFT、强化学习、奖励设计和效果评测；\n2.研发安全场景智能体，实现任务规划、工具调用、环境交互、记忆管理和反思纠错等能力；\n3.构建安全、代码和长程复杂任务，研究模型的风险识别、权限理解、可靠执行和异常恢复能力；\n4.参与 rollout、模型推理、任务环境和自动验证等训推框架建设，保障实验效率、稳定性和可复现性；\n5.分析模型训练与 Agent 执行轨迹，定位任务失败、奖励投机、工具异常和安全风险，并形成数据及算法改进闭环。","requirements":"1.了解大语言模型的训练与后训练流程，在模型训练或 LLM Agent 开发方面具有实践经验；\n2.熟练使用 Python、PyTorch 等工具，能够独立完成模型实验或多模块智能体系统开发；\n3.熟悉 SFT、强化学习、工具调用、RAG、规划或自动化评测中的一种或多种技术；\n4.具备基本的 Linux、Docker 和工程环境搭建能力，能够完成可复现的训练与评测实验；\n5.具备良好的问题分析和任务拆解能力，对安全智能体、Agentic RL 或模型安全有长期兴趣。\n加分项\n有 Agentic RL、Coding Agent、Computer-Use Agent 或长程任务智能体经验；\n有分布式训练、模型推理、rollout 系统或自动验证器开发经验；\n有模型红队、提示注入防御、权限控制、网络安全或代码安全经验；\n有高质量论文、开源项目、竞赛或完整 AI 系统交付经历。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7679026624230426907","sourceKey":"shlab_social","company":"上海AI实验室","title":"安全算法工程师/青年研究员","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7679026624230426907?mode=social","duty":"1. 负责面向网络安全的AI智能体研究，构建面向渗透测试、漏洞挖掘与利用的智能体框架，实现多种安全工具的协同编排，推动漏洞发现、验证及PoC/Exploit生成的自动化，并在真实授权攻防场景中验证实战效果；\n2. 负责AI智能体网络安全能力测试，构建覆盖安全知识、工具调用、漏洞发现、漏洞利用及长程攻防等能力的评测体系、测试环境与自动化平台，实现对模型及智能体安全能力的系统评估与细粒度画像；\n3. 负责基于AI智能体的网络安全数据生产，利用智能体自动完成漏洞环境构建、攻防任务生成、执行轨迹采集及结果验证，沉淀可用于模型训练、强化学习和能力评测的高质量安全数据。","requirements":"1. 本科及以上学历，计算机科学、信息安全、网络空间安全、软件工程或相关专业背景优先，一年及以上安全领域工作经验者优先；\n2. 具备扎实的机器学习和深度学习基础知识和算法实践能力，了解大模型的设计和训练流程；\n3. 具备安全研究基础，熟悉常见漏洞类型（如内存破坏、逻辑漏洞、Web漏洞等）的原理与利用技术，熟练使用IDA Pro、Ghidra、GDB、AFL、Burp Suite等至少一种逆向分析或漏洞挖掘工具，有代码审计经验、CTF竞赛经验或CVE/CNVD发现经历者优先；\n4. 熟悉常用的深度学习框架和工具，具备良好的编程能力，熟练使用Python、C/C++等编程语言；具备安全工具开发或AI Coding工具安全场景定制经验者优先；\n5. 在CVPR、NeurIPS、ICLR等人工智能会议或CCS、S&P、USENIX Security、NDSS、Black Hat等安全顶会有出色发表记录者优先。\n加分项：\n1. 在信息学奥赛、ACM、CTF竞赛（如DEF CON CTF、XCTF等）中获奖；\n2. 具备渗透测试、漏洞挖掘、逆向分析、模糊测试、符号执行等项目经验；\n3. 参与过开源安全工具/框架的开发与维护，或在CNVD、CVE等平台提交过高质量漏洞，有PoC/Exploit开发经验者；\n4. 熟悉V8/Chromium、JavaScript/WebAssembly及浏览器漏洞利用者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7679017810878712100","sourceKey":"shlab_social","company":"上海AI实验室","title":"基模算法青年研究员","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7679017810878712100?mode=social","duty":"1.深度参与模型训练数据优化的核心技术研发，包括预/中/后训练阶段的数据筛选与合成方法，提升模型在复杂场景的高阶处理能力（超过200轮次的长程任务执行、精准的复杂领域工具调用等）；\n2.开展模型后训练阶段的算法研究，包括但不限于：OPD，DAPO，GSPO等RL训练方法，提升模型特别是长程规划与代码能力；\n3.探索模型自进化的相关算法研究，包括但不限于：提升模型驱动的data/infra/training设施自优化，terminal world model等。","requirements":"1.有强烈的技术追求和和热情，希望参与解决现实世界极具挑战的问题；\n2.具备优秀的研究素养和创新能力，在国际顶会或期刊发表过高质量论文；\n3.有良好的工程和动手能力，能够广泛利用各种工具解决问题；\n\n加分项\n有大规模分布式训练相关经验、在理解算法原理的同时，也掌握实现细节者优先；\n有ACM/NOI/超算等各类竞赛获奖经历者优先；\n有参与基座模型训练或有行业影响力项目优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7679017516383602980","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型训练数据Infra算法工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7679017516383602980?mode=social","duty":"1.设计并实现训练数据 Pipeline，覆盖数据解析、清洗、过滤、去重、质量评估、分类采样等核心环节；\n2.优化数据处理管线的并发能力，包括模型推理速度、任务调度、资源使用、吞吐量与稳定性；\n3.参与数据质量的评估与数据管理设施的搭建。","requirements":"1.有强烈的技术追求和和热情，希望参与解决现实世界极具挑战的问题；\n2.具备优秀的研究素养和创新能力，在国际顶会或期刊发表过高质量论文；\n3.有良好的工程和动手能力，能够广泛利用各种工具解决问题；\n\n加分项\n有大规模分布式数据系统（如Ray、Flink、Kafka、Parquet、Arrow、Harbor）经历优先；\n有ACM/NOI/超算等各类竞赛获奖经历者优先；\n有参与基座模型或有行业影响力项目优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7679014206129981742","sourceKey":"shlab_social","company":"上海AI实验室","title":"智能体安全算法工程师","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7679014206129981742?mode=social","duty":"参与智能体安全评测相关工作： 构建数据测试智能体的安全性能，分析新一代AI的潜在安全风险边界，设计评测体系；\n1.参与解决智能体安全对齐的问题，包括内对齐、外对齐等，和团队合作开发RLVR等强化学习技术，以及对前沿强化学习路线研究，通过训练或推理时对齐提升智能体安全；\n2.参与智能体环境搭建相关工作：根据需要的Agent环境，如电脑、手机、网络环境等，使用docker进行环境搭建；\n3.参与网络安全攻防与评测。参与智能体在网络安全场景下的攻击、防御及能力评测工作，构建面向真实或仿真环境的安全任务与评测基准，分析智能体在漏洞发现、攻击规划、工具调用及防御响应等环节的能力与风险。","requirements":"1.本科及以上学历，计算机科学、电子信息、信息安全或相关专业背景优先；\n2.具备扎实的机器学习和深度学习基础知识和算法实践能力，了解Agent的设计和训练流程，熟练使用docker；\n3.ACM等编程竞赛获奖者，熟悉大模型相关研究的前沿进展，有顶会论文（如NeurIPS, CVPR, CCS等）优先；\n4.扎实的编程基础，对数据结构、算法设计基础有深度了解，熟练掌握Python/C++等主流语言一种或多种；\n5.熟悉SFT、RLHF、GRPO等后训练方法和框架，能基于实际业务问题，设计合理、高效训练流程；\n6.有安全领域相关评测或对齐经验优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7679013523556682020","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型内生安全青年科学家/研究员","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7679013523556682020?mode=social","duty":"1.研究大模型内生安全机制，分析模型在预训练、后训练及推理阶段产生越狱、欺骗、偏见、有害输出等风险的内部成因；\n2.探索面向安全的大模型架构与训练方法，研究注意力机制、表征空间、残差通路、稀疏激活及 MoE 路由等结构与模型安全行为之间的关系；\n3.研发大模型对齐、可解释性、鲁棒性及可控生成技术，包括安全对齐训练、机制可解释、表示干预、激活引导、安全解码和对抗训练等；\n4.跟踪大模型内生安全与可信人工智能前沿进展，推动研究成果在实际模型训练、部署及安全治理场景中的应用。","requirements":"1.计算机科学、人工智能、网络安全或相关专业硕士及以上学历，博士优先；具备大模型安全、可信人工智能或相关方向研究经历者优先；\n2.具备扎实的机器学习和深度学习基础，对 Transformer、MoE 等大模型架构有较深入理解，熟悉注意力机制、位置编码、归一化、残差连接、路由机制及解码策略；\n3.熟悉模型对齐、机制可解释性、对抗鲁棒性、模型后门或安全评测等方向中的一个或多个领域；有高水平论文、开源项目或实际成果者优先；\n4.具备较强的科研创新能力、问题抽象能力和逻辑分析能力，对大模型内生安全研究充满热情，并具备良好的跨团队协作能力。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7679012692174080310","sourceKey":"shlab_social","company":"上海AI实验室","title":"前沿智能体安全青年科学家/青年研究员","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7679012692174080310?mode=social","duty":"1.研究AI驱动的自动化漏洞挖掘与利用技术，包括构建智能攻防Agent框架，实现多工具协同编排（调试器、反编译器、模糊测试框架、符号执行引擎等），完成从漏洞发现到PoC/Exploit生成的全自动化转化；\n2.参与智能体安全评测相关工作，构建数据测试智能体的安全性能，分析新一代AI的潜在安全风险边界，设计评测体系；\n3.参与解决智能体安全对齐的问题，包括内对齐、外对齐等，和团队合作开发RLVR等强化学习技术，以及对前沿强化学习路线研究，通过训练或推理时对齐提升智能体安全；\n4.主攻前沿AI风险建模、量化识别及可信治理研究，重点攻坚模型对齐失效、数据污染、失控衍生安全风险等关键课题，构建全维度动态风险研判与感知体系。","requirements":"1.硕士及以上学历，计算机科学、人工智能、网络空间安全或相关专业背景优先；\n2.ACM等编程竞赛获奖者，熟悉大模型相关研究的前沿进展，有顶会论文（如NeurIPS, CVPR, CCS等）优先；\n3.扎实的编程基础，对数据结构、算法设计基础有深度了解，熟练掌握Python/C++等主流语言一种或多种；\n4.熟悉SFT、RLHF、GRPO等后训练方法和框架，能基于实际业务问题，设计合理、高效训练流程；\n5.有安全领域相关攻防或对齐经验优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7678997010829412634","sourceKey":"shlab_social","company":"上海AI实验室","title":"安全数据全栈算法工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7678997010829412634?mode=social","duty":"1.负责核心数据全栈架构的设计与开发，打通从数据采集、清洗、存储、计算到模型训练/推理的端到端链路，保障海量数据的高效流转与高质量交付。\n2.深入理解业务场景，主导数据算法的研发与迭代，将算法模型与工程架构深度融合，解决复杂的数据处理与分析难题。\n3.参与构建和优化数据基础设施（Data Infra），提升数据处理平台的吞吐量、稳定性和计算效率，为上层算法提供强有力的底层支撑。\n4.结合网络安全业务背景，探索安全场景下的数据价值挖掘，利用算法手段提升安全威胁检测、日志分析、行为建模等业务的智能化水平。","requirements":"1.计算机、软件工程、信息安全或相关专业本科及以上学历，具备扎实的数据结构、算法与计算机网络基础。\n2.具备出色的Coding能力，熟练掌握Python/C++/Go/Java中至少两种语言，拥有优秀的工程实践与代码规范意识。\n3.拥有“数据全栈”视野与实战经验，既懂算法模型（机器学习/深度学习），又精通大数据工程（如Spark/Flink/Hadoop等），能独立主导数据链路的开发与优化。\n4.具备网络安全行业背景，熟悉安全领域的数据特征、日志分析、威胁情报或攻防对抗相关技术者优先。\n5.具备极强的自驱力、复杂问题分析能力和跨团队协作能力，能够作为核心技术骨干推动关键项目的落地。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7678994798980303146","sourceKey":"shlab_social","company":"上海AI实验室","title":"强化学习算法工程师（AI Coding / Agentic RL方向）","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7678994798980303146?mode=social","duty":"1.负责大模型在AI Coding场景下的强化学习（RL）算法研发与训练，探索并落地PPO、GRPO等主流算法，提升模型在复杂代码生成、长程规划与工具调用任务中的自主推理与执行能力;\n2.参与构建端到端的Agentic RL训练链路，结合过程奖励机制（Process Reward）与Critic Model，优化Agent在真实环境中的行为引导、指令跟随与自我反思能力;\n3.负责AI Coding相关高质量RL训练数据的挖掘、合成与评测体系设计，针对模型能力短板构建可验证的训练闭环，持续提升模型在前沿Benchmark及真实业务场景中的表现;\n4.与算法、Infra团队紧密协作，参与RL训练系统的性能优化与工程化落地，解决训推分离场景下的大规模训练稳定性、吞吐瓶颈及长尾任务问题。","requirements":"1.计算机、人工智能、软件工程等相关专业本科及以上学历，具备2年以上大模型强化学习或AI Agent相关研发经验。\n2.具备扎实的强化学习基础，深入理解PPO、GRPO等算法原理，有实际跑通并优化过RL训练Pipeline的完整经验。\n3.在AI Coding、代码基座模型或Agentic RL方向有实际项目落地经验，熟悉代码生成、自动修复、测试框架等场景的RL训练方法。\n4.具备出色的代码能力与工程素养，熟练掌握Python，熟悉C++/Go/Rust中至少一种系统级语言，具备良好的代码规范与问题定位能力。\n5.对模型行为有较强洞察力，能够结合实际问题独立分析失败案例，设计Reward信号并持续迭代训练方案。\n\n加分项\n具备强化学习Infra或分布式训练系统背景，熟悉Ray、DeepSpeed、Megatron-LM、vLLM等框架，有大规模RL训练平台的开发或优化经验者优先。\n有开源项目贡献经历，或在ACM/ICPC、Kaggle等知名竞赛中取得优异成绩。\n熟悉Code Harness、Runtime环境构建，或有过Long Horizon Task相关的训练与评测经验。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7678926161595304238","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型后训练青年研究员/工程师","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7678926161595304238?mode=social","duty":"面向安全、代码和复杂工程场景，研究大模型智能体后训练与 Agentic RL 技术，负责从任务、环境和训练到评测及系统优化的完整技术链路，推动模型能力、安全性与训推效率协同提升。\n\n1.负责安全场景及长程复杂任务下的大模型后训练和 Agentic RL 技术研究，制定技术路线并推动落地；\n2.建设任务定义、数据与轨迹构建、奖励及验证器设计、强化学习和评测分析等后训练全链路；\n3.研究长程任务中的探索效率、稀疏奖励、信用分配、奖励投机、风险决策和异常恢复等问题；\n4.规划分布式 rollout、在线强化学习、模型推理和任务环境等训推基础设施；\n5.研究安全机制对训练吞吐、推理时延、有效轨迹比例和资源利用率的影响，优化能力—安全—效率之间的平衡。","requirements":"1.熟悉大语言模型、强化学习和智能体技术，对大模型后训练具有系统性理解；\n2.熟悉 SFT、RLHF/RLAIF、DPO、PPO、GRPO、在线强化学习等方法中的一种或多种；\n3.具有完整的大模型后训练、Agentic RL 或复杂智能体项目经验，能够覆盖任务、环境、训练和评测等环节；\n4.熟练使用 Python、PyTorch 等工具，了解分布式训练、模型推理或 rollout 系统；\n5.具备较强的问题定义、技术判断和独立推进能力，能够负责完整研究或工程项目。\n\n加分项\n有长程任务 Agent、Coding Agent、Computer-Use Agent 或多智能体系统经验；\n有分布式 rollout、推理加速、过程奖励、自动验证器或训练数据闭环经验；\n有智能体安全、模型红队、提示注入防御、工具安全或权限控制经验；\n在人工智能或安全领域有高水平论文、重要产品或高质量开源成果。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7678926056808876334","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型强化学习青年研究员/工程师（网安方向）","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7678926056808876334?mode=social","duty":"负责面向网络安全场景的大模型训练与能力建设，基于长程 Coding、多轮工具调用等能力，重点提升模型的漏洞挖掘、漏洞利用能力；\n面向网安与 Coding 任务开展大模型强化学习训练，研究可验证奖励、任务轨迹采样、长程信用分配、执行反馈和训练稳定性等关键技术，提升模型解决复杂任务的能力；\n建立覆盖代码生成与调试、工具调用可靠性、长程任务成功率及安全任务泛化能力的评测体系，推动模型能力在实际网络安全场景中的落地。","requirements":"计算机科学、人工智能、网络安全或相关专业硕士及以上学历，具备大模型训练、代码模型或智能体方向研究与工程经验；\n熟悉大模型预训练及后训练流程，掌握 SFT、DPO、强化学习、奖励模型等技术中的一种或多种，具备训练数据构建、实验设计和模型评测经验；\n具备长程 Coding、代码智能体或工具调用模型的训练经验，熟悉任务轨迹构建、执行反馈、奖励设计、上下文管理和推理能力优化；\n具备较强的科研创新能力和工程实践能力，能够将前沿方法转化为可验证、可落地的模型能力；具备网络安全基础知识、安全工具使用经验或相关项目经历者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7678900056162388251","sourceKey":"shlab_social","company":"上海AI实验室","title":"AI网络安全工程师/青年研究员","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7678900056162388251?mode=social","duty":"1.联动科研算法团队，围绕高价值安全问题完成标准化界定与方法沉淀，搭建配套的专项数据集、评测基准与测试框架，将安全领域的研究成果系统性转化为可被使用的网络安全能力。\n2.联动工程团队，主导企业级安全产品的顶层设计与工程化落地，为外部用户提规模化的工程支撑。\n3.基于项目需求与团队成员开展灵活协作、互为补位支撑，协同推进人工智能技术与网络安全场景的融合落地。\n","requirements":"1.对数据结构、操作系统、计算机网络等知识具有扎实基础，掌握 Python/Go/Java 中至少一门语言。\n2.至少具备一项传统网络安全产品的研发经验，包括但不限于漏洞扫描器、SAST/DAST/IAST、代码审计、恶意代码检测、Web/API 安全检测引擎、主机安全、态势感知、新一代防火墙、流量安全等。\n3.有将安全能力与大模型 / Agent 深度结合的产品落地成果，如模型微调（SFT/RLHF/DPO 等）、基于 LLM 的自动化漏洞挖掘、安全智能体、安全 Harness 建设等。\n4.熟悉 Transformer 架构及大模型预训练、继续预训练（CPT）、监督微调（SFT）的原理与实践，了解数据清洗、质量评估、数据配比等数据工程方法。\n\n加分项：在强网杯、网鼎杯等全国性攻防或红蓝队竞赛中有突出表现。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7678668641751992585","sourceKey":"shlab_social","company":"上海AI实验室","title":"网络安全青年研究员","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7678668641751992585?mode=social","duty":"我们致力于探索人工智能与网络安全交叉领域的前沿技术，打造面向下一代智能化攻防的网安基座模型与智能体系统。围绕大模型后训练、漏洞智能分析、自动化攻防智能体开展研究，推动 AI 驱动的网络安全能力革新。\n\n1. 开展网安基座模型后训练算法研究，重点提高模型的漏洞挖掘、利用和修复能力；\n2. 参与后训练数据合成管线的设计与搭建，包括漏洞数据挖掘和漏洞环境容器的构建。\n3. 开展大模型在网络攻防中的能力评测，分析其能力边界、安全风险与改进方向；\n","requirements":"1. 拥有研究生及以上学历，计算机、软件工程、网络安全等相关专业优先；\n2. 具备渗透测试、漏洞挖掘、逆向分析、模糊测试等项目经验者优先；\n3. 熟悉 CyberGym、ExploitGym、ARVO、Vulhub等漏洞数据集/数据库者优先；\n4. 对开发漏洞挖掘、利用、修复的智能体工作流有一定了解，有相关开源项目经验者优先；\n5. 具备一定的大模型/智能体系统经验，能灵活使用 Claude Code 或 Codex 等AI编程工具；\n6. 有 CTF 夺旗赛经历、漏洞发现与披露记录，或实际攻防经验者优先；\n7. 具有良好的沟通协作能力，能够与团队融洽合作，一起探索新技术，推进技术进步。\n\n我们提供：\n1. 前沿的技术视野： 置身于大模型技术发展的最前沿，与行业顶尖团队并肩作战。\n2. 有影响力的项目： 参与到具有挑战性并和影响力的项目中，发挥你的最大潜力。\n3. 完善的成长体系： 提供完善的培训体系和职业发展路径，助力你的个人成长。\n4. 有竞争力的薪酬： 提供具有市场竞争力的薪酬和福利待遇。\n\n我们期待与你一起：探索AI驱动网络安全的新范式；推动 AI 与网安交叉领域的技术突破。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7678666724207544602","sourceKey":"shlab_social","company":"上海AI实验室","title":"AI前沿风险青年研究员","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7678666724207544602?mode=social","duty":"随着AI能力快速发展，通用人工智能在生物、化学、能源、网络空间等高风险领域也带来了新的安全挑战。我们致力于探索AI的前沿风险（Frontier AI Risk），研究AI系统在复杂科学与工程领域中的潜在风险、能力边界与安全保障方法。\n岗位重点关注 AI 在生物、化学、医疗、金融、能源等高风险领域的能力评估、风险发现、安全测试与治理技术，探索如何构建面向未来智能系统的风险评测体系与安全保障机制。","requirements":"1. 拥有研究生及以上学历，生物信息学、环境学、金融、化学等相关专业优先；\n2. 具备一定的大模型/智能体评测经验，能灵活使用 Claude Code 或 Codex 等AI编程工具；\n3. 以下方向之一具备经验者优先：模型评测、红队测试、安全对齐、AI在生物/化学/材料等垂域的应用；\n4. 在生物、医疗、化学、金融等垂直领域具有专业背景或项目经验者优先；\n5. 对AI的安全挑战和跨学科问题具有兴趣，能够主动发现问题并推动研究落地；\n6. 具有良好的沟通协作能力，能够与团队融洽合作，一起探索新技术，推进技术进步。\n\n加分项：\n1. 在 Nature、Science、NeurIPS、ICML、ICLR、ACL 等期刊/会议发表过论文；\n2. 参与或维护 AI 安全、模型评测、智能体安全相关开源项目；\n3. 在生物、化学、医学、材料、能源、金融等领域有研究经历；\n\n我们提供：\n1. 前沿的技术视野： 置身于大模型安全治理的最前沿，与行业大牛面对面交流。\n2. 有影响力的项目： 参与到具有挑战性并和影响力的项目中，发挥你的最大潜力。\n3. 完善的成长体系： 提供完善的培训体系和职业发展路径，助力你的个人成长。\n4. 有竞争力的薪酬： 提供具有市场竞争力的薪酬和福利待遇。\n\n我们诚邀具有探索精神的优秀人才加入，共同研究下一代人工智能发展过程中的关键安全问题。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7678663376582986027","sourceKey":"shlab_social","company":"上海AI实验室","title":"基座模型算法工程师/青年研究员","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7678663376582986027?mode=social","duty":"我们致力于探索下一代大模型训练范式，面向基座模型后训练、智能体自我演化、高质量数据合成等前沿方向开展研究与工程实践。诚邀对大模型训练和智能体技术具有热情的人才加入，共同推动大模型能力边界探索。\n1. 开展大模型后训练阶段的算法研发，特别是针对智能体的自我演化；\n2. 开展大模型合成数据方法的优化研发，特别是针对后训练阶段的数据合成方法；\n3. 探索大模型自进化（Recursive Self-improvement）的全新技术路线。","requirements":"1. 拥有自然语言处理、机器学习、计算机视觉等相关专业背景，硕士及以上学历；\n2. 在 LLM SFT/RL/Agentic RL 方面拥有扎实的理论基础和实践经验者优先；\n3. 熟悉 Verl、Slime、vLLM 或 SGLang 等大模型框架，有多机多卡训练模型经验者优先；\n4. 对后训练全流程（数据、训练、评测）理解深刻，有相关项目经历者优先；\n5. 具有重量级开源项目或核心代码贡献经历者优先；\n6. 具有良好的沟通协作能力，工作积极主动，能够与团队一起探索新技术，推进技术进步。\n\n我们提供：\n1. 前沿的技术视野： 置身于大模型技术发展的最前沿，与行业顶尖团队并肩作战。\n2. 有影响力的项目： 参与到具有挑战性并和影响力的项目中，发挥你的最大潜力。\n3. 完善的成长体系： 提供完善的培训体系和职业发展路径，助力你的个人成长。\n4. 有竞争力的薪酬： 提供具有市场竞争力的薪酬和福利待遇。\n\n我们期待与你一起：探索下一代大模型范式，构建从算法创新到系统落地的完整研究闭环。\"","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7678626664427686153","sourceKey":"shlab_social","company":"上海AI实验室","title":"科学多模态大模型算法工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7678626664427686153?mode=social","duty":"负责科学领域（化学、生命科学、材料、地球科学、物理等）多模态大模型训练数据的全流程建设，提升模型在科学 benchmark 上的性能与科学知识、推理能力；\n负责科学领域高质量指令数据的大规模合成与筛选：基于专业科学数据库（PubChem、UniProt 等）与开源数据构造 QA，开展文本/VQA 数据合成、结构化数据改造、指令多样性升级与 CoT 升级；\n负责科学 benchmark 的收集、甄别与评测集成，基于 OpenCompass / VLMEvalKit 实现新数据集集成；\n负责数据有效性验证与合入：设计并执行单训、混训小规模实验，确定数据配比，完成数据交付与版本管理；\n与 AI4S 领域团队紧密协作，对接前沿科学任务场景与原始数据，跟进行业最新技术进展，探索 AI for Science 方向的新技术研究与落地。","requirements":"硕士及以上学历；\n有化学、生物、材料、地球科学等科学领域背景，或熟悉 PubChem、UniProt、Materials Project 等专业科学数据库与 RDKit 等工具链者优先；\n熟悉主流大模型/多模态大模型的训练、微调与评测流程，有大规模 SFT/RL 训练经验者优先；\n熟悉 deepspeed、xtuner、llamafactory、megatron、vllm、sglang、lmdeploy、opencompass、VLMEvalKit 等大模型训练、推理、评测框架可加分；\n有 Agent/Skill 开发、工具调用与自动化 pipeline 落地经验者加分；\n具备良好的沟通表达能力、跨团队协作意识、针对关键技术难度的攻坚能力。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7678625307444742463","sourceKey":"shlab_social","company":"上海AI实验室","title":"多模态大模型算法工程师（架构方向）","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7678625307444742463?mode=social","duty":"参与统一多模态大模型的训练与调优，优化从数据生产、数据配比到模型训练的全流程；\n研究统一多模态大模型领域高质量大规模数据合成、筛选、评估等；\n负责内部和开源算法库的相关工作，功能开发及维护；\n跟进行业最新技术进展，探索多模态方向的新技术研究与落地。","requirements":"硕士及以上学历，计算机或人工智能相关专业优先，有顶会论文可加分；\n熟悉主流大模型的部署、训练、架构实现，有大规模训练和部署经验者优先；\n熟悉数据抓取、大规模文档解析、多模态数据自动合成管线等经验者优先;\n熟悉deepspeed、llamafactory、megatron、vllm、sglang、lmdeploy、opencompass等大模型训练、推理、训练框架可加分；\n有知名学术工作、开源项目、国际竞赛成果可加分；\n具备良好的沟通表达能力、团队协作意识、针对关键技术难度的攻坚能力以及一定的抗压能力。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7678621698992949514","sourceKey":"shlab_social","company":"上海AI实验室","title":"云原生&算力集群SRE","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7678621698992949514?mode=social","duty":"1. 算力集群稳定性建设：负责大规模Kubernetes云原生集群、GPU算力集群的日常运维、故障排查、稳定性保障，主导集群核心故障的复盘、根因分析与优化落地，持续降低集群故障发生率，保障7*24小时业务稳定运行。\n2. 算力资源管理与调度优化：深入调研算力调度、资源隔离、负载均衡机制，优化集群资源分配策略，解决算力资源碎片化、抢占冲突、资源浪费等问题，提升GPU/CPU算力利用率，支撑海量训练、推理任务高效调度。\n3. 云原生运维体系自动化建设：基于云原生技术栈搭建自动化运维、监控告警、日志分析、链路追踪体系，实现集群资源、任务状态、服务指标的全维度可观测，推动运维流程标准化、自动化、智能化。\n4. 集群性能调优与成本优化：针对云原生集群、算力集群的网络、存储、调度、内核参数进行深度调优，解决集群延迟高、吞吐低、节点异常等问题；落地算力资源弹性扩缩容、闲置资源回收机制，持续降低基础设施运维成本。\n5. 技术迭代与架构升级：跟进云原生、算力基础设施前沿技术，参与集群架构迭代升级，落地容器化、服务网格、分布式算力调度等新技术方案，支撑业务规模化、高性能演进。\n6. 业务支撑与应急保障：对接算法、研发业务团队，提供算力集群技术支撑，处理突发线上故障，制定应急预案，保障大模型训练、推理核心业务平稳迭代。","requirements":"核心能力\n1. 本科及以上学历，计算机、软件工程、云计算、网络工程等相关专业，1-3年及以上云原生SRE、算力集群运维相关工作经验。\n2. 精通Kubernetes核心原理及组件（kube-apiserver、etcd、scheduler、controller-manager），熟练掌握容器、镜像、PV/PVC、资源配额、污点容忍等核心机制；熟悉Docker、Containerd容器运行时。\n3. 有GPU算力集群、AI训练/推理集群运维优化经验优先，熟悉算力调度框架、多卡通信、算力资源隔离、节点故障治理等相关技术。\n4. 熟练使用Prometheus、Grafana、ELK、Jaeger等可观测组件，能够独立搭建监控告警体系，精准定位线上集群、网络、资源各类故障。\n5. 熟练掌握Go/Python任意一种语言，能够独立开发运维脚本、自动化工具、调度插件，具备二次开发能力优先。\n6. 具备良好的线上故障排查能力、抗压能力和问题复盘能力，熟悉Linux内核、网络、存储原理，了解微服务、云原生架构设计思路。\n加分项\n1. 有大规模AI算力集群运维经验；\n2. K8s开源社区贡献经验、云原生认证（CKA/CKS）、算力调度系统二次开发经验者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7675701479667730731","sourceKey":"shlab_social","company":"上海AI实验室","title":"【高阶岗位】RL方向（高级）工程专家","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7675701479667730731?mode=social","duty":"参与实验室书生大模型后训练整体方案设计与合版工作，负责文本、多模态及智能体场景下强化学习技术架构的规划、研发与规模化落地，推动模型后训练能力持续演进。具体工作内容包括：\n1. 负责书生大模型后训练阶段强化学习整体技术方案的设计与落地，围绕文本、多模态、智能体等任务，推进强化学习训练流程、算法方案和工程系统的统一规划与持续优化；\n2. 负责基于多类型反馈的强化学习算法研发与迭代，覆盖复杂推理、指令遵循、代码、网页浏览、工具调用、多轮交互等任务，提升模型在真实应用场景中的综合能力；\n3. 负责强化学习训练数据、偏好数据、环境反馈数据及奖励模型体系的建设，推动奖励模型、过程评价模型和结果校验模型的研发与优化；\n4. 负责后训练相关方案的实验设计、效果评估和问题分析，建立完善的模型能力评测与迭代机制，推动算法方案在不同模型规模和任务上的泛化；\n5. 参与后训练方案的工程规模化和版本合并，协同算法、数据、工程及产品团队，推动强化学习技术在书生大模型中的稳定应用与落地；\n6. 关注大模型强化学习及智能体领域的前沿进展，结合实验室实际需求制定技术路线，并推动关键技术攻关。","requirements":"1. 博士及以上学历，计算机科学、人工智能、数学、统计、电子工程等相关专业优先；\n2. 在大模型后训练、强化学习、多模态学习或智能体方向具有深入研究或丰富工程实践经验，熟悉文本、多模态和智能体强化学习技术；\n3. 熟悉 PPO、GRPO、RLHF、RLAIF、过程奖励、奖励模型、环境反馈强化学习等相关方法，对大模型强化学习训练流程和技术演进具有系统理解和研发经理；\n4. 熟练使用 Python、PyTorch、Ray 等语言和代码库，具备大规模模型训练、强化学习训练系统或相关底层基础设施的研发与优化经验；\n5. 具备较强的技术判断力和系统性思考能力，能够识别关键问题、制定技术方案并推动复杂项目落地；\n6. 具备优秀的团队协作、沟通和项目推进能力，有顶会论文、知名竞赛获奖、顶级研究机构或大规模模型研发经验者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7675650537387952410","sourceKey":"shlab_social","company":"上海AI实验室","title":"【高阶岗位】长程推理青年/资深科学家","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7675650537387952410?mode=social","duty":"面向代码研发、科学研究等真实复杂任务，研究大模型智能体的长程推理与强化学习，并建设支撑规模化训练的 RL Infra 和环境 Infra\n1. 长程推理与智能体学习\n- 研究长程规划、工具使用、记忆管理、结果验证和失败恢复等关键算法\n- 研究面向长轨迹的强化学习方法，解决稀疏奖励、信用分配、探索效率和训练稳定性问题\n- 建设真实复杂任务的训练与评测方法，以实验结果持续推动模型能力提升\n2. RL Infra\n- 建设支持长轨迹、多轮交互、异步 Rollout 和分布式训练的强化学习系统\n- 优化采样、推理、奖励计算与训练之间的数据流和资源调度\n- 提升大规模智能体训练的吞吐、稳定性和资源利用率\n3. 环境 Infra\n- 建设面向代码、终端和科学计算等任务的可交互环境\n- 建设可靠的验证器，为训练和评测提供准确、可规模化的反馈信号\n- 推动环境与任务的自动生成、质量控制和规模化运行\n4. 科研与技术领导\n- 提出具有原创性和实际价值的研究课题，主导技术路线与规模化实验\n- 产出高水平论文、开源系统或具有显著能力增益的模型成果\n- 协同算法、系统、数据和产品团队，推动研究成果落地","requirements":"基本条件\n- 计算机科学、人工智能、数学、统计学或相关专业的博士学历且有3年以上相关研究经验\n- 在大语言模型、智能体、强化学习或机器学习系统方向有系统积累\n- 具备优秀的编程能力，熟练掌握Python、PyTorch等深度学习框架\n- 发表过高水平论文，或取得过具有同等影响力的模型、系统及开源成果\n专业能力\n候选人应在以下至少一个方向具备突出成果，并对其他方向有较强理解：\nA. 长程推理与智能体强化学习\n- 深入掌握强化学习、序列决策、规划搜索和信用分配等核心方法\n- 对工具使用、智能体记忆、过程验证和失败恢复具有系统研究\n- 具有大模型后训练或智能体强化学习的实际经验\n- 能够解决长轨迹训练中的奖励稀疏、策略投机和泛化问题\nB. RL Infra 与大规模学习系统\n- 深入理解大模型训练、推理及强化学习系统架构\n- 具有分布式训练、异步采样或大规模 Rollout 系统研发经验\n- 能够系统优化吞吐、延迟、显存、通信和资源利用率\n- 能够主导大型训练系统的架构设计与工程落地\nC. 环境 Infra 与可验证智能体\n- 深入理解智能体环境、工具协议、执行隔离和自动验证机制\n- 具有容器、虚拟机、沙箱或分布式任务平台建设经验\n- 能够设计真实、稳定、可复现、可验证的训练任务\n- 能够识别并治理奖励投机、测试泄漏和环境污染等问题\n素质要求\n- 对解决具有挑战性的AI问题充满热情，具备独立科研能力和创新思维\n- 优秀的沟通表达能力，能够清晰阐述技术方案并与跨职能团队高效协作\n- 良好的学术诚信意识与团队合作精神\n优先考虑\n- 在长程推理、智能体强化学习或机器学习系统方向取得过有影响力的成果\n- 主导过 Coding Agent、Research Agent 或其他长程智能体项目\n- 负责过大模型 RL Infra、Rollout 系统或环境平台建设\n- 具有大规模模型训练、并发环境运行或开源项目核心研发经验","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7675575188771129643","sourceKey":"shlab_social","company":"上海AI实验室","title":"【高阶岗位】仿真算法青年科学家","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7675575188771129643?mode=social","duty":"1. 主导具身智能仿真引擎的核心架构设计，保障引擎架构上的高性能、可分布式、可扩展。\n2. 开发可硬件加速的高性能高精度的可微物理仿真引擎，支持刚体、铰接物体、布料、软体、流体、粒子等物态的物理仿真。\n3. 开发可硬件加速的高保真图形渲染引擎，能够支持高性能光线追踪和全局光照算法。\n4. 机器人动力学和多种模态传感器模拟模块的开发，确保高保真度的物理交互仿真（如碰撞、动力学响应）及多模态数据（视觉、触觉等）的实时仿真。\n5. 解决大规模并行仿真中的性能瓶颈，设计分布式计算框架与资源调度策略，支持多智能体协作、复杂环境动态及跨平台部署需求。","requirements":"1. 计算机科学、计算机图形学或相关领域硕士以上学历，5年以上仿真引擎开发经验，熟悉Unity/Unreal/Isaac Sim等引擎内核，精通物理模拟、传感器建模及分布式系统设计。\n2. 具备3年以上技术团队管理经验，主导过仿真引擎项目开发，熟悉敏捷开发与DevOps流程，能高效协调算法与工程团队协作。\n3. 擅长解决高并发仿真中的实时性挑战，在物理引擎优化（如刚体/柔体动力学）、多智能体交互逻辑设计等领域有成功落地案例。\n加分项：\n1. 深入理解具身智能核心问题、熟悉强化学习、持续学习算法，具备机器人控制或认知科学交叉背景者优先。\n2. 熟悉具身智能在机器人、自动驾驶、智能制造等领域的应用场景，对数字孪生、虚实融合技术有实践经验，具备开源项目贡献或学术成果（如顶会论文）者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7675293896155187510","sourceKey":"shlab_social","company":"上海AI实验室","title":"【高阶岗位】AI技术战略青年领军科学家/资深科学家","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7675293896155187510?mode=social","duty":"承担人工智能重大专项在算力、数据、模型、Agent、具身、AI安全等核心方向上的技术调研、任务规划、项目技术管理等工作。\n1. 技术研判：日常跟踪人工智能领域的技术趋势和竞争态势，围绕人工智能重大专项核心方向开展深度调研，输出高质量研判观点及相关材料；\n2. 任务规划：参与人工智能重大专项实施方案、阶段实施计划、预期标志性成果等规划工作的技术研讨及材料撰写；参与人工智能重大专项年度指南研讨及编制；\n3. 项目技术管理：参与人工智能重大专项的项目全过程管理，参与项目技术审查和任务磋商，跟踪项目技术进展，识别重大技术问题、研判重大技术风险，提出优化/调整技术建议，参与专项相关技术进展材料编制；\n4. 承办领导交办的其他事项。","requirements":"- 具有计算机科学、人工智能等相关领域博士学位；\n- 具有高级专业技术职称，或具备同等水平的学术影响力与行业认可度；\n- 具备人工智能领域丰富的科研与工程经验，对人工智能全栈技术具备系统性理解；\n- 具备出色的战略思维、技术洞察、系统架构能力；\n- 主持过人工智能领域国家级或省部级科研项目。具有国家科技计划总体规划和论证履历者优先，具有国家科技计划项目负责人履历者优先，熟悉国家科技计划管理体系者优先；\n- 具备良好的跨领域沟通协调及高质量文稿撰写能力，能够适应阶段性高强度工作。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7674889611902683418","sourceKey":"shlab_social","company":"上海AI实验室","title":"AI应用评测工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7674889611902683418?mode=social","duty":"1. 评测框架与平台开发：构建以模型、Harness为评测对象，以AI4S多研究领域为核心内容的的评测能力，实现对 ” 任务 X 模型 X Harness “ 多维度组合的评测，建设使用门槛低、效率高、自动化、可信赖的评测框架与平台\n2. 评测方法建设：能够快速跑通、复现开源Benchmark；协同领域科学家、产品经理共同构建符合AI4S业务属性的评测方法，包含自建Benchmark，探索新的评估范式以解决静态评估及榜单的弊端\n3. 评测结果分析：对评测结果进行深入分析，形成评测报告，为模型、Agent研发迭代提供参考。Agent评测，对工具调用、工具轨迹、权限、状态变化、消耗资源、Agent产物等全链路评测结果进行真实性反馈，形成Agent迭代优化的依据\n4. AI研发体系建设：协同数据研发、模型研发、Agent研发、模型服务等多个研发团队，建设起 “ 数据语料-AI研发-AI评测 ”的闭环研发体系，不断提升模型与Agent表现","requirements":"1. 计算机相关专业，本科及以上学历，3年以上相关工作经验；具备Python/Java/Go至少一种语言的开发能力，熟悉JSON、YAML等数据格式，熟悉Linux开发环境，能够使用Shell脚本进行自动化任务。\n2. 熟悉Agent的评估指标，不仅限于文本生成质量，还包括规划能力、工具调用成功率等维度；有LLM 应用、AI Agent的AI原生产品研发经验加分；\n3. 紧跟业界前沿趋势，高效率的论文、技术报告的阅读能力；动手能力强，能够快速复现开源项目\n4. 积极主动，对AI有激情，具备较强的团队协作能力、组织协调能力、复杂问题解决能力。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7674889148247476490","sourceKey":"shlab_social","company":"上海AI实验室","title":"AI应用研发工程师 - 技术平台中心","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7674889148247476490?mode=social","duty":"1. 负责 AI 模型网关及计费平台的设计、开发与维护。\n2. 建设多模型接入、统一 API、模型路由、限流、熔断、降级及流式响应等能力。\n3. 负责 Token 用量采集、配额管理、成本核算、计费及账单等系统建设。\n4. 优化网关的高并发、高可用、可观测性及调用成本。\n5. 根据需要参与管理后台等前端开发。","requirements":"1. 计算机相关专业，本科及以上学历，3年以上相关工作经验；具备良好的系统设计及线上问题排查能力。\n2. 熟练掌握 Go、Python、Java 或 Node.js 中至少一种语言，熟悉 HTTP/SSE、数据库、缓存、消息队列及分布式系统。\n3. 理解 API 网关、限流、鉴权、负载均衡和容灾等机制；对大模型 API、Token 计量、模型定价和调用成本有一定理解；了解 SaaS 配额、计费、账单或支付相关系统。\n加分项\n熟悉多租户架构、Kubernetes、可观测性或高并发系统；具备 React、Vue 等前端开发经验。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7673755348960053550","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型安全数据工程师/青年研究员","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7673755348960053550?mode=social","duty":"我们致力于探索人工智能与网络安全交叉领域的前沿技术，打造面向下一代智能化攻防的网安基座模型与智能体系统。围绕大模型后训练、漏洞智能分析、自动化攻防智能体开展研究，推动 AI 驱动的网络安全能力革新。\n\n1. 开展网安基座模型后训练算法研究，重点提高模型的漏洞挖掘、利用和修复能力；\n2. 参与后训练数据合成管线的设计与搭建，包括漏洞数据挖掘和漏洞环境容器的构建。\n3. 参与学术讨论和技术交流，撰写研究报告、技术文档或论文，鼓励在国际会议 IEEE S&P、USENIX Security、ACM CCS 上发表研究成果。\n","requirements":"1. 研究生及以上学历，计算机、软件工程、网络安全等相关专业优先；\n2. 熟悉常见网络漏洞类型（如内存越界、Web漏洞）的原理和利用方法者优先；\n3. 熟悉 CyberGym、ExploitGym、ARVO、Vulhub等漏洞数据集/数据库者优先；\n4. 对开发漏洞挖掘、利用、修复的智能体工作流有一定了解，有相关项目经验者优先；\n5. 具备一定的大模型/智能体系统经验，能灵活使用 Claude Code 或 Codex 等AI编程工具；\n6. 具有良好的沟通协作能力，能够与团队融洽合作，一起探索新技术，推进技术进步。\n\n\n我们期待与你一起：探索AI驱动网络安全的新范式；推动 AI 与网安交叉领域的技术突破。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7673686983583385865","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型Agent审计与自进化算法工程师","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7673686983583385865?mode=social","duty":"1.开展大模型Agent评测、审计与自进化研究，探索Agent能力评估与持续优化关键技术。\n2.研发Agent评测与审计系统，负责执行轨迹采集、自动化评测和实验平台建设。\n3.设计过程级与结果级评测方法，分析Agent在规划、工具使用、推理、效率和鲁棒性等方面的表现。\n4.探索基于轨迹、环境反馈和交互数据的自进化方法，推动Agent能力持续提升。\n5.跟踪Agent前沿技术，参与论文、开源项目和技术成果产出。","requirements":"1.计算机科学、人工智能、数学、自动化或相关专业硕士及以上学历；特别优秀者可适当放宽。 \n2.熟悉Transformer、大语言模型和LLM Agent的基本原理，对Agent推理、工具调用、任务规划或模型训练有较深入的理解。 \n3.具备扎实的机器学习基础，熟练使用Python、PyTorch和Linux，能够独立完成模型训练、Agent实验、数据分析与问题诊断。 \n4.具备良好的科研能力，能够进行文献调研、实验设计、Benchmark构建、结果分析和技术写作，对实验结论保持严谨审慎。 \n5.具有较强的科研探索能力，对LLM Agent、Agent Evaluation 或 Recursive Self-Improving Agent等方向保持持续关注，能够独立提出问题并推动研究落地等方向有浓厚兴趣，具备良好的沟通协作能力和自主推进能力。 \n\n加分项 \n1. 具有LLM Agent、大模型训练、强化学习、Agent Evaluation、自反思或自进化模型相关研究经验。 \n2.熟悉主流Agent框架， 对轨迹分析及数据合成有经验。 \n3.具有分布式训练、大模型推理系统、Agent Infrastructure或大规模评测系统的实践经验。 \n4.参与过有影响力的开源项目,或者在相关领域发表过高质量论文，具备良好的英文论文阅读和写作能力。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7673413416513718578","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型可解释性青年科学家/青年研究员","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7673413416513718578?mode=social","duty":"1. 开展大模型可解释性、表示学习和模型机制分析相关研究，探索提升模型透明性与可信性的技术方法。\n2. 负责模型训练、实验系统搭建与算法优化，包括数据处理、模型微调和训练框架实现。\n3. 设计模型评估方法，分析模型表示、解释能力和鲁棒性表现。\n4. 跟踪前沿研究进展，复现和改进相关方法，探索创新研究方向。\n5. 参与论文、技术报告及开源项目建设，推动研究成果落地。","requirements":"1. 计算机科学、人工智能、数学、自动化或相关专业硕士及以上学历；特别优秀者可适当放宽。\n2. 熟悉 Transformer 和大语言模型的基本原理，对模型训练、内部表示或可解释性研究有较深入的理解。\n3. 具备扎实的机器学习基础，熟练使用 Python、PyTorch 和 Linux，能够独立完成模型训练、实验分析与问题诊断。\n4. 具备良好的科研能力，能够进行文献调研、实验设计、结果分析和技术写作，对实验结论保持严谨审慎。\n5. 对大模型可解释性研究有强烈兴趣，具备良好的沟通能力、协作意识和自主推进能力。\n加分项\n1. 具有大模型训练、强化学习、RLHF、表示学习、模型评估或可解释性研究经验。\n2. 熟悉模型内部激活提取、activation intervention、probing、representation analysis 等方法。\n3. 具有分布式训练或大模型推理系统的实践经验。\n4. 在相关领域发表过高质量论文，或参与过有影响力的开源项目。\n5. 具备良好的英文论文阅读和写作能力。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7673412432672688394","sourceKey":"shlab_social","company":"上海AI实验室","title":"具身多智能体青年研究员","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7673412432672688394?mode=social","duty":"工作概览：面向物理智能场景，负责多智能体协作与分布式系统层面的核心算法与体系设计。工作围绕多个具身智能体在真实物理环境中的任务分解、通信协调与协同优化展开，主导从问题定义、方案设计到真机或仿真验证的完整闭环，把探索性想法沉淀为可落地的能力。\n\n1. 主导物理智能场景下多智能体协作、分布式系统方向的算法研究与体系设计；\n2. 独立完成从问题定义、方案设计到实验验证的完整链路；\n3. 将研究思路转化为可落地的核心能力；\n4. 跟踪具身智能与多智能体前沿，产出高质量研究或工程成果。","requirements":"1. 计算机、人工智能、机器人等相关专业博士学历；\n2. 在分布式系统、多智能体协作等方向至少一项有深度积累，对具身、物理智能场景有接触者优先；\n3. 有顶会论文产出（NeurIPS / ICML / ICLR / CoRL / RSS 等）或可对标的工程成果；\n4. 具备从问题定义走到方案落地、独立推进的能力。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7673411792856549673","sourceKey":"shlab_social","company":"上海AI实验室","title":"【高阶岗位】评测技术架构师/全栈工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7673411792856549673?mode=social","duty":"1. 统筹梳理实验室现有评测平台、工具、算法、数据集和指标体系，识别重复建设与能力缺口，推动分散资源整合、复用和统一治理。\n2. 负责AI评测平台整体架构规划与持续演进，面向大模型、Agent及AI应用，明确平台分层、系统边界、技术标准和演进路径。\n3. 推动评测能力标准化和工程化，建设覆盖任务编排、数据管理、自动与人工评测、结果分析等环节的可扩展平台能力。\n4. 建设涵盖能力、效果、可靠性、鲁棒性、安全性、性能和成本等维度的综合评测体系，并推动其融入模型研发、上线验收和持续迭代流程。\n5. 牵头核心技术选型与方案评审，协同产品、算法、数据、研发和测试团队，解决关键技术问题，推动平台能力落地。","requirements":"1. 本科及以上学历，计算机科学、软件工程、人工智能、信息安全等相关专业；5年及以上架构设计经验，有大型AI产品从0到1搭建经验者优先。\n2. 精通微服务、分布式架构、云原生技术体系，熟练掌握前后端核心技术栈、数据库与中间件技术，具备扎实的架构设计、性能调优、高可用架构搭建能力。\n3. 深入理解大语言模型、Agent智能体、及模型训练推理流程，熟悉AI评测核心场景与技术痛点，具备AI类平台架构设计实战经验。熟悉AI评测方法与平台能力，包括数据集、指标体系、自动评测、人工评测、裁判模型、回归测试和在线评估等。\n4. 具备极强的系统化架构思维，能够结合业务战略、技术趋势制定平台架构演进路线，擅长平衡技术创新、研发效率与系统稳定性，具备丰富的技术攻坚与风险预判能力。\n5. 优秀的跨团队统筹协作能力，能够统筹研发、算法、产品、测试等多团队资源，推动复杂架构方案落地，具备良好的技术沉淀与团队赋能能力。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7673411774406871332","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型评测青年研究员","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7673411774406871332?mode=social","duty":"1. 负责生物、化学、材料等专业学科方向的大模型评测研究，结合学科知识设计评测框架、能力维度与评价标准。\n2. 建设和维护高质量学科评测数据集，负责题目设计、数据审核、答案标注及质量控制，确保评测内容科学、准确且可复现。\n3. 分析大模型在专业知识理解、科学推理、实验设计、物质性质分析及复杂问题求解等任务中的表现，识别模型能力边界与典型问题。\n4. 参与评测方法与技术研究，探索自动评测、专家评测及大模型辅助评测等方式，提升学科评测的准确性和效率。\n5. 跟踪相关学科及大模型评测领域的前沿进展，协同AI算法、产品和工程团队，推动研究成果在评测产品和实际项目中落地。","requirements":"1. 博士及以上学历，生物学、化学、生物化学、药学、材料科学及相关专业优先；具备扎实的专业知识和科研训练。\n2. 熟悉生物、化学、材料或物质科学中的一个或多个方向，能够准确判断专业内容、实验逻辑和科学结论。\n3. 对人工智能、大语言模型及AI评测具有浓厚兴趣，愿意持续学习大模型基本原理、评测方法和相关工具；具有相关项目经验者优先。\n4. 具备较强的资料检索、数据分析和研究能力，能够完成评测体系设计、数据集建设、结果分析及研究报告撰写；掌握Python或数据处理工具者优先。\n5. 具备良好的中英文读写、沟通协作和问题分析能力，工作严谨细致，有责任心，能够与学科专家、算法及产品团队高效协作。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7673391606859155721","sourceKey":"shlab_social","company":"上海AI实验室","title":"开发者大赛运营岗","city":"上海","category":"业务通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7673391606859155721?mode=social","duty":"1. 工作方案收口：统筹开发者大赛、创新赛事等方案制定与版本收口，明确赛事定位、赛道设置、赛程赛制、评审机制与成果转化路径；确保方案可直接上会决策、可向下拆解执行。\n2. 审议材料提报：撰写并提交学术委员会（学委会）所需材料，包括工作方案、预算与合规说明；跟踪审议进展与决议落实，形成提报—反馈—修订—归档闭环。\n3. 执行收口与合规管理：对赞助引入、会务招采、合同签署、流程合规统一收口；统筹大赛组织与成果宣发所需资金的提报申请，平衡内外部资金使用的合规性；留存决策与审批痕迹，确保全链路可追溯、可审计。\n4. 生态与合作运营：负责生态伙伴及大赛支持方（赞助方、评审专家、技术合作方、会务供应商）的联络与关系维护；作为技术团队与管理部门的沟通接口，参与对外交流与技术走访，独立完成纪要、意向梳理与跟进；建立并动态更新合作资源库。\n5. 调研与材料撰写：围绕 AI 技术动态、行业应用趋势、同类赛事实践开展专题调研；承担汇报、宣发及专报素材的撰写与统稿，对技术表述的准确性负责。","requirements":"基本门槛:\n1、本科及以上学历，理工科专业优先（计算机、人工智能、电子信息、自动化、数学、物理等）\n2、3 年以上生态合作、项目运营、赛事或大型活动管理经验\n3、熟悉赛事组织、招采合规、品牌与生态运营基本流程\n4、对 AI 产业格局、开源生态与开发者社群有基本认知\n5、认同科研机构长期价值导向，不以短期声量为目标\n核心能力:\n1、材料撰写：将零散信息整合为结构清晰、可直接上会的正式文件\n2、技术理解：了解大模型与机器学习基本范式，能读懂技术方案与产品介绍\n3、沟通调研：与专家、企业技术负责人有质量地对话，并沉淀为可用结论\n4、合规闭环：熟悉招采、合同、资金管理流程，习惯留存决策痕迹\n5、资源整合：基于资源库快速完成伙伴匹配、专家邀约与方案组合\n加分项：\n1、有科研院所、高校院系背景\n2、有 AI 企业、开源社区或开发者生态从业经历\n3、独立承担过专题调研或行业研究报告撰写\n4、有跨部门统筹\"一肩挑\"项目经验\n5、兼具技术背景与运营经验者优先","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7673033381178198278","sourceKey":"shlab_social","company":"上海AI实验室","title":"科研助理（项目管理方向）","city":"上海","category":"业务通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7673033381178198278?mode=social","duty":"1. 协助科研团队撰写、整理项目规划、申报、中期检查、结题验收及汇报展示等相关材料；\n2. 协助完成技术成果转化，包括项目相关文件、数据、报告的系统性归档与管理，成果转化对接及产业化推进，跟踪转化进展，支撑实验室PR宣发的项目材料；\n3. 协助项目经理及科研人员进行科研项目书、结题材料的撰写支持；负责人员信息收集、文案初审及系统申报上传等事务；\n4. 协助组织科研会议，做好会议纪要与决议跟踪；作为联络支持，与机构内部其他部门及外部合作单位进行日常事务性沟通，并组织和参与有关活动。","requirements":"1. 全日制硕士研究生及以上学历；\n2. 具备相关科研项目管理经验，了解AI行业相关背景、技术体系及产品体系的优先;\n3. 2年以上科研或科研管理工作经历；具有良好的组织协调能力、团队合作能力、出色的沟通能力与主人翁意识。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7672669433710332166","sourceKey":"shlab_social","company":"上海AI实验室","title":"具身模型部署算法工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7672669433710332166?mode=social","duty":"1. 负责多模态大模型、具身大模型（如VLA视觉-语言-动作模型、世界模型等）在国产算力芯片及边缘计算板卡上的迁移、适配与部署；\n2. 完成模型、算子、推理框架与国产板卡软件栈之间的兼容性适配，解决模型转换、编译构建、算子不兼容、运行时异常及精度偏差等问题；\n3. 针对机器人的高频控制闭环需求（如数百Hz的动作输出频率），开展端侧推理性能极致调优。围绕端到端时延、显存占用、I/O吞吐量进行分析，解决具身场景下单Batch、低延迟推理的性能瓶颈；\n4. 负责推理服务的工程化封装，并与机器人底层控制系统或中间件（如 ROS/ROS2, DDS）深度集成。实现多模态传感器数据（如多路视觉、本体状态、高精度空间定位数据）的高效接入与对齐。","requirements":"1. 硕士及以上学历，计算机、软件工程、人工智能、电子信息、自动化等相关专业，在机器人或自动驾驶等行业具有1～2年以上模型部署或AI加速相关工作经验，特别优秀者可放宽学历与年限要求；\n2. 熟悉Linux及实时操作系统（RTOS）开发环境，具备扎实的 Python 和现代 C/C++ 编程能力。能够独立完成模型适配、功能调试和底层性能问题定位；\n3. 熟练使用PyTorch，理解深度学习模型的计算过程、计算图、张量处理机制及常见算子实现方式；\n4. 具备CUDA模型迁移或异构计算平台适配经验，能够将基于CUDA生态开发的模型或算子迁移至国产算力平台；\n5. 熟悉ONNX模型转换及部署流程，能够处理模型导出、算子转换、动态图与静态图适配以及模型精度对齐等问题；\n6. 熟悉TensorRT-LLM等大模型推理框架及其优化机制，了解模型并行、批处理、KV Cache、显存管理和推理加速等关键技术。\n\n加分项：\n1. 具有华为昇腾、寒武纪等国产算力平台的实际模型适配或部署经验；\n2. 具有多模态大模型或大语言模型的量化、裁剪、蒸馏和推理加速经验；\n3. 熟悉国产算力平台的编译器、运行时、算子库及相关SDK，具备底层问题定位经验；\n4. 具有边缘计算板卡上的模型压缩、资源受限部署或低时延推理优化经验。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7670915938094500146","sourceKey":"shlab_social","company":"上海AI实验室","title":"Coding方向青年科学家","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7670915938094500146?mode=social","duty":"面向真实软件研发任务，研究 Coding Agent 的核心方法，提升模型在仓库级理解、长程任务执行、工具使用、错误修复和持续学习等方面的能力，推动算法、数据、环境、训练和评测形成完整闭环\n1. Coding 模型与智能体算法\n- 研究代码理解、生成、推理和软件工程任务中的关键算法\n- 研究仓库级长上下文建模、任务规划、工具使用和多智能体协作\n- 研究基于 SFT 与强化学习的后训练方法，提升模型的推理和执行能力\n2. 数据与评测体系\n- 建设高质量代码数据的生产、清洗、配比和质量控制体系\n- 研究合成数据、执行反馈数据及长程 Agent 轨迹的构造方法\n- 建设覆盖代码生成、仓库级开发和真实软件工程任务的评测体系\n3. 训练与 Agent 基础设施\n- 建设支持 Coding Agent 训练、Rollout 和评测的环境 Infra\n- 建设支持长轨迹、多轮交互和可验证奖励的 RL Infra\n- 推动模型在真实研发场景中的稳定、高效部署与应用\n4. 科研与技术领导\n- 提出具有原创性和实际价值的研究课题，主导技术路线和规模化实验\n- 产出高水平论文、模型、Benchmark、开源系统或技术报告\n- 指导团队开展技术攻关，建设持续演进的 Coding Intelligence 能力","requirements":"- 计算机科学、人工智能、数学、统计学或相关专业的博士学历且有3年以上相关研究经验\n- 在大语言模型、智能体、强化学习或机器学习系统方向有系统积累，对Coding Intelligence方向有浓厚兴趣和深入理解\n- 发表过高水平论文，或取得过具有同等影响力的模型、系统及开源成果\n- 具备优秀的编程能力，熟练掌握Python、PyTorch等深度学习框架\n专业能力\n候选人应在以下至少一个方向具备突出成果，并对其他方向有较强理解：\nA. Coding 模型与 Agent 算法\n- 深入理解代码大模型的预训练、后训练及推理方法\n- 熟悉规划、搜索、工具调用、执行反馈和错误自我修复机制\n- 具有 Coding Agent 或长程智能体的研究及实践经验\nB. Coding 数据与强化学习\n- 熟悉代码数据合成、清洗、去重、配比和质量评估方法\n- 熟悉 SFT、PPO、GRPO、奖励建模或可验证强化学习\n- 能够解决长轨迹训练中的信用分配、奖励投机和泛化问题\nC. 训练、环境与评测 Infra\n- 深入理解大模型训练、推理、Rollout 和评测系统\n- 具有分布式训练、高性能推理或大规模 Agent 执行经验\n- 熟悉容器、沙箱、代码执行环境和自动化验证机制\n优先考虑\n- 在代码生成、程序分析、软件工程智能化或 Coding Agent 方向取得过有影响力的成果\n- 主导过代码大模型训练、Coding Agent 或仓库级开发智能体项目\n- 负责过代码数据飞轮、强化学习系统、执行环境或评测平台建设\n- 参与过具有影响力的大模型、开发工具或开源项目核心研发","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7670099267914500371","sourceKey":"shlab_social","company":"上海AI实验室","title":"重大科研项目管理高级主管 - 项目与资源管理中心","city":"上海","category":"业务通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7670099267914500371?mode=social","duty":"1. 重大项目申报策划与争取\n牵头组织发改委建设类项目等的申报策划，开展政策研判与申报指南解读；统筹申报材料编制、内部论证与报送工作，确保申报方案科学可行、竞争优势突出，提升项目获批成功率。负责实验室重大任务的边界梳理及战略分解，支撑国家科技重大专项战略研究及规划布局。\n2. 建设类项目全生命周期管理\n具体承担发改委建设类专项的全过程管理，覆盖立项申报、年度/节点计划制定、过程检查、经费执行监控、结题验收及成果归档；建立项目里程碑管理机制，实施“里程碑”考核和全生命周期跟踪管理，跟踪关键节点进展，及时发现并协调解决实施中的堵点难点，保障项目按期高质量完成。\n3. 主管部门对接与政策跟踪\n负责与国家发改委、科技部等上级主管部门及相关机构的日常对接，建立常态化沟通和信息报送渠道；密切跟踪政策动态、申报指南发布及资金下达情况。负责科研总体工作、重大科研项目等相关专报编制及上报。\n4. 跨部门协同与资源协调\n协助推进跨部门、跨单位协作攻关，做好任务分解、进度协调与资源配置的具体衔接；协同项目经费、人力、设备等资源的合理调配，协调项目团队与财务、审计、采购等部门的联动。\n5. 项目信息管理与风险管控\n负责所管项目的信息收集、动态台账维护与全过程档案管理；建立项目重大事项报告机制，对进度滞后、经费异常、风险事件等及时预警并协助做好应急处置，保障项目运行平稳有序。\n6. 制度建设与体系完善\n协助开展纵向科研项目管理制度的起草、修订与宣贯工作，推动项目管理规范化、标准化，持续完善项目管理体系与内控机制。负责制定并优化重大项目管理制度程序和项目分级管理方案。\n7. 综合事务与专项推进\n承担部门重点专项工作的具体推进，包括保密管理、科研管理信息化建设、会议组织、调研接待、报告撰写等综合事务；完成部门交办的其他工作。","requirements":"1. 基本条件\n- 具有良好的思想政治素质，品行端正，责任心强，严守科研诚信与保密要求；\n- 本科及以上学历，理工科相关专业优先；\n2. 专业经验\n- 具有5年以上科研项目管理经验，熟悉国家科技政策、科技计划管理相关规章制度；\n- 具有国家发改委建设类项目申报组织经验优先；\n- 具有国家重大科技基础设施、大科学装置项目管理经验者优先；\n- 具有军工、航天类重大科研项目全过程管理经验者优先；\n- 熟悉“两重”建设项目全流程跟踪管理者优先。\n3. 专业技能\n- 熟悉国家重大科技基础设施管理办法及相关政策法规；\n- 具备较强的项目策划、组织协调与风险管控能力；\n- 具备优良的科学素养、信息数据分析和研究能力；\n- 具备较强的文字表达能力和专报撰写能力。\n4. 能力素质\n- 具备出色的沟通协调能力与跨部门协作能力；\n- 具备较强的统筹规划能力和执行推动能力，能够承担多项目并行管理；\n- 具备强烈的责任感、较强的抗压能力及执行力。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7670094181621418246","sourceKey":"shlab_social","company":"上海AI实验室","title":"智能体框架研发工程师/青年研究员","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7670094181621418246?mode=social","duty":"1、智能体核心研究： 研究 Agent 推理、规划、自我修正、记忆及工具使用机制，探索多智能体协作、长期学习与自主进化等前沿方向。\n2、Harness 系统建设： 设计并实现智能体 Harness 核心架构，包括任务编排、工具调用、状态管理、上下文管理及环境交互等能力。\n3、研究与工程转化： 跟踪、复现并改进前沿研究成果，推动研究原型向稳定系统转化，将相关能力沉淀为可复用的技能、策略和工程组件。\n4、数据与评测闭环： 建设智能体执行环境、训练数据闭环及评测平台，持续分析系统表现，提升智能体的可靠性、泛化能力和任务完成质量。\n5、科学智能探索： 结合人工智能、认知科学及具体科研场景，参与 AI for Science 智能发现系统的研究、开发与应用落地。","requirements":"1、教育背景： 硕士及以上学历，博士优先；人工智能、计算机、数学、认知科学或相关专业。\n2、研究能力： 具备独立研究和实验能力，能够快速阅读、复现并改进前沿工作；有高水平论文或相关研究成果者优先。\n3、技术基础： 熟悉大语言模型、AI Agent、强化学习等相关技术，理解推理、规划、记忆、工具使用或多智能体系统中的至少一个方向。\n4、工程能力： 具备扎实的软件工程功底，熟悉 Python，并掌握 TypeScript、Go 等语言中的一种；具备复杂任务流或系统架构设计能力。\n5、项目经验： 具有 AI Agent、LLM Infra、Agent Framework 或相关开源项目经验者优先；能够将研究想法转化为可靠系统，并具备良好的协作和问题解决能力。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7668253134548453683","sourceKey":"shlab_social","company":"上海AI实验室","title":"平台架构师（AI安全平台方向）-科研产品平台部","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7668253134548453683?mode=social","duty":"1. 负责AI安全平台整体架构规划与从零到一搭建：深度联动安全团队，基于Agent、大模型训练、安全算法等核心AI安全能力，统筹设计AI安全平台整体技术架构、分层体系与技术规范，支撑平台长期迭代。\n2. 负责AI能力工程化架构设计与落地：针对模型调度、Agent任务编排、安全算法服务化、AI风险计算等核心场景，设计高可用、低延迟、可扩展的工程架构，解决AI能力与业务平台融合的技术难点，实现安全算法能力的标准化、规模化落地。\n3. 制定平台技术规范与演进路线：统一前后端研发规范、接口标准、数据规范、部署规范，梳理平台技术债务，制定长期技术演进规划，主导核心技术选型、架构升级与技术攻坚，保障平台架构的前瞻性与可扩展性。\n4. 赋能团队研发与跨团队协同：指导核心模块研发，评审技术方案，规避架构风险；深度对接产品、安全算法、研发、测试团队，对齐业务目标与技术目标，支撑产品方案落地、行业场景迭代与生态能力建设。","requirements":"1. 本科及以上学历，计算机科学、软件工程、人工智能、信息安全等相关专业；5年及以上架构设计经验，深耕B端平台、安全平台或AI平台架构建设，有大型AI安全产品从0到1搭建经验者优先。\n2. 精通微服务、分布式架构、云原生技术体系，熟练掌握前后端核心技术栈、数据库与中间件技术，具备扎实的架构设计、性能调优、高可用架构搭建能力。\n3. 深入理解大语言模型、Agent智能体、模型训练与推理、AI算法工程化落地逻辑，熟悉AI安全核心场景与技术痛点，具备AI+安全类平台架构设计实战经验。\n4. 具备极强的系统化架构思维，能够结合业务战略、技术趋势制定平台架构演进路线，擅长平衡技术创新、研发效率与系统稳定性，具备丰富的技术攻坚与风险预判能力。\n5. 具备高度的安全合规意识，熟悉AI数据安全、业务安全、系统安全规范，可从架构层面筑牢平台安全壁垒，规避技术与业务安全风险。\n6. 优秀的跨团队统筹协作能力，能够统筹研发、算法、产品、测试等多团队资源，推动复杂架构方案落地，具备良好的技术沉淀与团队赋能能力。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7668145963677288742","sourceKey":"shlab_social","company":"上海AI实验室","title":"开发者社区运营（AI智能体方向）","city":"上海","category":"业务通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7668145963677288742?mode=social","duty":"1. 负责智能体方向相关项目的日常运营，包括内容策划、用户运营、社区维护、活动执行等工作；\n2. 围绕大模型、AI Agent、工具调用、自动化任务等方向，完成项目介绍、技术解读、案例文章、活动文案等内容输出；\n3. 维护开发者社区、用户社群、技术文档、官网/公众号等运营阵地，提升用户活跃度和项目影响力；\n4. 支持线上分享、技术直播、Workshop、开发者活动等运营活动的策划、执行与复盘。","requirements":"1. 本科及以上学历，1-3 年内容运营、产品运营、社区运营、开发者运营或科技行业运营经验；\n2. 对大模型、AI Agent、AIGC、开发者工具等方向有兴趣，具备一定技术理解能力；\n3. 文字表达能力强，能将技术内容转化为清晰、易懂、有传播性的内容；\n4. 熟悉公众号、知乎、B站、技术社区、用户社群、GitHub 等平台运营方式者优先。\n\n加分项：\n1. 有 AI、大模型、智能体、开发者工具、开源项目相关运营经验；\n2. 有技术文章、产品文档、开发者教程、案例内容写作经验；\n3. 能阅读英文技术资料或论文，对 AI 前沿技术保持关注","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7667771573831928083","sourceKey":"shlab_social","company":"上海AI实验室","title":"科技成果转化合规风控高级主管 - 项目经理人与成果转化中心","city":"上海","category":"业务通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7667771573831928083?mode=social","duty":"（一）制度与风控体系建设\n- 跟踪国家及地方关于科技成果转化、国有资产管理、知识产权保护及人工智能领域的最新政策法规，研究起草并完善单位内部科技成果转化合规管理制度文件。\n- 协助建立并完善实验室投资管理体系与内部风险控制体系，拟定相关管理制度，构建全链条贯通的合规框架。\n- 协助建立并完善实验室与合作基金、基金会等机构合作的相关制度框架。\n（二）项目合规审核与尽职调查\n- 负责科技成果处置方案、转化项目立项及对外投资方案的合规性审核，确保流程符合国有资产评估备案、产权交易等监管要求。\n- 组织或参与转化项目前期的法律与财务尽职调查，重点评估合作方资质、知识产权权属（含训练数据版权风险）、技术出口管制适用性及潜在法律纠纷，独立撰写尽职调查报告。\n- 审核各类成果转化合同（技术许可、合作开发、作价投资），识别并修改涉及IP归属、数据使用权、保密义务、收益分配等关键风险条款。\n（三）投后管理与合规监督\n- 负责已投项目（或持股AI企业）的持续跟踪管理，定期排查业务运营与数据安全风险，提出行之有效的风控措施。\n- 协助管理单位派出的董事、监事，督促其尽职履责，保障单位在投后企业的合法权益。\n（四）政策研究与能力建设\n- 开展技术转移与合规专项调研，对标国际国内顶尖高校及国家级实验室，优化单位内部工作流程。\n- 定期输出AI领域政策解读与风险研判报告，为实验室战略决策和项目立项提供合规指引。\n- 组织开展科研合同实务、数据合规、知识产权保护等专题培训，提升科研人员的合规风险意识与法律素养。","requirements":"1. 教育背景\n- 全日制本科及以上学历，法学（民商法、经济法、知识产权法、网络安全法方向优先）、金融、财经、知识产权管理等相关专业背景。\n2. 专业资质\n- 持有法律职业资格证书（A证）；具有CPA、CFA或基金从业资格者优先。\n3. 工作经验\n- 具备5-10年风控合规、法务或投后相关领域经验，其中至少2年人工智能、科技企业、国家级科研院所或互联网大厂相关经验。\n- 有高校/科研院所科技成果转化、国有资产管理经验者优先；有基金公司投后相关经验者优先；有知名律所/会计师事务所相关经验者优先。\n4. 核心能力\n- 专业判断力：精通成果转化领域核心法律法规及政策，能精准解读政策影响并转化为可落地的合规方案；具备合同审核、法律文书撰写及纠纷处理能力；具备较强的经营思维及风险防控意识，能独立识别、评估和处置复杂风险。\n- 复合知识结构：具备财务、法律复合知识基础；理解AI技术逻辑，具备一定的技术判断与市场分析能力，能与AI科研团队高效沟通。\n- 沟通协调力：较强的沟通协调能力和文字功底，能与科研团队、投资机构、法律顾问、政府监管部门等多方高效协作。\n- 政治素养与操守：具备高度的责任心与保密意识，政治素质过硬，认同国家战略科技力量使命。\n\n* 特别说明\n1. 国家AI实验室的特殊性\n需深刻理解“国家级新型科研事业单位”在国有资产管理、科技安全审查方面的特殊性；熟悉《科学技术进步法》《促进科技成果转化法》及国家关于AI领域“放管服”改革的最新政策。深刻理解高校院所“国有资产”管理的特殊性，熟悉知识产权作价投资、赋权改革等创新模式中的关键风控节点。\n2. 尽职免责机制\n熟悉国家及地方关于科技成果转化尽职免责的相关规定，能指导单位落实“三个区分开来”原则，营造敢于创新、合规转化的氛围。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7667078262334523658","sourceKey":"shlab_social","company":"上海AI实验室","title":"项目活动运营","city":"上海","category":"业务通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7667078262334523658?mode=social","duty":"1. 综合运营与支持\n1.1 综合运营：作为中心负责人的核心支持，高效管理其工作日程、差旅行程及重要会议的组织安排；作为内外部沟通的关键枢纽，协助进行团队管理、核心成员关系维护及跨部门协同。\n1.2 活动支持：与多部门协同，策划、组织、协同支持相关活动，包括但不限于技术大会、学术分享等。\n2. 科研项目与文案支持\n协助项目经理及科研人员进行科研项目书、结题材料的撰写支持；负责人员信息收集、文案初审及系统申报上传等事务。\n3. 技术成果宣发与社区运营\n负责技术成果在各渠道的宣发，负责内容策划与制作及社交账号的日常运维；\n4. 生态合作对接\n配合项目负责人进行外部生态合作对接，协助与高校、其他实验室及合作伙伴建立并维护良好的互动关系。","requirements":"1. 全日制本科及以上学历，1年及以上运营、综合行政管理相关工作经验；\n2. 极强的沟通协调与组织能力：具备出色的多任务处理、活动组织能力及能动性；\n3. 具备优秀的责任心、耐心与抗压能力，能妥善处理繁杂的部门行政工作；\n4. 具备良好的英文书面沟通能力，能独立处理英文邮件及日常英文材料；\n5. 有独立撰写文案、视频图片制作能力者优先；\n6. 拥有具身智能或相关领域的行业经历者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7665935715435612466","sourceKey":"shlab_social","company":"上海AI实验室","title":"代码预训练数据研究工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7665935715435612466?mode=social","duty":"【岗位介绍】\n团队已具备大规模代码数据、file-level 基础预处理和粗清洗 pipeline、已有代码质量评分系统，以及 proxy training、代码评测和数据版本交付能力。\n该岗位负责代码预训练数据的质量研究和最终质量把关，重点探索高价值代码数据源和数据形态，以及更有效的筛选、评分、修复、合成和采样方法。\n我们希望候选人不仅能够判断代码是否可解析或可运行，还能够判断代码是否清晰、惯用、可维护、可测试，并且值得模型学习和模仿。\n\n【团队协作】\n我们有专门的数据工程团队，负责代码数据接入、file-level 基础预处理、粗清洗、规模化 pipeline 和生产运行。\n本岗位侧重代码数据源与数据形态研究、代码质量算法、原型验证和训练效果分析。双方将共同定义预处理和质量方案，推动有效方法规模化应用，并结合代码质量分析和模型实验持续迭代代码数据版本。\n\n1. 负责代码预训练数据的质量研究、数据策略实现、训练验证和版本化交付。\n2. 与数据中心团队合作，定义并验收 file-level 代码 preprocessing substrate，包括语言识别、SHA256/MinHash 去重、语法解析、文件分类、reject reason 和数据版本接口。\n3. 建设代码质量评价体系，包括：\n  - LLM teacher 标注和质量 rubric；\n  - 回归 scorer、ranker 或轻量分类器；\n  - 代码可读性、正确性、完整性、复杂度及教育价值评估；\n  - Generated、vendored、minified、test、config 和 template 文件分类。\n4. 借鉴 Seed-Coder、Nemotron 等公开方法，验证 heuristic filtering、LLM scorer 和 soft weighting 等方案的训练效果。\n5. 研究当前被过滤代码数据中的 false rejection，探索修复、重新组织、重评分或转换为其他数据形态后对预训练的价值。\n6. 负责多编程语言数据覆盖、语言配比、代码领域配比和数据难度分布分析。\n7. 研究并实现 FIM、代码—注释、代码—文档、测试—实现、跨语言转换及其他代码数据形态。\n8. 建设代码 benchmark contamination 检测方案，覆盖 EvalPlus、MultiPL-E、MBPP、CRUX-O 等评测。\n9. 设计并执行代码数据消融及 proxy training 实验，评估代码数据对 Coding、Reasoning、Math/STEM 及 General 能力的影响。\n10. 按照统一标准完成代码 candidate、primary 和 fallback 数据版本的 materialization，包括质量统计、语言分布、污染检查、抽样验收和版本记录。\n11. 与网页、PDF 数据负责人及预训练负责人合作，确定代码数据在 Stable、Decay 等阶段中的使用方式和配比。","requirements":"1. 具有大语言模型、代码模型、程序分析、机器学习或代码数据处理经验。\n2. 熟悉 Python，并能够阅读和处理多种主流编程语言。\n3. 理解 AST、parser、Tree-sitter、代码去重、FIM 和 repository/file 数据结构。\n4. 具有 LLM batch inference、数据评分、模型训练或数据消融实验经验。\n5. 能够在不完整基础设施条件下快速实现研究原型，并与工程团队协作完成规模化。\n\n加分项\n- 参与过代码大模型预训练或代码语料建设；\n- 熟悉 Seed-Coder、StarCoder、The Stack、OpenCoder 或 Nemotron Code 数据方法；\n- 具有代码执行、编译、单元测试或沙箱环境经验；\n- 熟悉多编程语言 benchmark 和代码数据污染检测；\n- 具有合成代码、代码重写、代码审查或跨语言转换数据经验。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7665932167037536566","sourceKey":"shlab_social","company":"上海AI实验室","title":"网页预训练数据研究工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7665932167037536566?mode=social","duty":"【岗位介绍】\n团队已具备大规模网页数据、基础预处理和粗清洗 pipeline、已有质量评分系统，以及 proxy training、模型评测和数据版本交付能力。\n该岗位负责网页预训练数据的质量研究和最终质量把关，重点探索高价值数据源，以及更有效的筛选、评分、修复、合成和采样方法，在扩大有效数据规模的同时持续提升数据质量。\n\n【团队协作】\n我们有专门的数据工程团队，负责网页数据接入、基础预处理、粗清洗、规模化 pipeline 和生产运行。\n本岗位侧重网页数据源评估、质量算法研究、原型验证和训练效果分析。双方将共同定义网页数据方案和质量指标，协同推动有效方法的规模化落地，并结合数据统计、抽样分析和模型实验持续迭代数据版本。\n\n岗位职责\n1. 负责网页预训练数据的质量研究、数据方案实现和版本化交付。\n2. 基于现有网页处理 pipeline，研究不同数据筛选、分类、评分、修复和采样策略对模型能力的影响。\n3. 建设和优化网页质量评价体系，包括但不限于：\n  - 内容质量、知识密度和教育价值评分；\n  - 广告、导航、SEO、模板化和低信息内容识别；\n  - 领域、主题、语言及难度分类；\n  - LLM scorer、轻量分类器和规则的组合使用。\n4. 分析当前被过滤网页数据中的 false rejection，研究通过正文修复、重新切分、去模板、重写、重新评分或降低采样权重等方式恢复其训练价值。\n5. 负责网页数据中的通用知识、STEM、推理及多语言数据覆盖分析，并提出相应的数据采样和配比方案。\n6. 设计并执行数据消融及 proxy training 实验，评估不同网页数据方案对 General、Knowledge、Reasoning 和 Multilingual benchmark 的影响。\n7. 按照统一标准完成网页 candidate、primary 和 fallback 数据版本的 materialization，包括质量统计、抽样检查、版本记录和发布验收。\n8. 与 PDF、代码数据负责人及预训练负责人协作，参与整体预训练数据 mixture 的设计和迭代。","requirements":"1. 具有 NLP、大语言模型、搜索、推荐、内容理解或大规模文本数据处理经验。\n2. 熟悉网页文本中的正文抽取、模板内容、重复内容、垃圾内容和语言识别等问题。\n3. 能够独立设计数据质量指标、训练实验和对照实验，并根据模型结果迭代数据策略。\n4. 熟练使用 Python，具备良好的数据分析和工程实现能力。\n5. 熟悉至少一种分布式数据处理或大规模推理框架。\n\n\n加分项\n- 具有 LLM 预训练数据建设经验；\n- 做过网页质量排序、内容理解或搜索索引；\n- 具有多语言或低资源语言数据经验；\n- 熟悉数据去污染、数据溯源和训练数据合规问题。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7665931657489664302","sourceKey":"shlab_social","company":"上海AI实验室","title":"文档与 PDF 预训练数据研究工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7665931657489664302?mode=social","duty":"【岗位介绍】\n团队已具备大规模 PDF 和复杂文档数据、基础解析与清洗 pipeline，以及 proxy training、模型评测和数据版本交付能力。现阶段的主要目标，是将复杂文档恢复为适合大语言模型预训练的高质量 Markdown，并在需要时使用 LaTeX 保留数学和科学内容。\n该岗位负责文档预训练数据的质量研究和最终质量把关，重点探索高价值文档数据源，以及更有效的解析质量评估、内容修复、结构恢复、评分和采样方法。\n\n【团队协作】\n我们有专门的数据工程团队，负责 PDF 数据接入、通用解析、Markdown/LaTeX 转换、基础清洗、规模化 pipeline 和生产运行。\n本岗位侧重目标文档表示、质量评价方法、关键问题研究和训练效果分析。双方将共同分析解析结果、确定优先改进方向、推动有效方案的规模化应用，并持续提升文档数据的结构保真度和训练价值。\n\n岗位职责\n1. 负责 PDF 及复杂文档预训练数据的质量研究、数据方案实现和版本化交付。\n2. 基于现有 PDF pipeline，研究解析质量、文档结构恢复和内容筛选策略对模型预训练效果的影响。\n3. 建设 PDF 和文档质量评价体系，包括：\n  - OCR 和文本抽取质量评估；\n  - 阅读顺序、段落、标题及章节结构恢复；\n  - 页眉页脚、目录、引用和重复内容清理；\n  - 表格、公式、代码块及图注等特殊内容识别；\n  - 文档完整性、知识密度、专业性和教育价值评分。\n4. 对解析失败或当前被过滤的文档进行分类，研究通过重新解析、版面恢复、段落重组、内容修复或模型重写等方式恢复数据价值。\n5. 重点建设高质量 STEM、数学、教材、论文、技术报告及专业知识数据。\n6. 设计 PDF 数据与网页数据之间的去重、互补性分析和采样策略，避免重复 Token 占用训练预算。\n7. 设计并执行数据消融和 proxy training 实验，评估 PDF 数据对 Knowledge、STEM、Math、Reasoning 及 Multilingual 能力的贡献。\n8. 按照统一标准完成 PDF candidate、primary 和 fallback 数据版本的 materialization，包括质量统计、失败类型分析、抽样验收和版本记录。\n9. 与网页、代码数据负责人及预训练负责人协作，参与整体数据 mixture 设计。","requirements":"1. 具有文档理解、OCR、版面分析、NLP 或大语言模型数据处理经验。\n2. 熟悉 PDF 和复杂文档常见问题，包括多栏布局、扫描件、公式、表格、乱码和阅读顺序错误。\n3. 能够结合规则、模型和统计方法建立文档质量评价和修复流程。\n4. 熟练使用 Python，能够独立完成数据分析、实验实现和数据版本交付。\n5. 能够设计训练实验，判断文档质量变化是否真正改善模型能力。\n\n\n加分项\n- 具有图书、教材、论文、专利或技术文档处理经验；\n- 熟悉数学公式、表格或科学文献解析；\n- 具有多语言 OCR 或低资源语言文档经验；\n- 做过文档修复、结构化抽取或多模态文档理解。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7664940771481782547","sourceKey":"shlab_social","company":"上海AI实验室","title":"【高阶岗位】预训练青年/资深科学家","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7664940771481782547?mode=social","duty":"岗位职责\n1  预训练技术路线与体系规划\n- 参与制定通用基座大模型中长期预训练技术规划，涵盖大规模预训练数据、预训练任务、训练范式、并行架构、超参体系等顶层设计；\n- 研判业界基座模型技术趋势，持续优化稠密模型、稀疏MoE模型训练路线，定义年度基座模型迭代版本与技术指标；\n- 结合OpenCompass评测体系，建立基座模型能力基线，形成训练、评测、归因、迭代完整研发闭环。\n2 大规模预训练算法攻关\n- 通用基座大模型预训练算法研发，优化预训练目标函数、训练 Curriculum、知识覆盖、冷热知识平衡；\n- 负责模型初始化、归一化、激活、位置编码等底层模块调优，提升模型收敛速度、训练稳定性与泛化能力；\n- 攻克超大模型训练梯度爆炸、损失震荡、欠拟合、能力偏科等技术难点，持续提升通识、数理、代码、逻辑基础能力。\n3 预训练数据工程体系建设\n- 协助统筹万亿级高质量预训练语料建设，负责数据来源、分布配比、去重、过滤、提纯、脱敏、分词体系搭建；\n- 设计多领域、多语种、多知识层级的数据配比策略，优化高质量知识语料、专业语料、长文本语料占比；\n- 建立数据质量评估、污染检测、异常识别机制，构建标准化、可迭代、可管控的预训练数据生产线。\n4 算力及模型训练协同\n- 联动算力工程、模型架构、后训练、多模态团队，完成分布式训练、显存优化、通信优化、算力调度协同；\n- 参与制定训练集群运维规范、训练故障排查机制，保障大规模长时间稳定预训练。","requirements":"1  基础资质\n- 计算机、人工智能、数学、NLP、深度学习等相关专业，博士学历优先，顶尖名校硕士可破格；\n- ，具备极强科研判断力，认同实验室长期主义基座研发理念。\n2 工作经验\n- 6年以上大模型预训练研发经验，2年以上算法团队管理经验；\n- 完整主导过百亿/千亿参数稠密大模型预训练全流程，具备大规模算力集群量产训练经验；\n- 有头部研究院、大厂基座大模型研发经验，熟悉国产算力集群训练流程优先。\n3 专业能力\n- 精通Transformer基座原理，熟练掌握预训练任务设计、训练超参调优、loss优化、训练稳定性控制；\n- 精通大规模文本数据处理流程，熟悉数据去重、质量过滤、毒性检测、领域配比、语料提纯；\n- 熟练掌握Megatron-LM、DeepSpeed等分布式训练框架，精通张量并行、流水线并行、MoE并行技术；\n- 具备模型训练故障归因、损失分析、收敛调优实战能力，深刻理解大模型涌现能力与缩放定律。\n4  综合素质\n- 具备基座模型顶层设计能力，能够独立制定中长期预训练技术路线；\n- 抗压能力强，擅长大规模研发团队统筹、跨部门协同、算力资源调度；\n- 在ICML、NeurIPS、EMNLP等顶会发表预训练、大模型相关论文/专利优先。\n5. 优先条件\n- 主导过百亿至千亿级基座大模型完整预训练、冻结、版本迭代、开源发布；\n- 在大规模数据工程、并行训练、训练稳定性、稀疏模型任一方向有行业标杆成果；\n- 具备主流基座模型深度训练优化经验。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7662203193427003667","sourceKey":"shlab_social","company":"上海AI实验室","title":"AI战略和创新研究 - 战略研究中心","city":"上海","category":"战略类","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7662203193427003667?mode=social","duty":"1. 发现创新规律，输出战略洞见\n  - 系统追踪全球AI前沿，发掘创新特性和底层规律（大模型创新演进、AI4S科学智能等）\n  - 开展技术创新规律和科学学研究，分析科学智能如何重塑科学研究范式\n  - 对标国际顶级实验室，比较技术路线选择、资源配置逻辑和研究差异，提炼可借鉴的创新方法论\n  - 定期研究分析报告，输出可检验、可测量的战略判断\n2. 撰写战略级文稿，端到端交付\n  - 从实验室和高层战略需求出发，独立或组织完成从问题拆解、研究组织、分析论证到文稿转化的全流程交付\n  - 负责汇报材料的整体思想框架设计，确保逻辑严谨、论据充分、表达精准\n  - 统筹内外部研究资源，在限定时间内完成高质量的战略级汇报和Keynote演讲稿\n  - 战略汇报材料、对外Keynote演讲及论述体系\n3. 沉淀战略思想，体系化呈现\n  - 将分散的研究成果和战略观点提炼为体系化的思想框架，建立可复用的核心观点库和论证素材库\n  - 持续维护实验室的战略知识资产，开展战略方法论研究\n  - 形成实验室对外表达的战略论述体系，确保在不同场合中传递一致且有说服力的战略叙事","requirements":"1. 3-5年人工智能领域的工作/研究经验、战略研究或规划经验。具有独立思考和批判精神，能站在行业前沿思考问题，在人工智能、大模型、AI for Science等方向研究基础扎实，有政府汇报材料、大会演讲稿撰写经验者优先\n2. 研究导向判断力：能从复杂信息中识别底层规律和关键拐点，提出前沿观点而非行业共识\n3. 强烈学习欲望和好奇心：对AI的未来发展有真诚的思考和判断，而非追赶热点，习惯于拥有从0到1的问题，而不是执行现成的方案\n4. 端到端交付能力：习惯从问题定义、方案设计到最终交付的全程拥有；能协调多方资源；擅长在不确定中建立清晰的执行计划，完成高质量工作交付\n5. 结构化思维能力：能够将模糊的战略问题拆解为可研究的子问题，构建分析框架，并在复杂信息中识别关键变量和因果关系。具备优秀的文字功底，能够清晰、严谨地表达思想\n6. 沟通协调能力：善于在复杂项目中推动多方达成共识并保持一致的行动节奏，具备将研究语言转化为战略语言、将技术语言转化为决策语言能力\n","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7659998782134487302","sourceKey":"shlab_social","company":"上海AI实验室","title":"移动操作算法研究员","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7659998782134487302?mode=social","duty":"面向真实物理世界中的移动操作场景，负责机器人系统的工程化落地与真机部署。你将与算法、平台及硬件团队紧密协作，打通从数据采集、模型部署到真机运行的完整流程，持续优化机器人在复杂环境中的稳定性、鲁棒性和执行效率，推动具身智能算法真正应用于真实机器人系统。\n如果你热爱机器人、享受在真实世界解决复杂工程问题，并希望将前沿具身智能算法真正部署到机器人平台，欢迎加入我们，一起推动具身智能技术在真实世界中的落地。\n\n1. 围绕移动操作（Mobile Manipulation）开展具身智能前沿算法研究，探索 Vision-Language-Action（VLA）、World Model、Diffusion Policy、模仿学习、强化学习等方向的新方法；\n2. 针对真实机器人场景中的泛化能力、长时序决策、跨场景迁移等关键问题，设计并研发具有创新性的算法；\n3. 独立推进完整的研究闭环，包括问题定义、算法设计、模型实现、实验验证、真机评测及持续优化；\n4. 与机器人平台及工程团队协作，将算法部署到真实机器人系统，推动研究成果在真机上的验证与落地；\n5. 跟踪具身智能领域前沿研究，主导或参与国际顶级会议论文、专利及开源项目等高质量研究成果的产出。 ","requirements":"1. 计算机、人工智能、机器人、自动化等相关专业博士学历，具有扎实的机器学习与机器人研究基础；\n2. 在 Embodied AI、Robot Learning、Vision-Language-Action（VLA）、World Model、模仿学习、强化学习、Diffusion Policy 等一个或多个方向具有深入研究经验；\n3. 具备独立开展科研工作的能力，能够完成从问题定义、方法设计到实验验证的完整研究流程，并持续推进技术创新；4. 熟悉 PyTorch、JAX 等深度学习框架，具备较强的算法实现与实验能力；\n5. 有真实机器人（轮式机器人、机械臂、双足或人形机器人等）实验或部署经验，能够结合真机开展算法验证。 \n\n加分项\n1. 在 NeurIPS、ICML、ICLR、CVPR、ICCV、ECCV、CoRL、RSS、ICRA、IROS 等国际顶级会议发表论文；\n2. 在移动操作（Mobile Manipulation）、机器人基础模型（Foundation Model）、长时序操作、多机器人协作等方向具有代表性研究成果；\n3. 有大规模机器人数据、机器人 Foundation Model 或真实机器人系统研发经验；\n4. 具有开源项目、工业研究或技术落地经验。 ","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7659997654215264563","sourceKey":"shlab_social","company":"上海AI实验室","title":"多智能体平台算法工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7659997654215264563?mode=social","duty":"负责物理智能平台底座的搭建与持续迭代，把机器人、算法与数据打通成一套可扩展的系统。工作覆盖 Agent 框架的开发与编排、任务调度与设备接入等核心模块的设计落地，为上层的具身算法研究与真机实验提供稳定支撑。\n\n1. 负责物理智能平台底座的架构设计、开发与迭代，独立承担核心模块从设计到落地的全过程；\n2. 搭建与优化具身智能体框架，打通算法、机器人与数据的链路；\n3. 保障系统在真机场景下的稳定性、扩展性与可维护性。","requirements":"1. 熟悉 Agent 框架的开发与编排，有实际项目落地经验；\n2. 对 OpenClaw 或同类Agentic 工具链有实战经验；\n3. 工程功底扎实，能独立负责模块设计与落地；\n4. 有大型平台 / 中间件 / 调度系统经验，或有机器人、具身系统相关工程经验者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7659996225454950719","sourceKey":"shlab_social","company":"上海AI实验室","title":"移动操作算法工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7659996225454950719?mode=social","duty":"面向真实物理世界中的移动操作场景，负责机器人系统的工程化落地与真机部署。你将与算法、平台及硬件团队紧密协作，打通从数据采集、模型部署到真机运行的完整流程，持续优化机器人在复杂环境中的稳定性、鲁棒性和执行效率，推动具身智能算法真正应用于真实机器人系统。\n如果你热爱机器人、享受在真实世界解决复杂工程问题，并希望将前沿具身智能算法真正部署到机器人平台，欢迎加入我们，一起推动具身智能技术在真实世界中的落地。\n\n1. 负责移动机器人操作算法的工程实现、真机部署及工程化落地，推动算法在真实机器人上的稳定运行；\n2. 搭建并持续优化从数据采集、模型训练到真机部署的完整 Pipeline，提升开发效率与系统稳定性；\n3. 针对真实物理场景开展算法调试、性能优化与效果迭代，持续提升机器人系统的鲁棒性、执行效率和泛化能力；\n4. 与算法、平台及硬件团队紧密协作，完成算法在真实机器人上的部署、联调与验证，推动技术成果落地。","requirements":"1. 硕士及以上学历，计算机、人工智能、机器人、自动化等相关专业；\n2. 具有移动机器人（轮式机器人/双足机器人/人形机器人等）真机开发、部署或系统集成经验；\n3. 熟悉 ROS / ROS2，能够独立完成机器人软件开发、调试、部署及系统联调；熟练使用 C++ 或 Python，具备良好的 Linux 开发经验和工程实践能力；\n4. 具备较强的问题分析与工程调试能力，能够独立定位并解决真实机器人运行中的复杂问题；\n5. 具备良好的软件工程意识，代码规范、可维护性强，具有良好的团队协作能力。\n\n加分项\n1. 有移动操作（Mobile Manipulation）、机械臂、人形机器人或双足机器人项目经验；\n2. 有VLA、Diffusion Policy、模仿学习、World Model 等具身智能算法的部署或工程实现经验；\n3. 熟悉导航、SLAM、运动规划、机器人控制等机器人核心模块，有机器人大规模部署经验；\n4. 在机器人、具身智能、人工智能等相关方向发表过论文，或在 CoRL、RSS、ICRA、IROS、CVPR、ICCV、ECCV、NeurIPS、ICML、ICLR 等国际会议发表论文，或具有同等水平研究成果者优先。 ","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7659334795419748658","sourceKey":"shlab_social","company":"上海AI实验室","title":"世界模型训练与真机部署工程师/青年研究员","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7659334795419748658?mode=social","duty":"1. 负责物理智能世界模型的训练、优化与评估；\n2. 构建机器人数据闭环，覆盖数据采集、清洗、对齐、质量评估与训练样本构建；\n3. 负责多模态机器人模型训练，融合视觉、语言、动作、状态及传感器信息；\n4. 搭建模型真机部署链路，完成推理、控制接口适配、延迟优化、稳定性测试和实验复盘；\n5. 跟进物理智能、机器人基础模型、World Model、VLA/VLM、Diffusion Policy、Imitation Learning、RL 等相关前沿工作，并复现或验证关键方法。","requirements":"1. 计算机、人工智能、机器人、自动化、电子工程、机械工程、数学等相关专业硕士及以上学历；\n2. 熟练掌握 Python，熟悉 PyTorch / JAX / TensorFlow 中至少一种深度学习框架；\n3. 熟悉机器人学习或具身智能基础方法，如模仿学习、强化学习、行为克隆、轨迹预测、运动控制等；\n4. 具备扎实的深度学习基础，了解 Transformer、Diffusion Model、VLM/VLA、多模态学习或序列建模等技术；\n5. 具备良好的工程实现、实验设计、问题分析和系统调试能力；\n6. 有机器人真机实验经验或强烈兴趣，能够处理真实系统中的传感器误差、控制延迟、硬件异常和环境变化等问题。\n\n加分项：\n1. 有机器人真机部署、仿真平台或机器人数据集使用经验；\n2. 有 World Model、VLA/VLM、Diffusion Policy、Model-Based RL 等相关项目经验；\n3. 有大规模模型训练、视觉/三维感知、C++ 系统集成经验；\n4. 在机器人、机器学习、计算机视觉或强化学习方向有论文、竞赛、开源项目或产品化经验。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7657846659330558259","sourceKey":"shlab_social","company":"上海AI实验室","title":"智能体攻防算法工程师/青年研究员","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7657846659330558259?mode=social","duty":"1. 负责AI智能体全链路安全攻防研究，覆盖终端智能体、电脑操作智能体等复杂交互场景。构建智能体攻防技术体系，设计渗透测试方案、漏洞挖掘工具与自动化攻防平台，支撑智能体系统安全能力的实战化验证；\n2. 研究AI驱动的自动化漏洞挖掘与利用技术，包括构建漏洞挖掘Agent框架，实现多工具协同编排（调试器、反编译器、模糊测试框架、符号执行引擎等），完成从漏洞发现到PoC/Exploit生成的全自动化转化；\n3. 研究AI for Security技术，将机器学习/深度学习算法应用于渗透测试、漏洞挖掘、漏洞利用、漏洞管理、代码修复等传统网络安全领域，实现\"以AI对抗攻击\"的技术落地。","requirements":"1. 本科及以上学历，计算机科学、信息安全、网络空间安全、软件工程或相关专业背景优先，一年及以上安全领域工作经验者优先；\n2. 具备扎实的机器学习和深度学习基础知识和算法实践能力，了解大模型的设计和训练流程；\n3. 具备安全研究基础，熟悉常见漏洞类型（如内存破坏、逻辑漏洞、Web漏洞等）的原理与利用技术，熟练使用IDA Pro、Ghidra、GDB、AFL、Burp Suite等至少一种逆向分析或漏洞挖掘工具，有代码审计经验、CTF竞赛经验或CVE/CNVD发现经历者优先；\n4. 熟悉常用的深度学习框架和工具，具备良好的编程能力，熟练使用Python、C/C++等编程语言；具备安全工具开发或AI Coding工具安全场景定制经验者优先；\n5. 在CVPR、NeurIPS、ICLR等人工智能会议或CCS、S&P、USENIX Security、NDSS、Black Hat等安全顶会有出色发表记录者优先。\n\n加分项：\n1. 在信息学奥赛、ACM、CTF竞赛（如DEF CON CTF、XCTF等）中获奖；\n2. 具备渗透测试、漏洞挖掘、逆向分析、模糊测试、符号执行等项目经验；\n3. 参与过开源安全工具/框架的开发与维护，或在CNVD、CVE等平台提交过高质量漏洞，有PoC/Exploit开发经验者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7657111150010288411","sourceKey":"shlab_social","company":"上海AI实验室","title":"招聘数据运营专员","city":"上海","category":"职能通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7657111150010288411?mode=social","duty":"1. 招聘流程运营与系统管理\n    负责招聘中台系统的日常运营与维护，搭建并持续优化招聘流程管理机制，确保招聘流程高效、规范运转；统筹简历池、人才库及招聘渠道信息管理，提升人才资源复用效率。\n2. 招聘数据跟踪与分析\n    负责招聘全流程数据监控与分析，包括需求、投递、面试、Offer、入职等关键环节的数据追踪，定期输出周报、月报及专项分析报告，为招聘策略优化提供数据支持。\n3. 招聘流程标准化与效率提升\n    参与设计并优化招聘全流程 SOP，识别流程中的关键卡点与低效环节，推动流程标准化、自动化及数字化建设，提升招聘交付效率与候选人体验。\n4. 渠道运营与效果评估\n    协助管理招聘渠道，包括猎头、招聘平台、高校合作、内推等，跟踪渠道投产表现，建立渠道评估机制并输出 ROI 分析，持续优化渠道结构。\n5. 招聘质量管理\n    协助组织面试官培训，推动面试评价标准统一；参与优化面试评价体系，提升评估质量与决策一致性。\n6. 跨团队协同支持\n    对接业务招聘团队、招聘系统供应商及 HRSSC，协助推进 Offer 发放、入职流程衔接等关键节点，保障招聘交付闭环。","requirements":"1. 本科及以上学历，人力资源管理、统计学、数据分析、管理类相关专业优先。\n2. 1–3 年招聘运营、招聘协调、HR Ops 或数据运营相关经验，应届优秀候选人亦可。\n3. 对数据敏感，具备基础数据分析能力，熟练使用 Excel / Google Sheets（掌握数据透视表、函数等）；有 Power BI、Tableau 或 SQL 经验加分。\n4. 具备较强的流程意识和细节管理能力，能够发现问题并推动优化。\n5. 具备良好的沟通协调能力，能高效推动多方协作。\n6. 对 AI 工具、自动化系统或招聘数字化建设有兴趣者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7656639708097759497","sourceKey":"shlab_social","company":"上海AI实验室","title":"【高阶岗位】多模态方向青年/资深科学家","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7656639708097759497?mode=social","duty":"1多模态技术战略与路线规划\n- 结合行业前沿与实验室战略，参与制定多模态大模型中长期技术规划，涵盖通用图文大模型、视频多模态、多模态理解生成、跨模态对齐等方向；\n- 跟踪国内外SOTA多模态技术迭代，研判多模态大模型技术趋势，定义团队科研课题，攻克复杂图文推理、细粒度视觉理解、长视频理解、多模态幻觉抑制等技术瓶颈；\n- 协助进行多模态模型全系迭代升级，搭建专业多模态评测子集，完善多模态评测体系，构建行业领先的通用多模态技术底座。\n2 团队管理与多模态人才建设\n- 负责多模态专项团队搭建、组织架构优化、人员分工，制定科研考核与激励机制，打造高效自研研发团队；\n- 引进视觉、多模态、AIGC、视频理解领域顶尖科研人才，培养青年算法骨干，搭建学术+工程复合型研发团队；\n- 把控团队研发节奏，组织技术评审、算法复盘，解决多模态训练、对齐、推理过程中的核心技术难题。\n3 重大科研项目与技术攻关\n- 牵头申报并执行国家级、省部级多模态人工智能重大专项，负责项目方案撰写、经费管控、进度管理、验收交付；\n- 主导通用多模态基座模型预训练、跨模态对齐、指令微调、图文联合优化全流程研发，统筹多模态高质量数据集构建、大规模算力调度、分布式训练优化；\n- 推进行业多模态落地应用，涵盖工业视觉、科学计算多模态、图文生成、智能感知等方向，打通科研成果产业转化链路。\n4 开源生态与对外产学研合作\n- 对接高校、科研院所、头部企业，开展多模态产学研合作，拓展数据集、算力、行业落地资源；\n- 负责多模态技术成果对外输出、行业峰会技术分享，维护实验室多模态领域行业影响力；\n- 完善开源体系，运营多模态开源社区，迭代开源模型与工具链，扩大行业开源影响力。\n5 资源管控与技术资产沉淀\n- 统筹多模态算力、高质量图文视频数据、科研经费分配，优化GPU集群训练调度，控制研发成本；\n- 规范多模态数据合规、图像版权、算法安全、知识产权管理，搭建多模态科研风控体系；\n- 发表顶会论文、编制多模态技术白皮书、沉淀模型专利，固化实验室多模态核心技术资产。","requirements":"1 学历与基础资质\n- 计算机、人工智能、视觉算法、深度学习、数学等相关专业，博士优先，顶尖名校硕士可放宽；\n- 抗压能力强，认同科研机构长期研发理念，热爱多模态技术研究。\n2 工作经验要求\n- 具备上多模态/计算机视觉/AIGC研发经验，2年以上技术团队管理经验，具备专项团队统筹能力；\n- 有头部科研机构、大厂研究院多模态研发经验，主导过开源通用多模态模型、图文大模型、视频大模型完整迭代流程；\n- 有书生万象、CLIP、Flux、VLM等主流多模态模型研发、二次优化、落地经验者优先。\n3 专业技术能力\n- 精通Transformer、ViT、多模态融合架构，熟练掌握图文对齐、视觉编码、文本解码、多模态SFT/DPO对齐技术；\n- 精通大规模图文、视频数据集清洗、过滤、提纯，熟悉多模态数据构建方法论，掌握分布式多模态训练、显存优化、并行训练技术；\n- 熟悉图像生成、视频理解、多模态推理、幻觉抑制优化，对通用多模态发展方向有深度判断；\n- 具备多模态评测体系搭建经验，熟悉多模态感知、生成、推理类评测指标与优化方案。\n4 综合能力素质\n- 具备多模态技术顶层设计能力，能够精准判断行业技术风口，制定长期研发路线；\n- 具备团队搭建、人才培养、跨部门协同能力，逻辑清晰、决策果断，科研项目管控能力强；\n- 具备优秀技术汇报，可独立对接政府及行业合作机构；\n- 在CVPR、ICCV、ECCV、NeurIPS等顶会发表多模态/视觉方向论文、持有核心专利者优先；\n- 恪守科研伦理，无学术不良记录，责任心强，高度认同上海人工智能实验室科研发展理念。、\n5. 优先录用条件\n- 主导过十亿参数及以上通用多模态基座模型完整训练、对齐、开源落地全流程；\n- 主持过国家级多模态、人工智能重大科研专项，熟悉政府项目申报、评审、验收流程；\n- 在视频理解、图文生成、多模态推理、具身智能任一方向有行业公认突出成果；\n- 海内外顶尖高校、科研院所视觉/多模态资深研究员，行业具备较高学术影响力。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7655578882447296778","sourceKey":"shlab_social","company":"上海AI实验室","title":"【高阶岗位】产品运营架构师","city":"上海","category":"业务通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7655578882447296778?mode=social","duty":"1、统筹部门各产品线的用户增长与运营策略，推动科学发现平台、书生模型等核心产品的用户规模提升与活跃度建设\n2、搭建并运营开发者社区与用户社区，建立用户反馈闭环，驱动产品持续优化 \n3、建设数据运营体系，沉淀用户行为数据，推动科研数据有效回流，支撑模型迭代\n4、拓展高校、科研机构、行业合作伙伴等外部生态，推动产品在目标场景中的渗透与落地\n5、统筹对外品牌传播、成果展示与重大活动支持，提升产品与实验室的行业影响力\n6、搭建运营团队，建立运营指标体系与复盘机制    ","requirements":"1、8 年以上互联网产品运营或技术平台运营经验，3 年以上团队管理经验 \n2、有开发者生态、开源社区、科研平台或 AI 产品的运营经验者优先\n3、具备从 0 到 1 搭建运营体系的能力，能独立制定增长策略并落地执行\n4、数据驱动，熟悉用户增长模型与社区运营方法论\n5、优秀的跨团队沟通协调能力，能拉通产品、工程、算法等多方资源\n6、对 AI、科学计算或科研领域有了解或兴趣者优先","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7655521720548624678","sourceKey":"shlab_social","company":"上海AI实验室","title":"全球高端招聘主管","city":"上海","category":"职能通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7655521720548624678?mode=social","duty":"1、高端人选寻访与触达：面向全球AI高端人才市场开展主动寻访，建立并维护目标人才地图与高质量人脉网络，精准触达候选人。\n2、全流程闭环交付：独立负责从需求对接、人选评估、面试推进、薪酬谈判到Offer落地的完整链条，对关键岗位的到岗结果负责。\n3、业务深度对接：与用人团队紧密协同，准确理解技术方向与岗位画像，把模糊需求转化为清晰的寻访策略。\n4、人才库与渠道运营：搭建并沉淀高端人才储备库，持续运营高校、顶会、产业界、技术社区等多元渠道，提升高端人选的获取效率与转化率。","requirements":"1、具备扎实的技术岗位招聘经验，能听懂技术语言，熟悉AI/算法方向人才结构，熟悉AI领域全球人才分布与科研/产业生态。\n2、8年以上招聘经验，有高端/核心人选成功招募案例，有大型科技企业、AI创业公司或科研院所招聘经验者优先。\n3、结果导向、自驱力强，具备出色的攻坚能力，能有效应对高难度招聘挑战。\n4、英语可作为工作语言，能独立开展国际人才洽谈者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7655242543031273737","sourceKey":"shlab_social","company":"上海AI实验室","title":"多模态大模型青年研究员","city":"上海","category":"算法类","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7655242543031273737?mode=social","duty":"1、负责智能文档解析（含 OCR、布局分析、语义关联提取），设计数据清理、去重、增强及合成方法，提升训练数据质量与规模，支撑模型泛化能力建设。\n2、研发大模型增量训练算法，攻克灾难性遗忘问题；结合强化学习技术，开展多模态、多任务后训练优化，覆盖长思维链推理、指令遵循、智能体能力增强等任务。\n3、研究模型压缩、二值化及高效推理技术，优化模型存储与计算成本，提升模型在不同硬件平台的部署效率，满足实际应用场景需求。\n4、构建强化学习偏好数据集与奖励模型，抑制模型幻觉；开发数据防范机制与微调技术，实现模型安全对齐，确保符合人类价值观。\n5、设计前沿创新的多模态数据融合方案与模型架构，突破通用模型在垂类场景的能力限制，优化模型综合性能与应用范围。","requirements":"1、计算机科学、AI、机器学习等相关专业硕士及以上学历（博士优先），具备扎实的深度学习、大模型理论基础，熟悉 PyTorch/TensorFlow 等框架。\n2、精通至少 3 类关键技术：a, 文档解析与数据合成；b, 持续学习与模型压缩（剪枝、量化）；c，多模态数据融合和模态对齐训练；d, 强化学习 与 RLHF 对齐技术。\n3、熟练使用 Python/C++，具备算法高效实现能力，有分布式推理、混合精度推理等工程实践经验者优先。\n4、在顶会 / 期刊发表相关论文，或有大模型垂类落地项目经验，或算法比赛获奖者优先。\n5、能结合多模态、三维重建、模型安全等跨领域技术，解决垂类场景复杂问题，具备技术创新与落地转化意识。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7655230341552752923","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型训练青年研究员/工程师","city":"上海","category":"算法类","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7655230341552752923?mode=social","duty":"1. 参与实验室新型大模型后训练算法研究，包括但不限于SFT，RL，OPD等方向。\n2. 围绕大模型后训练，参与算法设计、实验验证、效果分析和系统化迭代，推动相关方法在科学推理任务中的落地。\n3. 持续关注最新研究动向，鼓励在高质量会议及期刊上发表高水平论文，打造和提升行业技术影响力。","requirements":"1. 计算机 / 数学 / 统计学等相关专业。\n2. 具备扎实的数学功底和工程能力，熟悉大模型后训练算法相关理论和方法。\n3. 具备良好的沟通表达能力、团队协作意识，以及针对关键技术难题的攻坚能力。\n\n加分项：\n1. 在 ICLR、ICML、NeurIPS、CVPR、ACL等顶会或顶刊上以一作身份发表过学术论文。\n2. 具有材料相关背景和项目经历的优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7654837551317158185","sourceKey":"shlab_social","company":"上海AI实验室","title":"安全保卫专员 - 行政服务办公室","city":"上海","category":"职能通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7654837551317158185?mode=social","duty":"1.园区安全保卫工作的统筹管理：负责园区的日常安全巡查、秩序维护与突发事件应急处置；制定并执行园区人防、物防、技防一体化安全防范方案，确保重点区域安全防范措施全面符合要求；\n2.治安与出入管控：管理园区门禁系统、访客登记、车辆进出及人员身份核验，严格执行科研单位保密区域准入制度；处理园区内治安事件，预防盗窃、破坏、非法入侵等安全风险；与所在区域工单机关建立日常联系，可快速联动处理园区治安事件或安全相关应急突发事件；\n3.重点区域专项防护：针对园区各类空间业态，如公寓、实验室、会议中心等，不同的场景指定对应的安全保卫管理机制，落实物理管控、监控覆盖、巡逻机制作业标准、操作行为监督等一系列安防措施；\n4.参与制定、修订园区安全保卫管理制度、应急预案等，组织安全培训与应急演练，提升园区整体安全意识与自救互救能力；负责安全保卫类工作的作业流程、制度建设、落地实施；\n5.负责安保供应商的日常管理、培训、品控等日常工作及考核，落实实验室安全保卫机制的执行落地，有效发挥供应商的能力和作用；\n6.负责园区大型活动的治安控防及，其它各类治安、安保类突发事件的有效处理；\n7.其他行政支持性工作及跨团队协作和沟通。","requirements":"1.全日制本科及以上学历，类似岗位3年以上经验；安全工程、公安管理或相关专业优先考虑；\n2.专业能力：\n(1)精通安防系统（门禁、监控、报警）操作与基础维护；\n(2)熟悉上海市各类治安相关管理条例、法规、政策等；\n(3)具备独立撰写安全管理制度、应急预案、事件报告的能力；\n3.工作经验：\n(1)3年以上大型国企、事业单位、科研院所或高科技企业安全相关工作经验；\n(2)有公安、武警等政府工作背景者优先；\n(3)具备重要接待或大型活动安全统筹经验者优先；\n4.证书要求：持有注册安全工程师证书者优先\n5.综合素质：\n(1)具备极强的责任心和职业素养，具备高度保密意识，能对风险进行预判，并具备问题解决能力；\n(2)细心严谨，能吃苦耐劳，具有团队精神及良好的沟通协调能力，具备较强独立思考和解决问题;\n(3)较强的文案输出、办公软件熟练使用、有一定统筹能力以及突发事件的解决能力;","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7654799784507279657","sourceKey":"shlab_social","company":"上海AI实验室","title":"机器人操作算法工程师(VLA / World-Action Model 方向)","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7654799784507279657?mode=social","duty":"本岗位面向 VLA 与 World-Action Model 方向,以操作基座模型的研发、训练与部署为核心。本岗位强调从算法到落地的完整工程链路:包括训练框架的搭建与优化、大规模异构操作数据处理 pipeline 的构建、真机与仿真环境下的系统集成与评测,以及模型的高效推理与实时部署。\n\n1. 负责操作基座模型的工程化研发与迭代,完成模型架构与训练策略的工程实现及性能优化；\n2. 跟进最新操作算法动态,快速复现 SOTA 工作并完成工程化落地与验证；\n3. 构建与维护大规模异构操作数据的处理 pipeline,包括多源数据对齐、信号质量过滤、运动学一致性校验、跨模态(视觉-语言-动作)一致性检查等；\n4. 搭建真机遥操作数据采集与部署系统,负责真机与仿真环境下的模型评测、问题定位与调优；\n5. 优化模型推理与实时控制链路,关注端到端延迟与部署效率。\n","requirements":"1. 计算机、自动化、机器人、人工智能等相关专业硕士及以上学历；\n2. 熟悉 Python 与 PyTorch，具备扎实的深度学习基础与工程实现能力，代码质量与工程规范意识良好；\n3. 熟悉 VLA、World-Action Model 经典工作,熟悉 LeRobot、OpenPI、StarVLA 等开源框架；\n4. 了解机器人操作与计算机视觉相关算法,包括但不限于机器人抓取、物体位姿估计、点云处理、模仿学习与强化学习等；\n5. 熟悉机器人运动学与坐标变换(URDF、正/逆运动学、SE(3) 位姿与旋转表示),了解跨本体动作重定向 (retargeting)\n6. 有真机遥操作数据采集经验与真机部署经验；\n7. 有大规模模型训练经验，熟悉多卡 / 分布式训练；\n8. 熟悉主流仿真平台,如 Isaac Sim、Isaac Lab、ManiSkill、RoboCasa 等；\n9. 有 CUDA 编程或模型推理优化经验,有 RTC 等实时部署经验,关注部署效率与延迟。\n\n加分项：\n\n1. 有大规模数据工程经验,熟悉信号滤波、时序对齐、多模态数据清洗与质量控制 pipeline 的搭建；\n2. 有相机标定与多视角几何经验(内外参标定、相机坐标系下的动作 / 位姿表示)；\n3. 有真机硬件集成经验,熟悉主流机械臂 SDK(Franka / UR / ARX / AgileX 等)与深度相机(如 RealSense)；\n4. 有合成数据生成 / 人手视频到机器人数据 (human-to-robot) 合成经验,熟悉渲染、深度估计、视频 inpainting、SAM 等分割工具链；\n5. 熟悉 flow matching / diffusion policy 等连续动作生成方法的工程实现；\n6. 有机器人、机器学习相关顶会顶刊论文(CoRL / RSS / ICRA / NeurIPS / ICLR / CVPR 等)或高影响力开源项目贡献。\n","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7654529166725548334","sourceKey":"shlab_social","company":"上海AI实验室","title":"具身仿真数据研究工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7654529166725548334?mode=social","duty":"1. 研究多样化的机器人操作场景搭建（机械臂、灵巧手、移动底盘等），设计物体交互的逻辑与剧本；\n2. 研究并设计高效的视觉与轨迹数据合成策略，包括场景布局自动随机化、物理属性扰动以及多模态传感器仿真（RGB/D/触觉），分析数据分布对下游策略性能的影响；\n3. 配合算法团队，分析合成数据在真实机器人上的泛化性瓶颈，提出改进数据生成策略的学术方案。","requirements":"1. 机器人、自动化、计算机等相关专业在读本科及以上学历，了解机器人学基础；\n2. 熟练使用 Isaac Sim 或同类型仿真器，能用 Python 编写场景脚本与数据导出流程；\n3. 具备良好的实验记录与分析习惯，能系统性地比较不同数据生成策略的效果。\n\n加分项：\n1. 有 Isaac Sim、MuJoCo 等多仿真器使用经验，熟悉 USD 或 PhysX 特性；\n2. 了解领域随机化、数据增广在 Sim-to-Real 中的应用，或有相关项目/论文经历；\n3. 发表过机器人学习或仿真相关论文，或参与过具身智能数据集的构建。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7654036886407448875","sourceKey":"shlab_social","company":"上海AI实验室","title":"具身智能算法研究员","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7654036886407448875?mode=social","duty":"1. 负责强化学习核心算法研究，聚焦低容错、高风险环境下的样本高效学习与策略稳健性，推动算法在物理系统上的可靠落地；\n2. 研究强化学习与具身智能体系统的耦合，探索感知—决策—执行闭环中的策略学习、长程任务规划与多模块协同优化方法；\n3. 跟踪和评估业界前沿研究进展,提出原创性算法方案,并通过顶级学术会议、专利或开源项目沉淀研究成果,形成技术影响力；\n4. 协同工程团队，推动研究成果在真机系统上的部署验证与创新应用展示。","requirements":"1. 计算机、人工智能、机器人相关专业博士学历,具备扎实的强化学习理论基础与研究功底；\n2. 熟悉具身VLA，WAM等模型，有机械臂操作相关经验；\n3. 理解强化学习核心算法(如 PPO、GRPO、Pi0.6等),对真实世界环境下的探索效率与安全性有认知；\n4. 熟练掌握 Python / PyTorch 等编程语言与深度学习框架,具备较强的算法实现与实验设计能力；\n5. 在 NeurIPS / ICML / ICLR / CoRL / RSS / ICRA 等顶级会议或期刊发表过强化学习相关论文。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7654035482623789375","sourceKey":"shlab_social","company":"上海AI实验室","title":"具身智能系统工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7654035482623789375?mode=social","duty":"1. 负责具身智能体操作框架的架构设计与研发,涵盖框架搭建、模块优化、接口标准化及跨任务通用能力建设,支撑多种下游操作任务的快速适配与落地；\n2. 主导操作框架内的数据采集、管理与处理工作,包括采集方案设计、数据清洗与标注规范制定、数据闭环 pipeline 搭建,以及大规模操作数据的质量管控与高效复用；\n3. 跟踪和评估业界最新研究与技术进展,设计、迭代和维护相关算法框架,推动框架在真机系统上的集成、优化与部署；\n4. 协同算法团队,推动真机部署、开源开放及创新应用展示等项目。","requirements":"1. 计算机、人工智能、机器人或相关专业本科及以上学历,有相关方向实习/工作经历者优先；\n2. 对具身智能、多模态大模型或智能体系统有整体认知,对数据驱动的算法迭代与框架设计有一定理解和思考；\n3. 熟悉数据采集与处理全流程,具备大规模数据 pipeline 设计、质量管控经验,了解多模态数据(图像、视频、力觉、轨迹等)的对齐与融合方法；\n4. 熟练掌握 Python / PyTorch 等编程语言与深度学习框架,具备较强的工程实现与框架开发能力,代码规范、可维护性强；\n5. 熟悉 CUDA、ROS 等技术栈,具备较好的系统优化与底层开发能力。\n\n加分项: \n1. 有相关研究经历,或在 CVPR / NeurIPS / AAAI / ICLR / CoRL 等顶级学术会议发表过文章;\n2. 参与过相关数据集与基准(Benchmark)搭建、真机系统优化部署或开源项目贡献者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7651889731673000238","sourceKey":"shlab_social","company":"上海AI实验室","title":"机器人算法工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7651889731673000238?mode=social","duty":"1. 全身运动控制与 RL 研究： 基于强化学习开发机器人的全身运控策略，设计状态空间与动作空间；\n2. 训练框架搭建： 使用 Isaac Gym / Mujoco MJX 等 GPU 并行仿真环境，支持可扩展的 RL 算法训练，优化样本效率与收敛速度；\n3. Sim-to-Real 迁移： 鲁棒部署研究，利用系统辨识缩小仿真与真实平台差异；\n4. 实机部署与调试： 将训练策略集成到实时控制框架（ROS 2 + 实时内核），确保控制频率 ≥ 1kHz；\n5. 混合控制架构： 将 RL 生成的高层动作（例如质心轨迹、足端落点）与传统 MPC/WBC 底层控制器结合，保证物理可行性和关节力矩平滑；\n6. 算法创新： 跟踪前沿工作，探索本体世界模型研发。","requirements":"1. 硕士及以上学历，机器人学、控制工程、计算机科学等相关专业，博士优先；\n2. 精通 C++ 和 Python，熟悉 Linux 环境下的实时编程；\n3. 强化学习基础扎实： 深入理解RL常用算法原理，熟练使用至少一种 RL 框架（RLlib, Stable-Baselines3, SampleFactory）；\n4. 机器人学基础： 熟悉 运动学（正逆解、雅可比）、动力学（拉格朗日/牛顿欧拉）、刚体变换、足式机器人步态规划；\n5. 仿真经验： 熟练使用 Mujoco 或 Isaac Gym 进行复杂人形机器人模型（自由度 ≥ 20）的仿真与训练；\n6. 实机经验： 至少将一种 RL 策略部署到 真实腿足机器人（人形或四足）。\n\n加分项：\n1. 熟悉全身控制 (WBC) 或 MPC，并能将其与 RL 结合；\n2. 有人形机器人 DRL 开源项目贡献 或 顶级会议论文（CoRL, ICRA, RSS）关于 DRL for locomotion；\n3. 熟悉 硬件在环 (HIL) 测试，能快速定位实机中的抖动、关节过热、足底打滑等问题；\n4. 了解 C++ 实时控制系统（如使用 Xenomai, Preempt-RT, 或 ROS 2 的实时优先级）。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7651886233359485247","sourceKey":"shlab_social","company":"上海AI实验室","title":"机器人数据工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7651886233359485247?mode=social","duty":"1. 数据采集与处理系统： 负责优化机器人数据采集、标注、清洗、管理的一体化平台（含传感器数据：激光雷达、RGB-D相机、IMU、力控传感器等）；\n2. 自动化标注与管理： 开发自动化标注工具（2D/3D目标检测框、语义分割、点云跟踪）及数据版本管理（Data Version Control），确保海量异构数据的质量与可追溯性\n3. 数据挖掘与增强： 针对长尾场景，开发数据挖掘和增强策略（如模拟传感器噪声、域随机化），提升算法鲁棒性\n4. 仿真数据管道： 与仿真团队协作，构建仿真数据生产流水线（例如自动生成带真值的合成数据），平衡真实数据与合成数据的配比\n5. 评测基准构建： 建立自动化评测系统，支持算法模型在离线数据集上的回归测试与指标监控\n6. 模型部署支持： 协助算法工程师将数据处理流程集成到前端或云端训练链路","requirements":"1. 本科及以上学历，计算机、自动化、电子工程、数学等相关专业；\n2. 熟练掌握 Python/C++，具备扎实的工程开发能力；\n3. 熟悉ROS/ROS2，理解机器人常见传感器（LiDAR, Camera, IMU, Encoder）的数据格式与时间同步机制；\n4. 熟悉常见数据格式（Rosbag, MCAP, PCD, TFRecord, Parquet）及处理库（OpenCV, PCL, NumPy）；\n5. 有大容量数据处理经验，熟悉分布式计算框架（如Spark, Ray, Dask）及数据库（MongoDB, InfluxDB, Milvus）。\n\n加分项：\n1. 熟悉点云处理（RANSAC, ICP, Filtering）或 3D视觉；\n2. 了解机器人模拟器（Gazebo, Isaac Sim, Mujoco）的数据生成机制；\n3. 有自动驾驶、VLM等相关数据场景落地经验；\n4. 熟悉 MLOps 概念（DVC, MLflow, Kubeflow）。\n","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7651886032015395122","sourceKey":"shlab_social","company":"上海AI实验室","title":"人形机器人移动操作算法工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7651886032015395122?mode=social","duty":"面向真实人形机器人构建 System 0/1/2 一体化移动操作策略栈，主导从数据、训练到真机部署的完整技术链路，研发可在真机上实时运行的全身移动操作策略，并参与顶尖论文、大项目、标杆 demo 与系统级成果交付：\n\n1. 研发基于强化学习的人形机器人基础运控模型，解决移动与操作中的接触响应、力位混合控制与全身协调问题，支撑移动中的双臂操作；\n2. 构建 System 0/1/2 一体化策略框架，打通底层执行、全身 visuomotor policy 与高层任务推理，重点解决长程任务中的动作连续性与失败恢复；\n3. 基于 VLA / WAM / diffusion policy / 模仿学习等研发人形机器人操作模型，探索\"一脑多形\"的跨本体泛化与策略复用；\n4. 建设人形机器人数据闭环，整合人类视频、遥操作、真机/仿真数据与失败样本，支撑基础策略的训练、评测与持续迭代；\n5. 与灵巧手团队协作，将双臂灵巧操作与全身动作生成统一到同一策略框架；推动策略真机部署，解决实时性、系统同步、安全约束与 sim-to-real 等问题。","requirements":"1. 计算机、人工智能、机器人、自动化、控制等相关专业背景，博士或优秀硕士优先；有突出研究成果或丰富真机经验者可适当放宽；\n2. 在强化学习、模仿学习、人形/腿足机器人运动控制、VLA/WAM、diffusion policy、多模态策略学习、sim-to-real 中至少两个方向有深入积累；\n3. 具备真实机器人平台的算法部署、数据采集或实验经验（机械臂、腿足机器人、移动操作平台等任一即可），熟悉运动学、动力学、状态估计、传感器标定与真机安全边界；\n4. 熟练掌握 Python/PyTorch，熟悉 Isaac Lab/Gym、MuJoCo 等主流仿真平台，具备良好的 C++、Linux、ROS/ROS2 开发能力；\n5. 具备从数据、模型、仿真到真机的完整闭环能力，能围绕真机失败案例定位问题并推动系统优化；适应高不确定性、长周期的人形机器人算法研发，愿意长期投入系统建设。\n\n加分项：\n\n1. 有人形机器人或全尺寸腿足机器人的真机部署经验，或完成过移动操作、灵巧手协作、长程任务操作等标杆 demo；\n2. 有机器人基础模型、世界模型、跨本体策略迁移或大规模机器人数据训练经验；\n3. 熟悉遥操作、人类动作捕捉、动作 retargeting 或 sim-to-real 评测流程；\n4. 有高质量机器人软件系统、数据采集/评测系统、模型部署工具链或开源项目经验；\n5. 在 CVPR、ICCV、ECCV、NeurIPS、ICLR、CoRL、RSS、ICRA、IROS、RA-L、T-RO 等会议/期刊有论文发表或核心贡献。\n","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7651885904365914377","sourceKey":"shlab_social","company":"上海AI实验室","title":"灵巧手精细操作算法青年研究员","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7651885904365914377?mode=social","duty":"面向真实机器人构建灵巧手大小脑一体化能力，主导从数据、模型到真机的完整研究链路，研发可在真实灵巧手上实时运行的双臂灵巧操作策略，并产出高水平论文、标杆demo、开源系统或大规模机器人数据集成果：\n\n1. 构建基于强化学习与模仿学习的灵巧手基础运控模型，解决复杂交互场景下的实时运控、柔顺控制与触觉/力觉反馈融合问题；\n2. 基于 VLA / WAM / diffusion policy 等研发双臂灵巧操作策略，重点突破复杂接触下的稳定操作、长程任务中的失败恢复与跨物体泛化，实现仪器设备使用、in-hand manipulation 等桌面级精细操作；\n3. 建设多源操作数据闭环，整合第一视角视频、遥操作、真机/仿真数据与失败样本，支撑策略训练、评测与持续迭代；\n4. 主导大小脑一体化策略的真机部署，解决实时性、手眼标定、力/触反馈、时延与 sim-to-real 等关键问题；与人形机器人团队协作，将灵巧操作能力接入全身移动操作系统；\n5. 主导或深度参与高水平论文、数据集、benchmark、开源系统与标杆机器人 demo 的产出。","requirements":"1. 计算机、人工智能、机器人、自动化、控制等相关专业背景，博士或优秀硕士优先；有突出研究成果或丰富真机经验者可适当放宽；\n2. 在强化学习、模仿学习、灵巧操作、diffusion policy、VLA/WAM、触觉/力觉感知、sim-to-real 中至少两个方向有深入积累；\n3. 具备真实机器人平台的算法部署、数据采集或实验经验（机械臂、移动操作平台、人形/腿足机器人等任一即可），熟悉机器人运动学、动力学、标定与控制接口；\n4. 熟练掌握 Python/PyTorch，熟悉 MuJoCo、Isaac Lab/Gym 等主流仿真平台，具备良好的 C++、Linux、ROS/ROS2 开发能力；\n5. 具备独立科研与系统迭代能力，能从真机失败案例中定位问题并推动数据—模型—评测的闭环优化；适应高不确定性、长周期的真实机器人研发，愿意长期投入高质量研究。\n\n加分项：\n\n1. 在 CVPR、ICCV、ECCV、NeurIPS、ICLR、CoRL、RSS、ICRA、IROS、RA-L、T-RO 等会议/期刊有论文发表或核心贡献；\n2. 有灵巧手、触觉传感器或力控操作平台的真机研发经验；\n3. 有高质量开源项目、机器人 benchmark、遥操作系统或大规模数据处理经验；\n4. 熟悉接触建模、触觉仿真、手部动作 retargeting 或人手到机器人手迁移。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7649790839346481427","sourceKey":"shlab_social","company":"上海AI实验室","title":"算力集群运维工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7649790839346481427?mode=social","duty":"1. 集群全生命周期运维：\n负责大规模AI GPU集群的日常巡检、实时监控与故障闭环处理，覆盖服务器、GPU加速卡、分布式网络及存储等全链路基础设施，确保大模型训练、AI推理等核心业务7×24小时高可用。\n2. 算力资源调度与效能优化：\n主导Slurm、K8s等主流算力调度平台的运维与策略管控。深度监控集群资源利用率与作业运行状态，通过优化调度算法、队列规则及资源配额，系统性提升GPU集群的整体算力效率与业务吞吐量。\n3. 复杂故障应急与根因分析：\n快速响应并主导集群软硬件故障及业务突发问题的应急处理。建立标准化故障分级响应机制，沉淀根因分析与处理经验，构建并持续完善风险预防体系，保障业务连续性。\n4. 可观测性与自动化运维体系构建：\n设计并落地覆盖算力、硬件、网络、存储等维度的全栈监控告警体系。主导运维自动化工具与脚本的开发，实现运维操作、异常告警、数据统计报表的自动化，显著提升运维人效与集群的可观测、可管控水平。\n5. 知识沉淀与内部技术赋能：\n6. 主导运维知识库建设，持续迭代标准化SOP、故障处理手册及环境配置规范。面向内部研发用户提供算力使用最佳实践与技术支持，推动集群使用规范化，加速研发迭代效率。","requirements":"1. 全日制本科及以上学历，计算机、网络工程、电子信息、自动化等相关专业。具备大规模GPU算力集群或同等规模服务器集群的实战运维经验。\n 2. 精通Linux操作系统原理与运维，熟练掌握K8s集群架构及日常管理。具备扎实的系统性能调优、权限管控、日志分析与故障排查能力。\n3. 深入理解GPU硬件体系结构，精通GPU驱动及配套计算加速库的安装部署、版本管理及多版本环境兼容性调试。具备独立诊断和处理服务器硬件及固件级故障的能力。\n4. 熟练掌握Shell、Python或Go至少一种编程语言，具备工程化的脚本与工具开发能力。能独立构建自动化运维、日志分析、算力计量与数据可视化等工具链。\n5. 具备项目全生命周期管理经验，自驱力强，能主动识别并闭环解决集群潜在风险。责任心强，具备出色的跨团队沟通协作能力和复杂项目的落地推动能力。\n\n加分项\n1. 深度参与过K8s容器化环境下的AI算力业务部署与运维，对GPU Operator、Volcano等云原生调度方案有实操经验，精通资源配额、队列策略与任务优先级管控；\n2. 熟悉分布式训练与多机多卡组网原理，掌握高性能通信协议栈，具备实战解决分布式训练中通信异常、训练效率不达预期、负载不均衡等复杂性能问题的经验；\n3. 具备大规模分布式对象/文件存储集群的规划、性能调优与运维经验，能针对性解决AI训练场景下的高吞吐、低延迟存储瓶颈；\n4. 精通服务器硬件参数调优（固件配置、NUMA拓扑、PCIe带宽分配等），能通过基准测试定位并消除硬件性能瓶颈，实现算力最大化释放。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7649605753204279590","sourceKey":"shlab_social","company":"上海AI实验室","title":"机器人运控算法工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7649605753204279590?mode=social","duty":"1. 参与异构智能体（包括轮式，机械狗，人型机器人和无人机）其中几种机器人的规划控制算法设计与开发工作，包括但不限于路径规划、控制器等功能模块的开发；\n2. 开展真机实验，通过实际测试验证控制算法的有效性与稳定性，为算法优化提供数据支持；\n3. 深入研究机器人规控算法，进行算法的改进与创新，提升机器人控制的精度与响应性能；\n4. 进行算法代码的编写、调试与维护，遵循代码规范与项目开发流程，确保算法功能的可靠实现。","requirements":"1. 硕士及以上学历，航空航天、自动化、电子信息、计算机等相关专业，具备扎实的控制理论、计算机编程等专业知识；\n2. 熟悉使用常见的人型机器人，机械狗或PX4 飞控固件无人机；\n3. 熟练掌握 MPC，PID 或 RL based 等至少一种控制算法，能够运用算法解决实际控制问题，有相关项目实践经验者优先；\n4. 具备机器人真机实验经验，能够完成真机规划控制方案落地；\n5. 熟练使用 C/C++、Python 等编程语言，具备良好的代码编写能力与编程习惯。\n\n加分项：\n1. 在 IROS、ICRA、RAL、TRO等机器人领域权威会议或期刊发表过相关论文；\n2. 具有 RoboMaster、Robocon 等机器人竞赛经历。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7649604717500893481","sourceKey":"shlab_social","company":"上海AI实验室","title":"嵌入式软件工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7649604717500893481?mode=social","duty":"1. 负责公司核心产品（机器人、机器狗、无人机、AI算力硬件）底层驱动及嵌入式应用层软件的设计、开发、测试与维护；\n2. 负责基于ARM、DSP或异构多核架构的系统级软硬件联调验证（Board Bring-up），解决复杂的系统级Bug；\n3. 负责各类传感器（如IMU、激光雷达、双目视觉、TOF等）及执行器（如FOC电机驱动）的接口开发与数据融合；\n4. 配合控制算法工程师及AI算法工程师，完成运动控制算法或AI模型在嵌入式边缘算力平台的部署与性能优化；\n5. 参与产品软件系统架构设计，撰写并维护相关的技术设计文档（需求说明、详细设计、测试用例等）。","requirements":"1. 学历及专业： 计算机、电子信息、自动化、通信工程、机电一体化等相关专业硕士及以上学历，特别优秀者可放宽至本科学历；\n2. 行业经验： 具有机器人、机器狗、无人机、智能设备或AI硬件等相关行业的嵌入式软件开发经验；\n3. 编程能力： 精通 C/C++ 语言，具备扎实的数据结构及算法基础，具有良好的代码编写规范；\n4. 操作系统： 熟练掌握至少一种RTOS（如FreeRTOS、RT-Thread、NuttX等）或嵌入式Linux系统开发，深入理解多线程、内存管理及任务调度；\n5. 底层硬件： 熟悉 ARM Cortex-M/A 系列架构及常见微控制器（如STM32、GD32、NXP等）；熟练掌握各类通信总线和外设接口（CAN、SPI、I2C、UART、USB、Ethernet等）；\n6. 动手能力： 能熟练阅读芯片数据手册（Datasheet）及硬件原理图，熟练使用示波器、逻辑分析仪等仪器进行软硬件联合Debug；\n7. 综合素质： 具备极强的责任心和自驱力，良好的团队协作精神，能承受一定的工作压力。\n\n加分项（满足其一即可优先考虑）：\n1. 无人机方向： 熟悉 PX4 或 ArduPilot 等开源飞控代码架构，有实际无人机及周边外设开发经验者优先；\n2. 机器人方向： 熟悉 ROS/ROS2 机器人操作系统，或有四足机器人（机器狗）运动控制、FOC电机控制开发经验者优先；\n3. AI硬件方向： 熟悉边缘计算平台（如Nvidia Jetson系列、瑞芯微RK3588、地平线等），有AI模型（如TensorRT、NCNN等）端侧部署和加速经验者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7649604501611825414","sourceKey":"shlab_social","company":"上海AI实验室","title":"嵌入式硬件工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7649604501611825414?mode=social","duty":"1. 负责机器人主控板、传感器、永磁同步电机驱动等硬件电路的系统性设计与实现，包括系统架构设计、原理图与PCB设计、布局及优化；\n2. 主导关键元器件的选型、验证及技术对接，撰写系统需求、设计方案及相关项目文档；\n3. 完成电路板的硬件调试，并配合软件完成系统联调与测试验证；\n4. 负责EMC/EMI设计与测试，参与系统可靠性分析，解决硬件在开发与量产阶段的问题；\n5. 参与自研机器人、智能穿戴等硬件系统的整体技术把控，跟踪行业前沿技术，支持产品持续优化；\n6. 与嵌入式软件、结构、工业设计等团队紧密协作，参与系统方案评审与产品集成。","requirements":"1. 硕士及以上学历，电子、机电、自动控制等相关专业，2年及以上嵌入式硬件开发经验（优秀者可放宽学历与年限要求）；\n2. 熟悉机器人硬件系统架构，具备扎实的数字/模拟电路基础，熟悉ARM、单片机等平台及外围接口电路设计；\n3. 具备电机驱动（如MOS驱动、变压器设计）和EMC相关经验，有4层及以上高速PCB设计能力，熟练使用Altium Designer、Cadence等工具；\n4. 熟悉常用通信接口（如I2C、SPI、UART、CAN、Ethernet等）与传感器电路，了解伺服驱动与线缆设计，具备硬件调试与焊接动手能力；\n5. 具备良好的系统思维和文档能力，能配合团队完成复杂问题攻关，有机器人、智能硬件或工业电子产品经验者优先；\n6. 具备一定的行业视野，了解机器人领域竞品与前沿技术，有机器人相关经验者优先；\n7. 具备良好的团队协作意识和沟通能力，能适应快节奏、多并行的项目环境；\n8. 有机器人、无人机、智能穿戴等消费电子硬件开发经验。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7646430022349605174","sourceKey":"shlab_social","company":"上海AI实验室","title":"战略研判主管-战略研究中心","city":"上海","category":"业务通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7646430022349605174?mode=social","duty":"1. 政府公文材料撰写：负责起草、审核和修改面向各级政府的汇报材料、请示报告、政策建议等公文；确保公文格式符合公文格式和政府侧话语体系\n2. 政策研究与分析：跟踪国家及地方在人工智能、科技创新、产业发展等领域的政策动态；开展专题研究，形成高质量的政策分析报告和决策建议\n3. 技术内容转化：将团队的技术研究成果转化为适合政府汇报的材料形式；协助技术团队理解政府需求，优化研究成果的呈现方式\n4. 会议组织与材料准备：负责政府会议的材料准备、会务组织和纪要撰写；参与政府对接活动，提供专业的沟通支持\n5. 内部能力建设：为团队提供政府公文写作培训和方法指导；建立公文写作模板和标准化流程","requirements":"1. 硕士及以上学历，计算机科学、数据科学、统计学、应用数学、物理等理工科背景优先\n2. 公文写作能力：精通政府公文写作规范，熟悉政府侧科技类话语体系；具备优秀的文字表达能力和逻辑思维能力\n3. 政策分析能力：熟悉国家及地方科技创新、产业发展相关政策体系；具备敏锐的政策洞察力和分析能力\n4. 技术理解能力：理解人工智能前沿技术的基本原理和应用场景；能够将技术语言转化为政策语言","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7644922829717047578","sourceKey":"shlab_social","company":"上海AI实验室","title":"高校合作与运营负责人（双聘与校招方向）","city":"上海","category":"职能通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7644922829717047578?mode=social","duty":"1. 战略合作与双聘攻坚\n围绕实验室战略协议，推动与顶尖高校的科研合作落地，重点运营双聘专家机制，牵引高校核心师资实质性参与科研攻关。\n2. 人才生态与社群运营\n构建重点高校核心科研人才地图，深度维护教授、青年PI及博士生社群，为高层次人才引进提供持续储备与精准对接。\n3. 校招统筹与品牌建设\n制定校园招聘整体策略，打通关键渠道，策划品牌活动，系统性提升实验室在目标高校科研社群中的影响力与吸引力。\n4. 机制建设与资源统筹\n参与高校合作年度规划，建立规范化项目管理流程，协调多方资源，保障合作项目的体系化推进与交付。","requirements":"任职要求：\nA：基本条件：\n1、硕士及以上学历，人工智能、计算机等科技或管理类专业优先。\n2、5年以上高校合作、科研人才运营或高端校招相关经验。\n3、熟悉国内顶尖研究型大学的科研体系、导师制度及运作规则，具备扎实的高校人脉网络。\nB：核心能力\n1、资源与推动力：能快速链接高校核心圈层，推动双聘等深度合作项目落地，有联合实验室或类似机制运营经验者优先。\n2、人才运营力：熟悉高端科研人才获取路径，具备差异化校招运营与科研品牌建设的方法论。\n3、统筹协调力：擅长跨组织复杂项目管理和资源整合，沟通与高层汇报能力突出。\n4、认同感：对前沿科技趋势和科研创新生态有高度热忱与理解。\n\nC：加分项\n1、具有新型研发机构、重大科研平台或产学研合作运营背景。\n2、在人工智能等前沿领域有高校资源积累。\n3、了解国家人才计划及科研项目协同机制。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7644504289545242934","sourceKey":"shlab_social","company":"上海AI实验室","title":"【高阶岗位】硬件系统青年/资深科学家","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7644504289545242934?mode=social","duty":"1. 嵌入式系统开发\n负责机器人本体嵌入式软件架构设计与开发，包括基于Linux/RTOS的底层驱动开发、实时通信中间件（如ROS/ROS2、DDS）集成、多传感器数据采集与同步模块开发。\n2. 硬件平台搭建与集成\n主导机械臂、轮式机器人、无人机等硬件平台的电控系统设计，完成主控芯片/嵌入式计算单元（如Jetson、RK3588等）的选型、电路设计审查与硬件调试，确保算力与功耗平衡。\n3. 传感器系统融合\n负责可见光相机、红外传感器、深度相机（ToF/结构光）、IMU、激光雷达等多传感器硬件接入与驱动开发，实现多源异构数据的硬件级同步与预处理。\n4. 运动控制与部署\n参与机器人底层运动控制算法部署，包括关节电机控制、轮式/足式底盘驱动、轨迹跟踪与力控模块的嵌入式实现，保障控制实时性与稳定性。\n5. 系统集成与调试\n负责算法团队模型在本体上的部署对接与性能优化，完成软硬件联调、外场测试与问题定位，推动从仿真到实机（Sim2Real）的可靠迁移。\n6. 产品化推进\n参与硬件方案从原型到产品化的迭代，制定可量产的硬件设计规范、测试标准与维护文档，提升硬件系统的稳定性与可维护性。","requirements":"1. 学历背景：\n博士及以上学历，电子信息工程、自动化、计算机、机械电子等相关专业；优秀硕士且有丰富项目经验者可放宽。\n2. 工作经验：\n  - 5年以上机器人导航 / 视觉语言导航 / 多模态算法研发经验\n  - 3年以上技术团队管理经验，有从0到1搭建团队或主导核心项目交付的经验\n3. 技术能力：\n  - 嵌入式软件开发：精通C/C++，熟悉Linux内核、设备驱动开发、实时操作系统（RTOS）；熟练掌握ROS/ROS2框架及通信机制\n  - 硬件设计能力：熟悉ARM/DSP等嵌入式处理器架构，具备PCB设计审查、硬件调试与信号完整性分析能力；了解电源管理、电机驱动等模拟电路设计\n  - 传感器与感知：熟悉常用机器人传感器（相机、IMU、激光雷达、编码器等）的硬件接口与驱动开发，有多传感器时间同步与数据融合经验者优先\n  - 运动控制基础：了解PID、MPC、运动学/动力学建模等基础控制理论，有电机控制、伺服系统调试经验者优先\n  - 通信与接口：熟悉CAN、EtherCAT、RS485、SPI、I2C、Ethernet等常用工业通信协议\n4. 综合素质：\n  - 具备较强的工程化落地能力，能在资源约束下快速推进原型验证与产品迭代\n  - 良好的跨团队协作意识，能与算法、结构、测试团队高效配合\n  - 动手能力强，熟练使用示波器、逻辑分析仪等调试工具，能独立完成硬件故障排查\n5. 加分项\n  - 有机械臂、人形机器人、四足机器狗等复杂机器人本体开发经验\n  - 熟悉嵌入式AI加速（NPU/GPU边缘计算部署），有TensorRT、ONNX Runtime等推理框架的嵌入式优化经验\n  - 掌握运动控制高级算法（如全身控制WBC、模型预测控制MPC、强化学习控制部署）\n  - 有Sim2Real部署经验，熟悉Gazebo、Isaac Sim等仿真平台的硬件在环测试流程\n  - 熟悉功能安全（ISO 13849等）或电磁兼容（EMC）设计规范\n  - 具备团队管理经验或技术方案主导经验","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7644148881353296171","sourceKey":"shlab_social","company":"上海AI实验室","title":"【高阶岗位】世界模型方向Tech Lead","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7644148881353296171?mode=social","duty":"核心目标\n- 构建充分理解物理世界规律、生成物理环境的、原生安全的基础模型和支撑软件系统。\n- 搭建面向科学实验室3D物理环境的生成式基础模型与软件系统；研发面向科学发现的融入物理数据与规律的世界模型。\n岗位职责\n1. 技术战略与架构规划\n- 制定物理世界模型的技术路线图，定义差异化技术方向\n- 设计面向科学发现的多模态模拟器架构\n- 规划物理智能基础模型的技术演进路径，探索替代大语言模型的新一代模型架构\n2. 核心技术研发\n- 领导团队在以下至少一个方向进行深度技术攻关：\n  - 3D空间智能：构建面向物理世界的3D感知、理解与生成能力\n  - 物理世界模型：面向科学发现的融入物理数据与规律的世界模型\n  - 多模态理解与生成：文本、图像、视频、动态场景的跨模态建模\n- 推动生成式AI技术在物理世界模拟中的应用，包括扩散模型、生成对抗网络等前沿技术\n- 负责大模型的微调、优化与部署，构建高效的训练与推理框架\n3. 科研项目与工程落地\n- 主导与中科院、高校等科研机构的合作项目，获取稀缺科研数据资源\n- 将前沿研究成果转化为可落地的工程实现，推动算法从实验阶段到生产环境\n- 构建高可用、可扩展的AI平台，支持大规模物理世界模型的训练与推理\n4. 团队管理与技术领导\n- 组建并管理核心技术团队，制定技术评审与质量把控机制\n- 培养团队技术骨干，建立技术传承体系，提升团队整体研发能力\n- 与其他团队（如操作智能、硬件工程等）协同工作，推动跨领域技术融合\n5. 前沿研究与创新\n- 持续跟踪生成式AI、物理模拟、具身智能等领域的最新进展\n- 评估前沿技术在团队战略方向的应用价值，推动技术创新与突破\n- 代表团队参与学术交流，发表高水平论文，提升团队在学术界的影响力","requirements":"基本要求\n- 国内外知名高校计算机、人工智能、机器人、自动化等相关专业博士学历\n- 同时具备有学术积累和工程化产出能力\n技术能力要求\n- 核心技术栈：\n  - 深入理解大语言模型、扩散模型、生成对抗网络等生成式AI技术\n  - 熟悉多模态融合、跨模态理解与生成技术\n  - 具备物理模拟、机器人控制、3D视觉等相关领域知识\n- 工程能力：\n  - 熟练掌握主流AI开发框架\n  - 具备大规模AI系统设计、优化与部署经验\n  - 熟悉分布式训练、模型压缩、推理加速等技术\n- 研究方向：在以下至少一个方向有深入研究：\n  - 数据工程与大规模数据采集处理\n  - 算法设计与模型训练优化\n  - 多模态生成与物理世界建模\n管理与领导能力\n- 具备技术团队的管理经验，或作为核心骨干承担过技术负责人角色\n- 能够制定清晰的技术路线，有效拆解复杂任务，推动项目落地\n- 具备优秀的沟通协调能力，能够跨团队、跨领域协作\n加分项\n- 在顶会（NeurIPS、ICLR、ICML、CVPR、ICRA等）发表过高水平论文5-10篇\n- 有开源AI项目贡献或技术社区影响力\n- 具备科学计算、物理模拟、计算生物学等交叉学科背景\n- 有实验室科研项目合作经验，熟悉科研数据获取与处理","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7641979533869107483","sourceKey":"shlab_social","company":"上海AI实验室","title":"材料科学数据青年研究员/工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7641979533869107483?mode=social","duty":"- 负责大模型预训练与微调数据的构建，搭建材料AI-ready数据，设计结构化数据、知识图谱等AI-ready数据构建的智能体系统。\n- 对接材料科学一线研究人员与湿实验团队，提炼真实科研需求，设计材料数据标注规则与评估体系。\n- 与预训练团队协同，通过数据迭代优化模型效果。","requirements":"- 计算机科学、材料学、计算物理学等相关专业硕士及以上学历。\n- 扎实的材料科学背景：实际使用过MP、AFlow、NIST、NIMS等材料数据库。\n- 有过材料/化学语言模型（ChemLLM、MolFormer、MatChat 等）或 MatterGen相关工具的实操经验。\n- 具有高通量实验数据解析经验，或参与过自动化实验平台数据对接。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7641171481333958931","sourceKey":"shlab_social","company":"上海AI实验室","title":"【高阶岗位】VLA具身操作智能Tech Lead","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7641171481333958931?mode=social","duty":"1. 技术战略与架构规划\n- 制定VLA技术中长期发展路线图，明确技术攻关方向与产品落地路径\n- 主导VLA技术体系整体架构设计，涵盖视觉感知、语言理解、动作生成全流程\n- 评估技术可行性、风险与商业价值，确保技术路线的先进性与可落地性\n2. 核心技术研发与攻坚\n- 主导VLA核心技术难题攻关，包括：VLA泛化性、世界动作模型协同、多模态语义对齐等\n- 研发端到端VLA架构，实现高层任务规划与低层动作生成的模态对齐\n- 构建物理世界模型（World Model），解决仿真到现实的泛化鸿沟（Sim2Real）\n- 开发扩散/自回归策略生成多模态动作轨迹，满足机器人实时控制需求\n3. 团队建设与管理\n- 负责VLA技术团队的组建、培养与管理，明确团队分工（算法研发、工程实现、系统集成）\n- 建立高效的研发体系与激励机制，打造兼具技术深度与协作能力的核心团队\n- 负责团队人才招聘、培养、绩效评估和职业发展指导\n4. 产品落地与商业化\n- 推动VLA技术在物流分拣、实验室自动化等场景的实际应用与产品化\n- 跨部门协同硬件、软件、产品团队，实现算法、硬件与系统架构的一体化整合\n- 将VLA技术能力转化为产品竞争力，支撑多场景机器人落地应用\n5. 工程与交付保障\n- 建立VLA数据采集、清洗、标注、质量评估体系，优化数据驱动的模型迭代流程\n- 主导算法在真实机器人设备上的部署与性能调优，保障模型在嵌入式系统的实时响应\n- 建立规范化研发机制（代码审查、仿真测试、数据闭环管理）","requirements":"硬性要求\n1. 教育与专业背景\n- 硕士及以上学历（博士优先），计算机科学、人工智能、机器人学、自动化等相关专业\n2. 工作经验\n- 5年以上VLA/多模态算法研发经验，其中至少2年以上技术管理经验\n- 具备VLA项目实际交付经验，有可验证的项目成果（技术报告、项目网站、媒体报道等）\n- 有物流分拣、实验室自动化、仓储机器人等相关场景落地经验者优先\n3. 核心技术能力\n- VLA技术深度：精通视觉-语言-动作多模态融合算法，熟悉CNN/Transformer、扩散模型、强化学习等技术\n- 算法实现能力：熟练运用PyTorch/TensorFlow、ROS 2、MuJoCo等工具框架\n- 工程部署能力：具备CUDA/TensorRT模型加速与部署优化经验，熟悉边缘计算设备优化策略\n- 系统集成能力：熟悉机器人操作系统，具备机器人系统端到端落地能力\n4. 学术成果（学术背景候选人）\n- 在VLA方向发表5-10篇高水平论文（CVPR、NeurIPS、ICML、ICRA、IROS等顶会/期刊）\n- 达到助理教授或副教授级别学术水平\n优先考虑条件\n1. 产业背景优先\n- 在自动驾驶、仓储分拣、家居服务等场景中实现过VLA泛化性应用\n- 有机器人产品量产落地经验或VLA技术平台搭建经验\n2. 海外背景加分\n- 海外高校或产业界工作经验，具备国际视野\n- 熟悉海外VLA技术发展动态，有国际学术交流经验\n3. 领导力与软技能\n- 具备优秀的团队管理、跨部门协作与资源整合能力\n- 强烈的创业精神、责任心与抗压能力\n- 清晰的逻辑思维与高效沟通能力","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7638161559856253220","sourceKey":"shlab_social","company":"上海AI实验室","title":"组织文化岗","city":"上海","category":"职能通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7638161559856253220?mode=social","duty":"1、文化阵地与品牌运营： 构建多维文化传播矩阵，通过新媒体等手段策划并推行文化项目，实现实验室品牌传播与文化传承的深度融合。\n2、组织沟通与信息公开： 搭建多层级员工沟通桥梁，策划并落地“决策透明化”相关机制，打造真实、互信的管理文化与职场氛围。\n3、员工关怀与能量场营造： 整合内外部资源，统筹员工文体活动与健康管理项目；通过陪伴式成长方案，提升员工幸福感与组织粘性。\n4、组织氛围感知与诊断： 运用结构化方法进行组织“体检”，精准感知员工需求与士气波动，输出专项分析报告为管理层决策提供支撑。\n5、大型项目全案策划： 统筹策划并执行年会、运动会、开放日及各类大型展会会务；负责全流程质量管控与传播效果最大化。","requirements":"1、学历背景： 全日制本科及以上学历；具备 3 年以上组织文化或品牌公关相关工作经验。\n2、核心能力： 具备极强的文字功底与活动策划能力，能够独立输出高质量的推文、视频及活动方案；熟悉新媒体运营逻辑。\n3、沟通影响力： 具备出色的组织沟通与资源整合能力，擅长跨部门协调，能够快速与各层级员工建立信任。\n4、综合素养： 性格开朗热情，具备较强的亲和力与同理心；正直诚信，能够在高压环境下保持积极乐观的职业态度。\n5、特质优先： 熟悉互联网文化传播手段；有科技/人工智能行业背景或大型文化项目成功案例者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7637155354942228779","sourceKey":"shlab_social","company":"上海AI实验室","title":"物质科学青年研究员/算法工程师","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7637155354942228779?mode=social","duty":"1、探索人工智能与物质科学相关自然科学研究课题的结合，致力于提出新的研究方法与技术路径；\n2、参与科学智能的大模型开发和训练，开发和优化适用于物质科学问题的AI模型与开源AI工具，持续提升模型性能；\n3、跟踪国际前沿研究动态，推动研究方向的拓展与深化，打造和提升行业技术影响力。","requirements":"1、具有物理、计算化学、计算机科学、人工智能、数学等相关专业博士学位；\n2、对AI for science领域的前沿研究充满热情，渴望通过技术推动科学进步，在相关领域有突出研究成果，如Nature、Science或重要子刊、PR系列上的论文发表，或发表人工智能领域顶会论文；\n3、拥有良好的沟通与团队协作能力，能够与跨学科团队高效合作；\n4、具备极强的自主探索、解决问题的能力和精神，针对研究过程中遇到的实际问题能够自主寻找解决方案。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7626655853009406217","sourceKey":"shlab_social","company":"上海AI实验室","title":"保密管理岗-保密办公室","city":"上海","category":"职能类","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7626655853009406217?mode=social","duty":"1. 负责保密日常教育素材收集、保密常识常态化宣贯，完成保密宣传小报制作、国家安全宣传教育日等专项活动策划落地；会同人力资源部门落实年度保密培训计划，完成培训通知、资料发放、组织实施及全流程台账记录归档。\n2. 监督涉密载体接收、登记、传阅、保管、清退、归档、销毁全流程的审批办理与合规检查，规范整理并归档全周期管理材料，确保涉密载体全程可追溯、全环节合规。\n3. 按保密管理要求，常态化开展实验室非密计算机及网络、涉密信息设备的日常使用合规性检查，严格落实专人专管、审查审批、账物相符的管理要求，形成闭环检查记录。\n4. 协助落实年度保密工作计划，常态化开展泄密风险与安全隐患排查，规范做好日常巡查记录；受理各部门日常保密咨询、发布保密风险提醒，指导协助各部门规范处理涉密事项。\n5. 配合完成上级单位保密专项检查、机构保密自查自评、问题整改落实等全流程工作，规范整理归档相关材料，确保各项工作符合上级保密管理要求。","requirements":"1. 学历专业：硕士及以上学历，保密管理、行政管理、法学、信息安全、档案管理等相关专业优先。\n2. 经验背景：3 年及以上保密管理、涉密合规相关工作经验；有科研机构、高新技术企业、军工单位、政府事业单位保密管理工作经验，熟悉人工智能科研场景保密要求、持有保密管理相关资格证书者优先。\n3. 专业技能：精通 Office 办公软件，具备宣传物料制作、台账规范化管理、公文撰写能力；熟练掌握国家保密法律法规，熟悉涉密载体、涉密信息设备与网络的保密管理规范，掌握保密检查、风险排查的核心流程与方法。\n4. 核心素养：具备极强的保密意识与底线思维，严守保密纪律，原则性强；工作细致严谨、责任心强，具备良好的沟通协调、闭环执行与问题排查能力；抗压能力强，可适配阶段性高强度专项工作，具备快速学习与合规落地能力。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7615234376275773734","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型训练算法工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7615234376275773734?mode=social","duty":"1.负责垂直领域大模型的全流程训练工作，独立执行增量预训练（CPT）、监督微调（SFT）及强化学习对齐（RLHF/DPO）任务\n2.负责高质量训练数据的构建与清洗，包括预训练语料的清洗过滤、SFT指令数据的构造与配比、偏好数据的生成\n3.基于Ascend NPU/NV GPU平台，使用Megatron-LM、veRL、LLaMA-Factory等框架进行模型训练与性能调优\n4.监控训练过程，及时发现并解决Loss异常、梯度爆炸等常见训练问题，产出实验分析报告\n5.参与模型评测工作，根据评测结果调整数据配比与超参数，持续提升模型在垂域的效果\n6.跟踪大模型训练领域前沿进展，复现SFT/RLHF相关论文算法，并尝试应用到业务场景中","requirements":"1.计算机、人工智能、数学等相关专业硕士及以上学历，具备1~2年NLP或大模型算法工作经验\n2.熟悉Python、PyTorch，对Transformer架构原理（Attention、RoPE等）和主流开源LLM（Qwen、LLaMA、InternLM等）有深入了解\n3.具备大模型（7B及以上）微调实战经验，并具备以下任一方向的技术积累：\n-预训练/CPT方向：熟悉分布式训练基础（DP/TP/PP），有使用Megatron-LM或DeepSpeed进行多机多卡训练的经验\n-后训练方向：熟悉SFT、RLHF、DPO等算法流程，有过完整的模型精调与对齐实践，了解PPO算法细节\n4.具备良好的实验习惯，能够独立设计对比实验，对数据质量和超参敏感，能通过Badcase分析定位问题\n5.有大模型相关的开源项目贡献、顶会论文发表或知名比赛（Kaggle、天池等）获奖经历者优先\n6.具备团队协作意识，能够快速适应业务迭代节奏","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7595097499736639753","sourceKey":"shlab_social","company":"上海AI实验室","title":"AI平台产品经理 - 科研产品平台部","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7595097499736639753?mode=social","duty":"面向科研工作者和专业用户，参与AI科研产品及大模型产品的建设，推动模型、Agent、工具、数据和工作流转化为易用、可信、可评估的产品能力。\n既能理解用户，又能理解AI：不仅能够撰写需求文档，还能借助AI编程工具快速验证想法，并通过系统评测判断产品是否真正有效。\n\n岗位职责\n1. 负责AI科研产品竞品研究、技术趋势分析、用户研究、需求分析、产品规划、方案设计和迭代落地。深入科研人员和专业用户的真实工作流程，识别高价值任务、关键痛点和AI可介入环节。\n2. 参与科学发现平台产品建设。将大模型、工具调用、知识检索、数据分析和智能体能力转化为用户可理解、可操作的产品体验。\n3. 设计核心使用链路和关键交互，持续优化产品的上手效率、任务完成质量和用户体感。使用AI编程和原型工具快速构建可交互原型，完成需求验证、方案比较和用户测试。\n4. 建立AI产品评测体系，从任务完成度、准确性、稳定性、可用性、效率和用户感知等维度评价产品效果。设计典型任务集、评测样本、基线和验收标准，协同算法、研发和科研团队持续优化模型及产品表现。\n5. 跟踪用户行为、访谈反馈和评测结果，识别模型能力与用户需求之间的差距，推动产品闭环迭代。\n6. 参与竞品研究和技术趋势分析，对大模型、Agent及AI科研产品的发展有独立判断。\n \n","requirements":"1. 本科及以上学历，2年以上AI产品、专业工具、平台产品或复杂用户产品经验。\n2. 具备较强的用户洞察、需求分析和产品设计能力，能够将复杂能力转化为清晰易用的产品。\n3. 对 Agent、大模型、RAG工具调用及模型评测有基本理解，能够与算法和研发团队有效协作。\n4. 具备完整产品经验，能够从问题定义、方案设计、开发跟进、上线验证到数据复盘推动闭环。\n5. 具备较强的结构化分析和逻辑表达能力，能够明确产品目标、使用场景和验收标准。\n6. 对产品体验敏感，能够发现交互摩擦、结果不可信和用户预期落差等问题。\n7. 主动性强，善于在不确定条件下快速验证，而不是等待所有信息完备后才开始行动。\n8. 对科研工作方式和AI for Science有兴趣，愿意持续学习不同学科的任务特点。\n\n优先条件\n- 熟练使用Cursor、Claude Code、Codex等AI编程工具，能通过Vibe Coding快速完成可交互原型或小型产品验证；\n- 有大模型产品评测、模型能力评估、Agent评测或复杂任务验收体系建设经验；\n- 有AI助手、工作空间、专业软件、开发者工具或生产力产品经验；\n- 有科研工具、数据分析、知识管理或AI for Science相关产品经验；\n- 有较强的用户产品体感，能够同时关注功能价值、交互体验和结果可信度；\n- 具备基础编程、数据分析或实验设计能力。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7594391555437480202","sourceKey":"shlab_social","company":"上海AI实验室","title":"GPU平台研发工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7594391555437480202?mode=social","duty":"1. 参与 AI 算力云原生平台整体架构设计与核心模块研发，负责训练调度、资源管理等关键子系统的设计与实现，支撑万卡级 GPU/NPU 集群的稳定运行与资源效率持续优化；\n2. 深度参与 Kubernetes 调度器的定制化开发，负责 AI 训练场景下的优先级调度、资源抢占、Gang 调度及弹性伸缩能力建设，满足大规模分布式训练与推理需求；\n3. 深度参与 AI 训练任务运行稳定性与可观测性能力建设，设计并实现基于硬件、通信及调度事件的监控、告警与故障诊断机制，提升任务异常发现效率与根因定位能力；\n4. 持续跟进云原生 AI 领域前沿技术方向（如异构算力编排、Serverless 训练等），推动技术方案的工程化验证与落地，并参与 CNCF 等开源社区的技术交流与贡献。","requirements":"核心能力：\n1. 计算机相关专业本科及以上学历，3–6 年云原生或分布式系统研发经验，参与过至少一个中大型容器平台或基础设施系统的建设；\n2. 精通 Golang 系统编程，熟悉 Kubernetes 核心组件原理，具备调度器扩展、调度插件或设备插件开发经验；\n3. 熟悉 Kubernetes 调度与资源管理机制，有 Volcano / Kubeflow / Argo 等 AI 云原生框架使用或开发经验者优先；\n4. 熟练使用 Prometheus + Grafana 构建监控与告警体系，具备性能瓶颈分析与告警规则设计经验；\n5. 具备较强的问题分析与系统定位能力，能够独立完成复杂调度异常、资源争用或性能问题的根因分析与修复。\n加分项：\n1. 有 AI 训练平台或大模型训练系统建设经验，熟悉 PyTorch 分布式训练原理；\n2. 参与过 Kubernetes 或云原生相关开源项目贡献（如 SIG-Scheduling / SIG-Node）；\n3. 熟悉 eBPF、内核调度或系统级监控技术，具备复杂系统深度诊断能力。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7586993002837641482","sourceKey":"shlab_social","company":"上海AI实验室","title":"推理框架开发工程师- 系统平台","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7586993002837641482?mode=social","duty":"1. 参与各种AI加速芯片接入深度学习训练与推理框架的开发工作；\n2. 运用编译、融合算子等多种技术手段，加速各种AI加速芯片上的大模型训练推理；\n3. 其他相关前沿技术的调研与运用。\n\n\n","requirements":"1. 具有良好的编程习惯，熟练使用Python/C++ 语言，有较强的debug能力；\n2. 熟悉大模型推理算法，熟悉一种或者多种推理框架（vllm, lmdeploy, sglang, lightllm等）；\n3. 对深度学习训练框架有较深理解与实践（包含不限于深度学习框架：Megatron，Pytorch，TF，JAX）；\n4. 较强的自驱动力，对先进技术有浓厚兴趣；\n5. 有较强的团队精神和沟通交流能力。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7586567008909773098","sourceKey":"shlab_social","company":"上海AI实验室","title":"前沿AI风险算法研究员","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7586567008909773098?mode=social","duty":"1. 针对超级智能体、前沿AI智能体及AI4S智能体，研究其潜在的内生未知风险（如目标偏移、权力寻求、策略欺骗、模型逃逸等），建立具备前瞻性的风险识别、建模与形式化分析的理论框架；\n2. 设计并开发算法与系统，用于预测、评估和量化前沿AI系统在高度复杂、开放或对抗性环境下的极端风险场景与连锁效应，构建风险预警指标体系；\n3. 开展对大语言模型、自主智能体等前沿AI系统的安全性评估，推动风险防御从“事后治理”转向“前瞻预测”的研究范式突破；\n4. 研究针对超级智能和前沿模型的创新性安全对齐与风险控制方法，探索可控、可靠、可中断的人工智能架构与干预机制；\n5. 跟踪国际AI安全与风险研究最新进展，参与高水平学术交流与协作，并推动在国际顶级AI/安全会议或期刊上发表研究成果。","requirements":"1. 硕士及以上学历，计算机科学、人工智能、网络安全、数学或相关专业；\n2. 精通AI技术，对大语言模型、强化学习智能体及多智能体系统的前沿技术有深刻理解；\n3. 具备出色的数学建模或概率推理能力，能够对模糊、不确定的风险进行结构化定义与量化分析；\n4. 具备优秀的Python编程能力及AI训练框架使用经验，有处理复杂实验与仿真的能力；\n5. 具备优秀的英文文献阅读、技术研判与学术交流能力；\n6. 满足以下至少一项专业相关能力：具有AI安全对齐、AI4Science、前沿风险等相关领域的研究或项目经验；具备复杂系统建模、因果推断、形式化验证或高风险系统可靠性分析的研究背景；有深度参与大语言模型、自主智能体或AI4Science项目研发的经验，并对其潜在风险有深入思考。\n\n加分项：\n1. 在人工智能、机器学习领域的顶级会议或期刊（如NeurIPS, ICML, ICLR, AAAI, JMLR）上发表过相关论文；\n2. 具备跨学科建模能力，对超级智能风险、AI安全治理等宏观议题有系统性的思考和见解。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7585179885099944238","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型攻防算法工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7585179885099944238?mode=social","duty":"1. 研究并构造针对大语言模型的攻击方法，包括 jailbreak、提示注入、越狱构造、模型欺骗等；\n2. 搭建攻防评测系统，自动化运行各种恶意 prompt、隐蔽攻击、长上下文攻击等手段，识别模型漏洞；\n3. 分析攻击样本与模型行为，定位安全薄弱点，推动安全可信AI研发；\n4. 跟踪国际前沿的 LLM 攻防研究、越狱技术、对抗样本生成方法，并转化为内部测试能力；\n5. 与安全对齐、预训练团队协作，在模型迭代过程中持续进行安全性回归测试。","requirements":"1. 在大模型攻防、越狱攻击等方向有研究或工程经验；\n2. 理解大模型架构与推理机制，熟悉常见安全漏洞（幻觉、有害输出、归纳偏差等）；\n3. 熟练使用 Python，有能力构建自动化攻防测试工具链；\n4. 善于分析模型行为，能从攻击结果中抽象出可复用的漏洞模式；\n5. 有红队经验、安全攻防竞赛经历或安全研究背景者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7585179064547690778","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型数据算法工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7585179064547690778?mode=social","duty":"1. 负责大模型预训练与微调数据的构建，包括数据采集、清洗、去重、过滤、打标、质量评估等全流程；\n2. 构建高效的数据处理与分发管道，支持 TB–PB 级数据量的处理与管理；\n3. 开发数据质量监控体系，识别低质量、有害、重复、偏见数据并进行修复；\n4. 与训练团队协作，通过数据实验发现提升路径，持续优化数据方案。","requirements":"1. 熟练掌握 Python / SQL / Spark / Ray 等数据处理工具；\n2. 熟悉互联网文本数据、数据过滤策略、语言模型数据构建规范；\n3. 有自动化数据清洗、文本分类、质量检测等经验者优先；\n4. 具备团队协作和文档能力，能维护清晰的数据版本和数据血缘。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7585176321564166451","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型架构研究员","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7585176321564166451?mode=social","duty":"1. 负责新一代大模型架构的设计与验证，包括但不限于 Transformer 替代架构、混合架构、记忆增强架构等；\n2. 围绕长上下文、记忆能力、持续学习能力等关键方向，设计实验方案并与现有 Transformer 基线进行系统对比；\n3. 将研究原型工程化，与训练工程、Infra 团队协作，完成从小规模原型到 8B 级模型的端到端实验流程；\n4. 持续跟踪国内外前沿研究和开源项目，评估技术路线可行性，并提出架构演进建议了；\n5. 输出技术文档和内部分享，沉淀模型架构设计规范、实验结论和最佳实践。","requirements":"1. 计算机科学、数学、电子工程等相关专业硕士及以上学历，博士优先；\n2. 扎实的深度学习理论基础，熟悉主流大模型架构（Transformer、Mamba/SSM、RNN/RWKV 等）及其变体；\n3. 在下述至少一类方向有深入经验：模型架构设计、长序列建模、记忆机制、持续学习 / 终身学习；\n4. 熟练使用 PyTorch / TensorFlow 等深度学习框架，有从 0 到 1 搭建模型结构和训练代码的经验；\n5. 具备较强的科研能力和工程落地能力，有顶会论文或大规模模型项目经验者优先；\n6. 具备良好的沟通协作能力和自驱力，乐于在不确定性较高的前沿方向探索。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7585174467577874739","sourceKey":"shlab_social","company":"上海AI实验室","title":"AI基础设施研究员/工程师","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7585174467577874739?mode=social","duty":"1. 负责大模型训练所需的底层基础设施建设与维护，包括 GPU 集群、存储系统、任务调度与资源管理等；\n2. 与训练工程、模型研究团队合作，优化分布式训练作业的部署流程，提高集群资源利用率与稳定性；\n3. 搭建训练任务的监控与告警体系，对 GPU 利用率、网络带宽、IO 性能等关键指标进行观测和调优；\n4. 参与建设内部 AI 平台工具（如一键提任务、实验管理、日志系统等），提升研发团队整体效率；\n5. 编写并维护相关技术文档和运维手册，持续改进系统的可靠性与可维护性。","requirements":"1. 计算机、软件工程、网络工程等相关专业硕士及以上学历；\n2. 熟悉 Linux 操作系统，精通至少一种后端编程语言（如 Python / Go / C++），有分布式系统开发经验；\n3. 熟悉主流容器与编排技术（Docker、Kubernetes 等），了解常见任务调度与资源管理框架（如 Slurm、K8s Operator 等）者优先；\n4. 对GPU计算、分布式训练、网络与存储有基本理解，有大规模训练平台或云原生平台建设经验者优先；\n5. 具备良好的问题定位与性能调优能力，能在复杂系统中快速排查并解决问题；\n6. 具备良好的沟通与协作能力，能够支持多团队协同工作。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7579187048109869375","sourceKey":"shlab_social","company":"上海AI实验室","title":"解决方案顾问","city":"上海","category":"业务通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7579187048109869375?mode=social","duty":"岗位说明：\n结合实验室的科研方向和科研成果完成应用场景发掘、梳理和设计\n深度参与AI相关的解决方案设计与文档编写，并结合客户需求完成业务方案和技术方案的细化\n协助团队完成客户技术交流，通过原型演示等方式清晰传递方案价值，推动项目落地\n跟踪全球AI技术动态及行业应用趋势，形成结构化的研究报告，支撑业务决策\n\n","requirements":"职位要求：\n5年以上相关工作经验；具有制造、金融、供应链、能源领域管理咨询经验优先\n精通Office办公软件，擅长结构化表达复杂技术逻辑，具备高质量方案文档编写经验优先\n具备优秀的沟通能力、团队协作意识及快速学习能力，对AI技术应用场景有敏锐洞察力\n硕士及以上学历，计算机科学、人工智能、电子信息、数学等相关专业优先\n","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7574396982888139014","sourceKey":"shlab_social","company":"上海AI实验室","title":"生命科学青年研究员/算法工程师","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7574396982888139014?mode=social","duty":"1. 负责面向生命科学的多模态大模型设计与训练。融合生物医学文献、组学及分子结构数据，构建兼具科学推理能力与微观物理表征能力的基座模型，支持蛋白质、核酸及小分子等场景的研究；\n2. 设计专用于生命科学研究的智能体协作模式，模拟科研专家的思考路径。例如：构建能自动拆解复杂生物学问题、执行深度文献调研、构建知识图谱、提出科学假设的Agent系统；\n3. 探索大模型在生物通路分析、靶点发现、作用机理推演等场景下的长链条推理能力，提升科学结论的可解释性与准确性；\n4. 跟踪 AI4S 领域动态，参与团队技术讨论，针对生命科学领域重要的问题提出创新 AI 解决方案, 推动技术在真实科研场景中的落地。","requirements":"1.教育背景：计算机科学、人工智能、或计算生物、计算化学背景但具备扎实深度学习能力的硕士/博士；\n2.熟悉大模型、多智能体优化相关理论；对大语言模型（如 GPT 系列、Transformer 架构）或者 AlphaFold、ESM 等生物大模型原理有深入理解；\n3.具有很强的发现问题、解决问题的能力，以及扎实的 Coding 实现能力（Python/PyTorch；\n4.相信AGI, 热爱科学探索，具备极强的问题拆解能力，愿意为了解决生命科学的本质问题而不断拓展技术边界，致力于用 AI 加速生命科学的新突破。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7563274661065886006","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型训练框架算法工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7563274661065886006?mode=social","duty":"1、分布式训练框架开发：主导或深度参与书生系列大模型训练框架的设计、实现与迭代，覆盖多种任务（预训练、SFT、RL等）和多种模态（语言、视频、音频等）。\n2、性能极致优化：深入分析训练瓶颈，对计算（GPU/NPU）、通信（NCCL/RDMA）、存储（IO）和内存进行系统性优化，包括不限于算子融合、显存优化等技术。\n3、稳定性与可靠性保障：构建高可用的训练系统，确保超大规模集群上长时间训练的稳定性。\n协作与支持：与模型研究团队紧密合作，理解其需求并将其转化为框架特性，为研究员提供高性能训练解决方案和技术支持。\n4、技术前瞻性研究：跟踪业界最新技术动态，探索并引入新的并行策略、编译技术和硬件协同设计，保持框架的技术领先性。","requirements":"1、计算机科学、人工智能或相关领域的本科及以上学历。\n2、拥有PyTorch开发或深度定制经验，熟悉其自动微分、计算图、张量计算等核心机制。\n3、有使用Deepspeed、FSDP、Megatron等框架进行大模型分布式训练的实际项目经验。\n\n加分项：\n1、熟悉GPU/NPU硬件架构，有CUDA/OpenMPI内核开发或性能剖析经验（使用Nsight, Triton等工具）。\n2、具备分布式系统知识，熟悉NCCL、MPI、gRPC等通信库，对RDMA有了解者优先。\n3、参与过知名深度学习框架（PyTorch, TensorFlow）或大规模分布式训练系统的开源贡献。\n4、强烈的责任心、出色的分析和解决复杂问题的能力，对高性能计算充满热情。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7555353313010223401","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型评测算法工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7555353313010223401?mode=social","duty":"1. 参与大模型评测算法的设计与开发，构建贴近用户真实场景的评测基准，涵盖纯文本、图文、视频、Agent等多种场景。\n2. 探索并落地评测分析能力，挖掘模型问题，提出改进建议，支持模型优化迭代。\n3. 调研AI领域最新技术，协助团队引入创新评测方法。\n5. 跟踪AI领域前沿技术，团队协作，完成算法评测相关科研任务。\n","requirements":"1. 计算机、人工智能或相关专业硕士及以上学历，具备算法理论基础。\n2. 研究方向聚焦LLM、MLLM、Agent相关领域，该领域有代表性科研成果。\n3. 具备丰富的大模型或Agent算法评测经验，熟悉CV或NLP评测方法。\n4. 熟悉Python、TensorFlow或PyTorch等开发工具，了解LLM、MLLM、Agent部署等，了解自动化测试流程。\n5. 具备较强的数据分析能力和团队协作意识，善于解决技术问题。\n6. 具备出色的逻辑思维、独立思考能力、分析能力和快速学习能力、对大模型前沿动向有足够的热情和好奇心。\n7. 以上条件满足3点即可。在ICLR、ICML、ACL等顶会发表过论文者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7555079128825104681","sourceKey":"shlab_social","company":"上海AI实验室","title":"系统TesT","city":"上海","category":"业务通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7555079128825104681?mode=social","duty":"Test","requirements":"Test","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7555027739335461139","sourceKey":"shlab_social","company":"上海AI实验室","title":"材料大模型青年研究员/算法工程师","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7555027739335461139?mode=social","duty":"我们正在寻找一位在生成模型与几何深度学习（Geometric Deep Learning）方面拥有深厚背景的人工智能研究员，希望您在扩散模型（Diffusion Models）、图神经网络（Graph Neural Networks）相关及交叉领域具备扎实的理论与实践经验。您将负责领导设计和推进我们的生成式AI算法，专注于其在通用科学领域的应用。\n岗位职责\n1. 深入开展理论算法分析，研究、设计、实现适用于基座模型的架构（如合适的扩散模型和等变图神经网络模型等），并推进其实现与应用；\n2. 结合不同模型的特点，探索多模态、Graph与LLM的融合方法，提升模型表达能力与跨模态推理能力；\n3. 与化科学领域专家协作，将前沿技术应用于关键科学问题，推动AI驱动的科研创新。","requirements":"任职要求\n1. 拥有计算机科学、机器学习、应用数学或相关领域的博士学历（或硕士学历且拥有3年以上相关研发经验）；\n2. 熟练掌握PyTorch等深度学习框架，对Transformer等主流模型有深入理解；熟悉GNN（如MPNN, SchNet, DimeNet, GemNet）及等变神经网络（e3nn, SE(3)-Transformer）的设计与实现；\n3. 能实现高效代码转换，熟悉标准的MLOps工具链（如Git, Docker），具备Diffusion Models，Score-based model，Flow matching等生成模型扎实的理论基础和丰富的实战经验；\n4. 具有出色的数学基础（概率论、随机过程、优化理论），并能一作在顶级会议（NeurIPS, ICML, ICLR）或期刊（TPAMI，Nature/Cell/Science及其子刊）上发表过相关论文。\n5. 具备优秀的解决问题能力、创新思维和沟通能力。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7553291568346728758","sourceKey":"shlab_social","company":"上海AI实验室","title":"智能体算法工程师/青年研究员","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7553291568346728758?mode=social","duty":"1. 参与书生大模型智能体能力建设，负责Agent在搜索、工具调用、生产力办公、代码生成、安全攻防、科学研究等场景下的算法研发与系统实现。\n2. 构建面向复杂任务的智能体训练数据，包括任务轨迹、工具调用链、环境交互数据、多轮推理数据、代码执行数据、安全攻防数据及科学任务数据等。\n3. 研发和优化Agent相关模型能力，包括任务规划、多步推理、长上下文理解、函数调用、工具使用、代码执行、结果校验、自我反思与错误恢复等能力。\n4. 建设智能体评测体系与自动化评测流水线，围绕BrowseComp、SWE-Bench、安全攻防Bench、DeepResearch等任务开展模型能力评测、问题分析和迭代优化。\n5. 推动智能体能力与主线基座模型合版集成，参与模型训练、后训练、数据治理、能力回归和版本交付工作。\n6. 跟踪国内外Agent、代码大模型、安全智能体、科学智能体等前沿技术进展，完成技术调研、方案验证和工程落地。","requirements":"任职要求\n1. 计算机、人工智能、软件工程、网络安全、自然语言处理、机器学习、数据科学、物理、化学、生物、材料等相关专业硕士及以上学历，优秀本科生亦可考虑。\n2. 熟悉大语言模型、Agent、RAG、Tool Use、代码生成、强化学习、后训练、数据合成或自动化评测中的一个或多个方向。\n3. 具备扎实的编程能力，熟练使用Python，熟悉PyTorch、Transformers、vLLM、Ray、Docker、Linux等常用训练与工程工具者优先。\n4. 具备以下经验之一者优先：\n  - 参与过大模型训练、SFT、RLHF/RLAIF、DPO、数据合成或评测体系建设；\n  - 参与过Agent系统、工具调用系统、自动化办公助手、搜索问答系统建设；\n  - 熟悉SWE-Bench、代码生成、代码修复、仓库级代码理解或自动化软件工程；\n  - 熟悉CTF、漏洞挖掘、渗透测试、二进制分析、代码安全或AI安全攻防；\n  - 具备科学计算、科学文献理解、科研工作流自动化、AI4Science相关经验。\n5. 具备较强的问题拆解、实验分析和工程落地能力，能够在快速迭代环境中独立推进任务。\n6. 有顶会论文、开源项目、大模型竞赛、Kaggle/CTF/ACM获奖、知名大模型或Agent项目经验者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7540111744543443250","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型应用算法工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7540111744543443250?mode=social","duty":"1、利用主流AI工具及开发框架，完成解决方案的产品原型开发、测试及优化，确保技术方案的可落地性与创新性\n2、研究相关领域的大模型核心技术，包括：知识与数据的建模与融合、面向设计场景的模型后训练（SFT、PEFT、RLHF等）、结合RAG与智能体（Agent）框架的决策推理\n3、负责垂直领域大模型的训练与优化，包括需求分析、数据集构建清洗合成、模型训练及评估迭代\n4、搭建并优化智能体系统，实现基于模型和算法的辅助决策与自动化\n5、跟踪行业前沿算法，参与面向场景的算法研究与创新，推动相关成果落地 ","requirements":"1、本科及以上学历，计算机科学、人工智能、电子信息等相关专业优先\n2、具有扎实的编程与工程开发能力，熟悉Python、PyTorch，有大模型训练实操经验者优先\n3、具备相关领域知识背景，熟悉工业设计流程与关键技术，能够与大模型技术深度结合\n4、熟悉大模型（LLM、MLLM）底层原理、主流训练框架和技术路线，具备模型训练与部署能力\n5、熟悉RAG、Agent框架及Prompt优化技术，有实际项目经验者优先\n6、发表高质量学术论文或参与过优秀开源项目开发维护者优先","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7535362154582575406","sourceKey":"shlab_social","company":"上海AI实验室","title":"重点研发项目经理TPM（安全）- 项目与资源管理中心","city":"上海","category":"业务通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7535362154582575406?mode=social","duty":"岗位职责：\n1. 负责科研团队重点研发项目工作推进，制定研发型项目管理方案与配套全流程，提升研发项目工作效率并推动落地；协调内外部资源(产研团队、合作企业、政府等相关部门)，确保项目进度、质量与成本可控；识别项目风险，提供预案并解决跨部门协作问题，保障项目按期交付；\n2.支撑科研项目标准化立项与交付全流程，组织项目书撰写、阶段性检查、结题验收等工作；\n3.支持组织管理与运营，包括但不限于团队资源配置与资源协调（设备、算力、人力等）、知识库建设、效能优化等；\n4.支撑开展人工智能产业、科研等决策研究，参与相关文件的起草编制等；\n5.管理并跟进与重点企业、机构的合作，支持研究团队与外部沟通交流。\n\n职位要求:\n1.硕士及以上学历，3年及以上相关工作经验，人工智能、计算机等理工科相关专业优先；\n2.拥有出色的沟通协调能力与跨部门合作能力，能够与不同部门、不同层级的人员进行良好的沟通与协作，协调各方资源，解决项目管理过程中的各种问题；\n3.熟悉AI产品生命周期全流程/模型训练全流程/AI技术治理，并有比较完整的AI项目管理(包含规划、执行、监控等)实践经验优先；\n4.有政府机关、科研事业单位、大型企业等相关工作经验的复合型人才优先；\n5.拥有PMP证书或Scrum Master认证优先。","requirements":"","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7519329796603332901","sourceKey":"shlab_social","company":"上海AI实验室","title":"AI测试开发工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7519329796603332901?mode=social","duty":"1. 独立负责大模型应用产品及 AI 系统的测试开发工作\n2. 全面把握产品功能和非功能质量，对交付质量负责\n3. 负责测试全流程的自动化流水线建设，进行测试方法、测试框架平台等方面的创新和落地\n4. 负责产品迭代中把控研发、测试以及交付过程质量，以及流程质量规范实施","requirements":"1. 计算机及相关专业本科以上学历，在开发测试领域有一年及以上经验\n2. 熟悉测试流程和测试方案设计，熟悉测试自动化开发以及主流 CI 工具框架使用，对自动化需求挖掘、方案设计和实施有深刻认识\n3. 拥有良好的团队协作和沟通能力，较强的质量意识\n4. 在 AI 系统或 AI 应用测试开发、评测等领域开发测试经验者优先","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7493888550514952459","sourceKey":"shlab_social","company":"上海AI实验室","title":"多模态大模型青年研究员/算法工程师","city":"上海","category":"算法类","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7493888550514952459?mode=social","duty":"1. 参与科学多模态大模型的研发，包括但不限于预训练、后训练和评测体系构建。\n2. 参与大模型训练与知识图谱，检索增强生成，多模态学习，强化学习（Reinforcement Learning) 等技术的创新融合；\n3. 构建高质量的大模型数据集，包括但不限于文本，图片，视频，多组学，时空间序列等数据；\n4. 参与大模型技术在科学场景的落地应用。","requirements":"1. 人工智能相关专业，具备扎实的编程与算法基础，科研或工程能力优秀，有产业工作经验优先；\n2. 熟悉人工智能领域的相关研究工作和算法，具有多模态大模型实践经验，具备大模型优化能力优先；\n3. 具备优秀的分析和解决问题能力，良好的团队合作精神及沟通意识。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7493730371797453093","sourceKey":"shlab_social","company":"上海AI实验室","title":"科研规划管理（高峰、数据、智能体、大模型）- 科研规划中心","city":"上海","category":"业务通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7493730371797453093?mode=social","duty":"1. 领域战略规划与解码\n— 参与机构总体战略的制定与迭代，重点负责对二级单元进行战略解码，形成可执行、可衡量的业务发展路径、行动计划与技术路线图；\n— 参与设计并推动战略性业务发展方案，包括资源整合模式与阶段目标设定，确保战略有效落地；\n— 构建战略执行监控与反馈体系，定期开展复盘与校准，保障业务发展与机构宏观战略始终保持对齐。\n2. 领域战略研究与洞察\n— 围绕具体领域开展系统性研究，研判科技产业发展趋势、竞争格局与政策导向，撰写深度战略分析报告，为机构中长期发展决策提供支持；\n— 开展战略推演，进行战略假设验证与迭代跟踪，识别重大风险与战略机遇，定期向决策层提供战略预警和布局建议。\n3. 领域战略落地与业务赋能\n— 深度嵌入科研与业务团队，提供战略分析、路径规划和项目设计等全方位支持；\n— 建立跨单元、跨层级的协同流程，推动战略规划-战略解码-战略落地的一体化运作；\n— 根据业务需要，提升组织战略理解与执行能力，实现业务层面的战略赋能。\n4. 领域战略资源整合与知识运营\n— 体系化梳理领域的战略技术思想和技术观点，定期开展战略进展提炼和总结；\n— 体系化沉淀领域知识，建设并维护领域战略成果与进展知识库。","requirements":"1. 教育背景\n— 硕士及以上学历，人工智能、计算机科学、电子信息、管理科学与工程等理工科相关专业优先，欢迎复合交叉型人才；\n— 具备扎实的研究能力和系统性的思维框架，能够快速学习并掌握新领域知识。\n2. 专业经验\n— 硕士须具备4年以上科技领域战略规划、产业分析、商业咨询或科研管理相关经验，有头部科技企业、知名咨询公司或高水平研究机构工作经历者优先；博士工作年限不限；\n— 对人工智能、前沿信息技术或特定垂直领域具备深厚的行业认知与洞察，能独立开展系统性战略研判并形成可落地的战略建议；\n— 擅长战略研究、战略管理方法论，熟练掌握并实践多种战略分析与管理工具，具备从战略制定到执行推进的全流程经验。\n3. 核心能力\n— 战略思维能力强：能理解抽象的战略意图，将宏观战略转化为清晰可执行的业务方案和行动路径；识别战略执行中的偏差；从局部工作洞察全局价值；\n— 技术理解能力强：针对AI领域（大模型、AI4S、AI安全、算力和数据等任一方向）具有深入认知和判断力；\n— 沟通协调能力强：能与科研人员、管理层高效沟通协作，兼具技术深度与战略视野；\n— 材料撰写能力强：快速理解技术内容，实现战略提炼与总结呈现，具备优秀的文字功底和PPT制作能力；\n— 学习适应能力强：快速学习适应新技术变革，敏捷灵活应对行业发展。\n4. 个人特质\n— 对科技创新和战略管理充满热情，具备前瞻视野和敏锐洞察，能持续跟踪学习新兴技术与发展动态；\n— 结果导向，抗压性强，能适应高强度、快节奏的科研攻关与组织发展环境；\n— 高度责任心和自驱力，善于多任务管理和高效时间规划，具备良好的职业素养与合作精神。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7464047091833604390","sourceKey":"shlab_social","company":"上海AI实验室","title":"重大任务项目经理人-项目经理人与成果转化中心","city":"上海","category":"业务通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7464047091833604390?mode=social","duty":"岗位概述：\n项目经理人的核心使命是在科学世界和产业世界之间架起桥梁，发现并推动具有战略突破潜力的创新项目，需要通过系统的价值发现、精准的团队评估、深度的项目共创，连接顶尖科学家、产业领袖和政策制定者，推动中国科技创新的战略突破。\n岗位职责：\n1. 战略级技术趋势研判与规划\n  1）主导AI for Science、大模型、具身智能等前沿技术的全球趋势分析，评估技术先进性、落地可执行性，制定技术战略路线。识别挑战既有共识、跨越学科边界的颠覆性创新机会；\n  2）深度参与实验室战略决策，结合业务需求与行业动态，输出技术投入优先级建议，支撑高层技术布局决策。\n2. 技术生态构建与资源整合\n  1）在全国范围内发现、评估并筛选优秀科研团队，超越论文数量、获奖数量等指标，深入理解团队的真实研究能力和价值；建立和维护前沿领域的专家顾问网络，定期组织跨界研讨会；\n  2）通过科研专项、算力支持、基金投资等形式与高质量科研团队建立合作，并全程跟进项目里程碑管理，给予项目相关的技术和产业化的战略聚焦和资源支持，从概念到落地全程陪伴项目发展，确保高影响力成果产出。\n  3）在项目中后期，识别成果的产业转化机会，协调产学研合作，推动科研成果的实际应用。\n3. 跨部门协同与创新机制沉淀\n  1）统筹内外部技术资源，主导跨部门协同项目，确保技术战略与业务目标的高度对齐。\n  2）从实践中总结项目管理的方法论，不断完善项目经理人的运作机制，参与创新政策建议。","requirements":"任职要求：\n1. 博士学历优先（特别优秀者可放宽到硕士），人工智能、计算机、物理、化学、材料、生物、医学等理工科专业优先；\n2. 以下任一方向3年及以上工作经验优先：\n  1）科研背景：有学术研究或科技管理/咨询工作经历，特别是跨学科合作经验；\n  2）投资背景：从事早期项目评估、天使投资等，具备识别潜力项目的敏感度；\n  3）产业背景：在高科技企业从事R&D管理、战略规划、技术评估工作，理解技术应用场景；\n  4）项目管理背景：有复杂项目协调推进经验，理解项目管理实质。\n3. 能够快速获取陌生领域核心知识，清晰表达复杂技术概念；\n4. 具备系统性思维，能从复杂信息中抽象核心问题，善于结构化分析；\n5. 谦虚、好奇，愿意从专家和实践中快速学习，乐于跨越舒适区，有推动科学进步的热情；\n6. 诚实、负责，尊重科学伦理，拒绝学术不诚实。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7446231036575648039","sourceKey":"shlab_social","company":"上海AI实验室","title":"重点研发项目经理TPM（大模型、AI4S）- 项目与资源管理中心","city":"上海","category":"业务通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7446231036575648039?mode=social","duty":"岗位职责：\n1. 负责科研团队重点研发项目工作推进，制定项目计划、推进项目执行、日常项目跟进、监控项目风险，确保目标达成；\n2. 统筹项目资源（设备、算力、人力等），发挥有限资源的最大化效益；\n3. 制定科研项目标准化立项与交付全流程，组织项目书撰写、阶段性检查、结题验收等工作；\n4. 支撑开展人工智能产业、科研等决策研究，参与相关文件的起草编制等；\n5. 协助策划、组织和实施科研侧的内外部会议、活动及大型赛事，包括但不限于政府、科研院所、产业界；\n6. 管理并跟进与重点企业、机构的合作，支持研究团队与外部沟通交流；\n7. 负责项目成果发布宣传工作，包括但不限于组织、跟踪、材料收集、对外链接、想法提出等；\n8. 协助项目团队组建，制定研发型项目管理方案与配套全流程，提升研发项目工作效率；\n9. 协助进行团队内部管理，进行团队建设，完善团队内部管理流程，并持续优化；\n\n职位要求：\n1. 硕士及以上学历，工科背景优先；\n2. 3年以上相关工作经验，熟悉项目管理/互联网/AI产品技术等，具有较好的业务、技术理解力;\n3. 对项目管理流程搭建和优化，对产研效能分析和提效有相关思考和实际经验；\n4. 有生态拓展经验优先，有政府机关、科研事业单位、大型企业等相关工作经验的复合型人才优先；\n5. 自驱，自律，具有较强的责任心，抗压能力强，擅长以目标导向的落地执行、问题解决;\n6. 性格开朗，优秀的人际交往、沟通协调能力，具有良好的团队合作精神，能够积极配合相关方的工作；\n7. 具备出色的公文写作能力，能够撰写各类申报材料和报告。","requirements":"","description":"","jdComplete":true,"sourceStatus":"1"}];
